/**
 * The light a planet's block chunks carry, drawn as the world asks. The
 * planet's server bakes each vertex's light as Luanti's smooth lighting
 * gives it: the sky's light (in its colour as well), the light of the light
 * sources about it (lava, torches), and a corner shade, darker where solid
 * blocks crowd the corner. The shade is kept apart so the world can set its
 * strength at run time (`planet.block-shading`, 0 none to 1 Luanti's); the
 * light sources' light, so it can glow as the sky's light fades
 * (`planet.block-glow`, 0 to 2, in the colour `planet.block-glow-color`).
 * A point is lit by the brighter of the sky's light at this hour and its
 * light sources', so at night the ground the sky lit goes dark and the
 * ground about the lava does not, and the lava itself stays bright.
 *
 * The same plugin draws the sky's fill light turned and coloured
 * (skyFill.ts), on the chunks and the far tiles alike.
 *
 * This is the small controller the planet view drives: it fetches the
 * code-split chunk (blockLightChunk.ts) only when the world wants any of
 * them and the visitor's tier draws it, and feeds it each frame how much day
 * there is and the sky fill's change.
 */
import type { Scene } from '@babylonjs/core/scene';
import { parseColor } from '@fivesqd/veml-parse';

/** What a world asks of its blocks' light (read live): the corner shade's strength, 0 to 1; the glow's, 0 to BLOCK_GLOW_MAX; the glow's colour. */
export interface BlockLightAsk {
  shading: number;
  glow: number;
  color: [number, number, number];
}

/** The shell's: Luanti's shade, the light sources' light as it is, a little warm, as firelight is. */
export const BLOCK_LIGHT_DEFAULTS: BlockLightAsk = { shading: 1, glow: 1, color: [1, 0.85, 0.65] };
/** The strongest glow a world may ask for. */
export const BLOCK_GLOW_MAX = 2;

/**
 * The change to the sky's fill light the ground is drawn with (skyFill.ts):
 * straight up in the scene, and what a face turned up and one turned down
 * take on top of the world's hemispheric light, its strength in them.
 */
export interface SkyFillLight {
  up: [number, number, number];
  sky: [number, number, number];
  ground: [number, number, number];
}

/** What the chunk is given each frame: the ask, how much of the day's sky light there is, 0 at night to 1, and the sky fill's change, or null for none. */
export interface BlockLightState extends BlockLightAsk {
  day: number;
  fill?: SkyFillLight | null;
  /** The relief's strength (blockRelief.ts), 0 for none. */
  relief?: number;
}

/** A world's blocks' light, from its hints in force (`ClientHints.Get`): `none` for none, `auto` or anything unreadable for the shell's. */
export function blockLightAskOf(hint: (name: string) => string | null | undefined): BlockLightAsk {
  const read = (name: string, d: number, max: number): number => {
    const v = hint(name);
    if (v === null || v === undefined || v === 'auto') return d;
    if (v === 'none') return 0;
    const x = Number(v);
    return v.trim() !== '' && Number.isFinite(x) ? Math.min(max, Math.max(0, x)) : d;
  };
  let color = BLOCK_LIGHT_DEFAULTS.color;
  const c = hint('planet.block-glow-color');
  if (c && c !== 'auto') {
    const p = parseColor(c).color;
    if (p.form !== 'neutral') color = [p.r, p.g, p.b];
  }
  return { shading: read('planet.block-shading', BLOCK_LIGHT_DEFAULTS.shading, 1), glow: read('planet.block-glow', BLOCK_LIGHT_DEFAULTS.glow, BLOCK_GLOW_MAX), color };
}

export interface BlockLightHandle {
  update(state: BlockLightState): void;
  dispose(): void;
}

export interface BlockLightModule {
  createBlockLightOn(scene: Scene, opts: { engineKind?: string }): BlockLightHandle;
}

/**
 * The planet view's block light: the chunk fetched the first time the world
 * asks for a shade or a glow (and the visitor's tier, `allowed`, draws it),
 * then fed each frame, and let go with `dispose`.
 */
export function createBlockLight(o: {
  scene: Scene;
  load: () => Promise<BlockLightModule>;
  ask: () => BlockLightAsk;
  engineKind?: string;
  track: <T>(p: Promise<T>) => Promise<T>;
  warn: (name: string, detail: string) => void;
  allowed?: boolean;
}): { frame(f: { day: number; fill?: SkyFillLight | null; relief?: number }): void; dispose(): void } {
  let handle: BlockLightHandle | undefined;
  let asked = false;
  let gone = false;
  return {
    frame(f) {
      if (o.allowed === false) return;
      const ask = o.ask();
      if (!handle) {
        if (asked || (ask.shading <= 0 && ask.glow <= 0 && !f.fill && !(f.relief && f.relief > 0))) return;
        asked = true;
        void o.track(
          (async () => {
            try {
              const m = await o.load();
              const h = m.createBlockLightOn(o.scene, o.engineKind ? { engineKind: o.engineKind } : {});
              if (gone) h.dispose();
              else {
                handle = h;
                h.update({ ...ask, day: f.day, fill: f.fill ?? null, relief: f.relief ?? 0 });
              }
            } catch (err) {
              o.warn('veml:planet:block-light-unavailable', String(err));
            }
          })(),
        );
        return;
      }
      handle.update({ ...ask, day: f.day, fill: f.fill ?? null, relief: f.relief ?? 0 });
    },
    dispose() {
      gone = true;
      handle?.dispose();
      handle = undefined;
    },
  };
}
