/**
 * A planet's day. The sun is fixed in the planet's own frame (+y the north
 * pole) while the planet turns under it, eastward, once a day: so it rises in
 * the east and sets in the west, and the side away from it has night.
 *
 * The planet declares, on its `planet:planet`, the length of a day in seconds
 * (`0` holds the sun still), the hour at longitude 0 at the epoch and the
 * latitude the sun stands over at noon (its season), so every visitor reads
 * the same hour off their own clock; the defaults are for what it leaves
 * unsaid. Local time runs ahead of longitude 0's by an hour for every 15° east.
 */
import type { Vec3 } from './planetFrame';

/** What a world says of its day; anything left out is the shell's default. */
export interface DaySettings {
  /** The hour at longitude 0, 0 to 24, now. */
  time?: number;
  /** Seconds a day lasts; 0 holds the sun still. */
  dayLength?: number;
  /** The latitude, in degrees, the sun stands over at noon. */
  sunLatitude?: number;
}

export interface Day {
  /** The hour at longitude 0 at `startS` seconds. */
  hour: number;
  dayLength: number;
  sunLatitude: number;
}

/**
 * The defaults: for a planet that declares no day, the shell's, a visitor
 * arriving at mid-morning and a day of twenty minutes; and the planet
 * profile's, the sun over the equator at noon.
 */
export const DAY_DEFAULTS = { arrivalHour: 10, dayLength: 1200, sunLatitude: 0 };
/** The planet profile's hour at longitude 0 at the epoch, for a planet that declares a day but not its time. */
export const DECLARED_TIME_DEFAULT = 12;

const wrap24 = (h: number) => ((h % 24) + 24) % 24;

/** The hour at a longitude when it is `hour` at longitude 0. */
export const localHour = (hour: number, lon: number): number => wrap24(hour + lon / 15);

/** The day a world asks for, for a visitor arriving at longitude `arrivalLon`: by default mid-morning there. */
export function dayOf(s: DaySettings, arrivalLon: number): Day {
  return {
    hour: wrap24(s.time ?? DAY_DEFAULTS.arrivalHour - arrivalLon / 15),
    dayLength: Math.max(0, s.dayLength ?? DAY_DEFAULTS.dayLength),
    sunLatitude: Math.min(90, Math.max(-90, s.sunLatitude ?? DAY_DEFAULTS.sunLatitude)),
  };
}

/** What a planet declares of its day on its `planet:planet`, each absent where it says nothing. */
export interface PlanetDaySettings {
  dayLength?: number;
  time?: number;
  sunLatitude?: number;
  tidePeriod?: number;
}

/**
 * The day a planet declares (planet profile, "The planet's day"). With a
 * `dayLength` the day is the planet's: `hourAt(day, t)`, with `t` the
 * seconds since 1970-01-01T00:00:00Z by the visitor's own clock, is the same
 * hour for every visitor, `time` at the epoch. Without one the hour is the
 * shell's (`shared` false): mid-morning where the visitor arrives, read on a
 * clock that starts when the view opens. The season is the planet's either way.
 */
export function planetDay(p: PlanetDaySettings, arrivalLon: number): { day: Day; shared: boolean } {
  const sunLatitude = p.sunLatitude ?? DAY_DEFAULTS.sunLatitude;
  if (p.dayLength === undefined) return { day: dayOf({ sunLatitude }, arrivalLon), shared: false };
  return { day: dayOf({ time: p.time ?? DECLARED_TIME_DEFAULT, dayLength: p.dayLength, sunLatitude }, arrivalLon), shared: true };
}

/**
 * The tide's period, and whether it is on the planet's clock (seconds since
 * the epoch, high water at each whole period) or the view's own: as the
 * planet declares it; else half its declared day, or 0, no tide at all,
 * where its sun stands still; else the shell's, half its own day.
 */
export function planetTide(p: PlanetDaySettings): { period: number; shared: boolean } {
  if (p.tidePeriod !== undefined) return { period: p.tidePeriod, shared: true };
  if (p.dayLength !== undefined) return { period: p.dayLength / 2, shared: true };
  return { period: DAY_DEFAULTS.dayLength / 2, shared: false };
}

/** The hour at longitude 0, `timeS` seconds into the day `d`. */
export function hourAt(d: Day, timeS: number): number {
  return d.dayLength > 0 ? wrap24(d.hour + (24 * timeS) / d.dayLength) : d.hour;
}

/**
 * The unit direction toward the sun in the planet's frame, `timeS` seconds
 * into the day `d`: over the place where it is noon, at the sun's latitude.
 */
export function sunDirection(d: Day, timeS: number): Vec3 {
  // Noon is where the sun stands: at longitude 0 when it is twelve there, 15° west of it for each hour later.
  const lon = ((12 - hourAt(d, timeS)) * 15 * Math.PI) / 180;
  const lat = (d.sunLatitude * Math.PI) / 180;
  return [Math.cos(lat) * Math.cos(lon), Math.sin(lat), Math.cos(lat) * Math.sin(lon)];
}
