/**
 * What the sun's shadows draw, and for whom: the rules the planet view puts
 * on its cascaded shadow map, kept here without Babylon so they are tested on
 * their own.
 *
 * - A mesh receives the shadows only where some of it lies within their
 *   reach. Beyond it the cascades hold nothing, so a far tile would work out
 *   four cascades' positions at each vertex and find no shadow; it looks the
 *   same without.
 * - A caster is drawn into a cascade only where its shadow can fall on what
 *   the eye sees through that cascade: its bounding sphere, as the sun sees
 *   it, overlaps the outline of the cascade's slice of the view, and it does
 *   not lie wholly beyond the slice from the sun. Every caster was drawn into
 *   all four cascades, whose squares cover the slices' bounding spheres, so
 *   the blocks behind and beside the visitor were drawn as often as those in
 *   view.
 * - The map is drawn again only when something it shows has changed: the
 *   eye, the view, the reach, the casters, or the sun by enough to shift a
 *   tall tree's shadow by half a texel. A still visitor's map is held.
 */

import type { Vec3 } from './planetFrame';

/** Whether a mesh's bounding sphere, `centre` and `radius`, reaches within `reach` metres of the eye. */
export function withinShadowReach(centre: Vec3, radius: number, eye: Vec3, reach: number): boolean {
  return Math.hypot(centre[0] - eye[0], centre[1] - eye[1], centre[2] - eye[2]) - radius < reach;
}

/** A point through a view matrix as Babylon keeps it: sixteen numbers, row vectors (p' = p · M). */
function inView(m: ArrayLike<number>, p: Vec3): Vec3 {
  const [x, y, z] = p;
  return [x * m[0]! + y * m[4]! + z * m[8]! + m[12]!, x * m[1]! + y * m[5]! + z * m[9]! + m[13]!, x * m[2]! + y * m[6]! + z * m[10]! + m[14]!];
}

/** The convex hull of points in the plane, anticlockwise (Andrew's monotone chain). */
function hull(points: Array<[number, number]>): Array<[number, number]> {
  const p = [...points].sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  if (p.length < 3) return p;
  const cross = (o: [number, number], a: [number, number], b: [number, number]) => (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
  const lower: Array<[number, number]> = [];
  for (const q of p) {
    while (lower.length >= 2 && cross(lower[lower.length - 2]!, lower[lower.length - 1]!, q) <= 0) lower.pop();
    lower.push(q);
  }
  const upper: Array<[number, number]> = [];
  for (let i = p.length - 1; i >= 0; i--) {
    const q = p[i]!;
    while (upper.length >= 2 && cross(upper[upper.length - 2]!, upper[upper.length - 1]!, q) <= 0) upper.pop();
    upper.push(q);
  }
  return lower.slice(0, -1).concat(upper.slice(0, -1));
}

/** The distance from a point to a convex polygon given anticlockwise: 0 inside. */
function distanceToPolygon(poly: Array<[number, number]>, x: number, y: number): number {
  if (poly.length === 0) return Infinity;
  if (poly.length === 1) return Math.hypot(x - poly[0]![0], y - poly[0]![1]);
  let inside = poly.length >= 3;
  let best = Infinity;
  for (let i = 0; i < poly.length; i++) {
    const a = poly[i]!;
    const b = poly[(i + 1) % poly.length]!;
    const ex = b[0] - a[0];
    const ey = b[1] - a[1];
    if (ex * (y - a[1]) - ey * (x - a[0]) < 0) inside = false;
    const len2 = ex * ex + ey * ey;
    const t = len2 > 0 ? Math.min(1, Math.max(0, ((x - a[0]) * ex + (y - a[1]) * ey) / len2)) : 0;
    best = Math.min(best, Math.hypot(x - (a[0] + t * ex), y - (a[1] + t * ey)));
  }
  return inside ? 0 : best;
}

/**
 * Whether a caster's bounding sphere can shadow what the eye sees in a part
 * of its view: `view` is the cascade's view matrix (the sun's, `z` growing
 * away from it), `slice` the corners in the scene of that part of the view
 * frustum, `margin` how much wider to look, in metres, for the texels the
 * shadow's filtering reads beside each one. Nearer the sun than the slice
 * still casts (the map clamps depth); wholly beyond it, nothing it shades.
 */
export function castsIntoSlice(view: ArrayLike<number>, slice: readonly Vec3[], centre: Vec3, radius: number, margin = 0): boolean {
  const corners = slice.map((p) => inView(view, p));
  const c = inView(view, centre);
  if (c[2] - radius > Math.max(...corners.map((p) => p[2]))) return false;
  return distanceToPolygon(hull(corners.map((p) => [p[0], p[1]])), c[0], c[1]) <= radius + margin;
}

/** Everything the sun's shadow map shows depends on, as it was when it was last drawn. */
export interface ShadowPose {
  eye: Vec3;
  forward: Vec3;
  up: Vec3;
  /** The camera's vertical field of view, radians, and its width over its height. */
  fov: number;
  aspect: number;
  /** How far the shadows reach, metres. */
  reach: number;
  /** Toward the sun. */
  sun: Vec3;
  /** Counts each time the casters come or go. */
  casters: number;
  /** Something that casts moves by itself (the plants in the wind): drawn every frame. */
  moving: boolean;
}

/** How far, in radians, the sun may move before a shadow `heightM` long shifts by half a texel `texelM` wide. */
export function sunStillAngle(texelM: number, heightM: number): number {
  return (0.5 * texelM) / heightM;
}

const same = (a: Vec3, b: Vec3, eps: number) => Math.abs(a[0] - b[0]) <= eps && Math.abs(a[1] - b[1]) <= eps && Math.abs(a[2] - b[2]) <= eps;

/**
 * Whether the shadow map must be drawn again. The cascades follow the view,
 * so any move or turn of the eye redraws it; so does a change of the casters,
 * of the reach, or a sun moved by more than `sunStill` radians. Held, the map
 * keeps the cascades it was drawn with, so what it shows stays where it was.
 */
export function shadowMapStale(last: ShadowPose | undefined, now: ShadowPose, sunStill: number): boolean {
  if (!last || now.moving || now.casters !== last.casters || now.reach !== last.reach) return true;
  if (!same(now.eye, last.eye, 1e-4) || !same(now.forward, last.forward, 1e-6) || !same(now.up, last.up, 1e-6)) return true;
  if (Math.abs(now.fov - last.fov) > 1e-6 || Math.abs(now.aspect - last.aspect) > 1e-6) return true;
  const [a, b] = [now.sun, last.sun];
  const cos = (a[0] * b[0] + a[1] * b[1] + a[2] * b[2]) / (Math.hypot(...a) * Math.hypot(...b) || 1);
  return Math.acos(Math.min(1, Math.max(-1, cos))) > sunStill;
}

/**
 * Whether a caster's bounding sphere can fall on a cascade's square: `min`
 * and `max` its extents in the cascade's view. The coarser test, for when the
 * slice's corners are not known.
 */
export function castsIntoCascade(view: ArrayLike<number>, min: Vec3, max: Vec3, centre: Vec3, radius: number): boolean {
  const [vx, vy, vz] = inView(view, centre);
  return vx + radius >= min[0] && vx - radius <= max[0] && vy + radius >= min[1] && vy - radius <= max[1] && vz - radius <= max[2];
}
