/**
 * A planet's atmosphere: a shell of air that thins with height, lit by the
 * sun. Its single scattering of sunlight (Rayleigh, by the air; Mie, by haze)
 * gives the sky its colour, a low sun its red, the distance its haze and
 * space its black. The air reaches `top` metres over altitude 0 (by default a
 * quarter of the radius, so a small planet keeps a sky over its mountains)
 * and thins exponentially, with scale heights a sixth (air) and a thirtieth
 * (haze) of that. Each is as thick, straight up, as Earth's, so the sky looks
 * as Earth's does however thin the shell.
 *
 * This is the reference the atmosphere's shader (atmosphereChunk.ts) follows,
 * on the processor: the planet view takes the haze's colour and thickness for
 * the ground from it.
 */

export type Vec3 = [number, number, number];

export interface Atmosphere {
  /** Metres, at altitude 0. */
  radius: number;
  /** Metres over altitude 0 the air reaches. */
  top: number;
  /** Scale heights, metres: the air's and the haze's. */
  rayleighHeight: number;
  mieHeight: number;
  /** Scattering per metre at altitude 0: the air's, by colour, and the haze's. */
  rayleigh: Vec3;
  mie: number;
}

/** Optical depth straight up through Earth's air (by red, green, blue) and its haze. */
const EARTH_RAYLEIGH_DEPTH: Vec3 = [5.8e-6 * 8000, 13.5e-6 * 8000, 33.1e-6 * 8000];
const EARTH_MIE_DEPTH = 21e-6 * 1200;
/** Haze absorbs a little as well as scattering. */
const MIE_EXTINCTION = 1.1;
/** The haze's forward scattering: the glow around the sun. */
const MIE_G = 0.76;
/** The sun's brightness in the sum; the result is tone-mapped to 0..1. */
const SUN_INTENSITY = 20;

export function atmosphereOf(radius: number, opts: { top?: number } = {}): Atmosphere {
  const top = opts.top ?? 0.24 * radius;
  const rayleighHeight = top / 6;
  const mieHeight = top / 30;
  return {
    radius,
    top,
    rayleighHeight,
    mieHeight,
    rayleigh: EARTH_RAYLEIGH_DEPTH.map((d) => d / rayleighHeight) as Vec3,
    mie: EARTH_MIE_DEPTH / mieHeight,
  };
}

/** The air's density at an altitude, 1 at altitude 0, none past the top. */
export function airDensity(a: Atmosphere, alt: number): number {
  return alt > a.top ? 0 : Math.exp(-Math.max(alt, 0) / a.rayleighHeight);
}

/**
 * The haze for the ground, as an EXP2 fog density per metre at the eye's
 * altitude: at altitude 0 it hides half of what lies `top` metres away, and
 * thins with the air; none past the top.
 */
export function hazeDensity(a: Atmosphere, alt: number): number {
  return (Math.sqrt(Math.LN2) / a.top) * airDensity(a, alt);
}

const dot = (u: Vec3, v: Vec3) => u[0] * v[0] + u[1] * v[1] + u[2] * v[2];

/** Where a ray from `o` along unit `d` meets a sphere of radius `r` at the origin: its two distances, or null. */
function sphere(o: Vec3, d: Vec3, r: number): [number, number] | null {
  const b = dot(o, d);
  const c = dot(o, o) - r * r;
  const disc = b * b - c;
  if (disc < 0) return null;
  const s = Math.sqrt(disc);
  return [-b - s, -b + s];
}

/**
 * The share of the sun's light, by red, green and blue, that reaches `origin`
 * (metres from the planet's centre) from the unit direction `sun` through the
 * air: nearly all of it from overhead, the red of it from low down, none from
 * under the horizon (the planet is in the way), and all of it past the air.
 */
export function sunlight(a: Atmosphere, origin: Vec3, sun: Vec3, steps = 8): Vec3 {
  const ground = sphere(origin, sun, a.radius);
  if (ground && ground[0] > 0) return [0, 0, 0];
  const out = sphere(origin, sun, a.radius + a.top);
  if (!out || out[1] <= 0) return [1, 1, 1];
  const start = Math.max(out[0], 0);
  const ds = (out[1] - start) / steps;
  let odR = 0, odM = 0;
  for (let i = 0; i < steps; i++) {
    const t = start + (i + 0.5) * ds;
    const h = Math.hypot(origin[0] + sun[0] * t, origin[1] + sun[1] * t, origin[2] + sun[2] * t) - a.radius;
    odR += Math.exp(-h / a.rayleighHeight) * ds;
    odM += Math.exp(-h / a.mieHeight) * ds;
  }
  return [0, 1, 2].map((k) => Math.exp(-(a.rayleigh[k]! * odR + a.mie * MIE_EXTINCTION * odM))) as Vec3;
}

/** The sun's disc's angular radius, in radians: a little larger than the real sun's, so it reads on a screen. */
export const SUN_RADIUS_RAD = 0.008;
/** The numbers the sky's shader carries as the reference does, written as it writes them. */
export const SUN_GLOW_CONSTANTS = ['0.008', '0.035', '0.15', '0.85', '1.15'] as const;

/**
 * The sun as the eye sees it toward a direction at cosine `mu` from it,
 * before the air in front dims it: a disc darker at its rim and with no hard
 * edge, in a glow the air scatters about it (the aureole) that falls away
 * over a few degrees and then a few tens.
 */
export function sunGlow(mu: number): number {
  const angle = Math.acos(Math.min(1, Math.max(-1, mu)));
  const r = angle / SUN_RADIUS_RAD;
  const smooth = (e0: number, e1: number, x: number) => {
    const t = Math.min(1, Math.max(0, (x - e0) / (e1 - e0)));
    return t * t * (3 - 2 * t);
  };
  const rim = 1 - 0.6 * (1 - Math.sqrt(Math.max(0, 1 - Math.min(r, 1) ** 2)));
  const disc = 40 * rim * (1 - smooth(0.85, 1.15, r));
  return disc + 0.6 * Math.exp(-angle / 0.035) + 0.08 * Math.exp(-angle / 0.15);
}

/**
 * The light the air scatters toward the eye at `origin` (metres from the
 * planet's centre) looking along unit `dir`, the sun along unit `sun`:
 * linear red, green and blue, tone-mapped to 0..1. `steps` samples the view
 * ray and `lightSteps` each sample's ray to the sun.
 */
export function skyColour(a: Atmosphere, origin: Vec3, dir: Vec3, sun: Vec3, steps = 16, lightSteps = 4): Vec3 {
  return skyLight(a, origin, dir, sun, steps, lightSteps).scatter.map((c) => 1 - Math.exp(-c)) as Vec3;
}

/** The air's light along a view ray, before it is tone-mapped: what it scatters toward the eye, and the share of what lies beyond (the sun, the stars) it lets through. */
export interface SkyLight {
  scatter: Vec3;
  through: Vec3;
}

/** `skyColour`'s sums, untone-mapped, with the share of space's light the ray lets through: what the sky's shader adds the sun and stars to. */
export function skyLight(a: Atmosphere, origin: Vec3, dir: Vec3, sun: Vec3, steps = 16, lightSteps = 4): SkyLight {
  const top = a.radius + a.top;
  const none = (): SkyLight => ({ scatter: [0, 0, 0], through: [1, 1, 1] });
  const hit = sphere(origin, dir, top);
  if (!hit || hit[1] <= 0) return none();
  let start = Math.max(hit[0], 0);
  let end = hit[1];
  // The ground stops the view.
  const ground = sphere(origin, dir, a.radius);
  if (ground && ground[0] > 0) end = Math.min(end, ground[0]);
  if (end <= start) return none();
  const ds = (end - start) / steps;
  let odR = 0, odM = 0;
  const sumR: Vec3 = [0, 0, 0], sumM: Vec3 = [0, 0, 0];
  for (let i = 0; i < steps; i++) {
    const t = start + (i + 0.5) * ds;
    const p: Vec3 = [origin[0] + dir[0] * t, origin[1] + dir[1] * t, origin[2] + dir[2] * t];
    const h = Math.hypot(...p) - a.radius;
    const dR = Math.exp(-h / a.rayleighHeight) * ds;
    const dM = Math.exp(-h / a.mieHeight) * ds;
    odR += dR;
    odM += dM;
    // The sun's light reaching the sample, unless the planet is in the way.
    const toSun = sphere(p, sun, top)!;
    const shadow = sphere(p, sun, a.radius);
    if (shadow && shadow[0] > 0) continue;
    const dl = toSun[1] / lightSteps;
    let lR = 0, lM = 0;
    for (let j = 0; j < lightSteps; j++) {
      const q: Vec3 = [p[0] + sun[0] * (j + 0.5) * dl, p[1] + sun[1] * (j + 0.5) * dl, p[2] + sun[2] * (j + 0.5) * dl];
      const hq = Math.hypot(...q) - a.radius;
      lR += Math.exp(-hq / a.rayleighHeight) * dl;
      lM += Math.exp(-hq / a.mieHeight) * dl;
    }
    for (let k = 0; k < 3; k++) {
      const tau = a.rayleigh[k]! * (odR + lR) + a.mie * MIE_EXTINCTION * (odM + lM);
      const att = Math.exp(-tau);
      sumR[k]! += att * dR;
      sumM[k]! += att * dM;
    }
  }
  const mu = dot(dir, sun);
  const phaseR = (3 / (16 * Math.PI)) * (1 + mu * mu);
  const g2 = MIE_G * MIE_G;
  const phaseM = ((3 / (8 * Math.PI)) * ((1 - g2) * (1 + mu * mu))) / ((2 + g2) * (1 + g2 - 2 * MIE_G * mu) ** 1.5);
  return {
    scatter: [0, 1, 2].map((k) => SUN_INTENSITY * (sumR[k]! * a.rayleigh[k]! * phaseR + sumM[k]! * a.mie * phaseM)) as Vec3,
    through: [0, 1, 2].map((k) => Math.exp(-(a.rayleigh[k]! * odR + a.mie * MIE_EXTINCTION * odM))) as Vec3,
  };
}
