/**
 * The planets of one world (specs/veml/profiles/planet.md, Bodies; Held by
 * a planet; Arrival). A world may be a planet, include planets, or both: a
 * solar system includes its planets, a planet includes its moons. Each is
 * drawn by its own planet view (planetView.ts); this places them and passes
 * the visitor between them.
 *
 * Frames. The root world's frame is "the world": its own entities hang under
 * one node here, and an included planet's frame is the entity that includes
 * it, its scale left out (a planet is drawn at its own size). The scene is a
 * floating origin about the visitor: anchored on the planet that holds them,
 * so that planet stands still in the scene however the world moves it, and
 * the visitor, who stands on it, is carried along. Outside every hold
 * sphere the anchor is in the world's frame.
 *
 * Holds. A planet holds the space within `reach` of its surface. The
 * smallest hold sphere around the visitor holds them: that planet draws
 * their surroundings and keeps them on its ground; the rest are drawn from
 * their terrain. Hold spheres must nest or stand apart; one that does not is
 * neither drawn nor holds anyone.
 *
 * Links. An `on` pair names a planet by its document's own URL; the visitor
 * arrives where the root world puts them, and is moved there, through a
 * fade, once that planet is found.
 */

import { TransformNode } from '@babylonjs/core/Meshes/transformNode';
import { Matrix, Quaternion, Vector3 } from '@babylonjs/core/Maths/math.vector';
import type { AbstractMesh } from '@babylonjs/core/Meshes/abstractMesh';
import type { VemlPlanet } from '../../veml/documentModel';
import { FLY_SPEED_MPS, GRAVITY_MPS2 } from '../../controller/firstPersonController';
import { anchorOf, anchorTransform, arrivalOf, createPlanetView, type AnchorTransform, type PlanetController, type PlanetView, type PlanetViewOptions } from './planetView';
import { geoOf, type Vec3 } from './planetFrame';
import { createSiteBudget } from './planetSites';

// ---- pure parts ----------------------------------------------------------------

type Mat3 = [Vec3, Vec3, Vec3];
/** A turn and a shift: x ↦ r·x + t, `r` by its rows. */
export interface Rigid {
  r: Mat3;
  t: Vec3;
}

const dot = (a: Vec3, b: Vec3) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const sub = (a: Vec3, b: Vec3): Vec3 => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const turn = (r: Mat3, x: Vec3): Vec3 => [dot(r[0], x), dot(r[1], x), dot(r[2], x)];
const transpose = (r: Mat3): Mat3 => [0, 1, 2].map((i) => [r[0][i]!, r[1][i]!, r[2][i]!]) as Mat3;
const apply = (a: Rigid, x: Vec3): Vec3 => {
  const p = turn(a.r, x);
  return [p[0] + a.t[0], p[1] + a.t[1], p[2] + a.t[2]];
};
/** `a` after `b`. */
const compose = (a: Rigid, b: Rigid): Rigid => {
  const bt = transpose(b.r);
  return { r: a.r.map((row) => bt.map((col) => dot(row, col))) as Mat3, t: apply(a, b.t) };
};
const invert = (a: Rigid): Rigid => {
  const r = transpose(a.r);
  const t = turn(r, a.t);
  return { r, t: [-t[0], -t[1], -t[2]] };
};
const IDENTITY: Rigid = { r: [[1, 0, 0], [0, 1, 0], [0, 0, 1]], t: [0, 0, 0] };

/** An anchor (planet to scene) as a turn and a shift. */
const rigidOfAnchor = (a: AnchorTransform): Rigid => ({ r: [...a.axes] as Mat3, t: a.apply([0, 0, 0]) });
/** A turn and a shift from a planet's frame to the scene, as that planet's anchor. */
const anchorOfRigid = (s: Rigid, radius: number): AnchorTransform => {
  const o = turn(transpose(s.r), s.t);
  return anchorOf([-o[0], -o[1], -o[2]], [...s.r] as Mat3, radius);
};

/** A node's matrix (Babylon's: row vectors) as a turn and a shift, its scale left out, and whether it had any. */
function rigidOfMatrix(m: Matrix): { rigid: Rigid; scaled: boolean } {
  const a = m.m;
  const rows = [0, 1, 2].map((i) => [a[i * 4]!, a[i * 4 + 1]!, a[i * 4 + 2]!] as Vec3);
  const scales = rows.map((v) => Math.hypot(...v));
  const unit = rows.map((v, i) => v.map((x) => x / (scales[i] || 1)) as Vec3);
  return { rigid: { r: transpose(unit as Mat3), t: [a[12]!, a[13]!, a[14]!] }, scaled: scales.some((s) => Math.abs(s - 1) > 1e-6) };
}

/** A turn and a shift as a node's place. */
function placeNode(node: TransformNode, s: Rigid) {
  const [x, y, z] = s.r;
  node.rotationQuaternion = Quaternion.FromRotationMatrix(Matrix.FromValues(x[0], y[0], z[0], 0, x[1], y[1], z[1], 0, x[2], y[2], z[2], 0, 0, 0, 0, 1));
  node.position.set(...s.t);
  node.computeWorldMatrix(true);
}

export interface HoldSphere {
  centre: Vec3;
  radius: number;
  reach: number;
}

/** The planet whose hold sphere is the smallest around `point`, by its place in the list; -1 for none. */
export function heldBy(spheres: readonly HoldSphere[], point: Vec3, skip: ReadonlySet<number> = new Set()): number {
  let best = -1;
  spheres.forEach((s, i) => {
    if (skip.has(i) || Math.hypot(...sub(point, s.centre)) > s.radius + s.reach) return;
    if (best < 0 || s.radius + s.reach < spheres[best]!.radius + spheres[best]!.reach) best = i;
  });
  return best;
}

/**
 * The planets that break the nesting, by their place in the list (the include
 * tree's depth-first order): two hold spheres must be one inside the other or
 * apart, and one inside another must lie outside that planet itself. Of two
 * that break it, the later one does.
 */
export function brokenHolds(spheres: readonly HoldSphere[]): Set<number> {
  const broken = new Set<number>();
  spheres.forEach((a, i) => {
    for (let j = 0; j < i; j++) {
      if (broken.has(j)) continue;
      const b = spheres[j]!;
      const d = Math.hypot(...sub(a.centre, b.centre));
      const ha = a.radius + a.reach, hb = b.radius + b.reach;
      const ok = d >= ha + hb || (d + ha <= hb && d - ha >= b.radius) || (d + hb <= ha && d - hb >= a.radius);
      if (!ok) {
        broken.add(i);
        return;
      }
    }
  });
  return broken;
}

/**
 * A world URL's fragment, its `on` pair taken out: the planet it names,
 * percent-decoded, and the rest of the fragment as it was written. A
 * repeated `on` keeps its first value; a malformed one is warned and names
 * no planet.
 */
export function linkOf(fragment: string): { on?: string; rest: string; warnings: string[] } {
  if (!/^(at|on|look)=/.test(fragment)) return { rest: fragment, warnings: [] };
  const rest: string[] = [];
  const warnings: string[] = [];
  let on: string | undefined;
  let seen = false;
  for (const part of fragment.split('&')) {
    const eq = part.indexOf('=');
    if (eq < 0 || part.slice(0, eq) !== 'on') {
      rest.push(part);
      continue;
    }
    if (seen) continue;
    seen = true;
    try {
      on = decodeURIComponent(part.slice(eq + 1));
    } catch {
      warnings.push('veml:planet:unknown-fragment');
    }
  }
  return { ...(on !== undefined ? { on } : {}), rest: rest.join('&'), warnings };
}

const httpUrl = (u: string): URL | undefined => {
  try {
    const url = new URL(u);
    url.hash = '';
    return url.protocol === 'http:' || url.protocol === 'https:' ? url : undefined;
  } catch {
    return undefined;
  }
};

/** Whether an `on` link names the document at `docUrl`: both absolute http(s) URLs, alike once serialized, fragments aside. */
export function sameDocument(link: string, docUrl: string): boolean {
  const a = httpUrl(link), b = httpUrl(docUrl);
  return !!a && !!b && a.href === b.href;
}

/**
 * Whether an include at `a` in the include tree comes before one at `b`, depth
 * first: an include before the ones it brings in, and those before the next
 * one. One whose place is unknown comes after every known one.
 */
export function earlierInTree(a: readonly number[] | undefined, b: readonly number[] | undefined): boolean {
  if (!a) return false;
  if (!b) return true;
  for (let i = 0; i < Math.min(a.length, b.length); i++) if (a[i] !== b[i]) return a[i]! < b[i]!;
  return a.length < b.length;
}

/**
 * The shell's own `fly-speed`: the height a dive covers a second, as a share of the height, so that each halving of it
 * takes a second and a half; from orbit to the treetops is then about 15 s, which the terrain under a fresh spot keeps
 * up with. At one height a second the halving took 0.7 s, and the eye outran the ground.
 */
export const DEFAULT_FLY_SCALE = Math.LN2 / 1.5;
/**
 * The seconds of terrain in view still to come that a flight takes in its stride; past them, each as many again halves
 * the pace once more. And how quickly the pace follows, in seconds. Braking on how many tiles were wanted held a dive
 * at half its pace however fast they came: a fast dive always wants many.
 */
const BRAKE_FREE_S = 1;
const BRAKE_EASE_S = 0.4;
/** The least share of its pace a flight keeps while the terrain in view comes. */
const BRAKE_FLOOR = 0.15;

/** How fast a visitor flies `height` metres over the ground: `scale` times the height a second, never slower than the shell's fly speed. */
export const flySpeedOf = (height: number, scale: number): number => Math.max(FLY_SPEED_MPS, scale * height);

// ---- the system ----------------------------------------------------------------

/** How far, in metres, a visitor outside every planet moves before the origin moves to them. */
const SPACE_REANCHOR_M = 256;
/** Ground this high over a planet's radius may stand on its far side: its mountains. */
const MOUNTAINS_M = 10_000;
/** The share of the camera's far plane a planet beyond it is drawn within, made smaller and nearer. */
const NEAR_SHARE = 0.9;
/** Frames between looks for root-world entities to carry about the floating origin. */
const ADOPT_EVERY = 60;

export interface PlanetSystem extends Omit<PlanetView, 'anchorNow' | 'setAnchor' | 'setHeld' | 'arriveAt' | 'setShown' | 'height'> {
  /** A planet world included by an entity (`carrier`), or, with no carrier, the root world itself; `url` its document's own URL. */
  /** `order`: where the include that brings it stands in the include tree, depth first (IncludeSite.order). */
  addPlanet(planet: VemlPlanet, url: string, carrier: TransformNode | null, gravity?: number, order?: readonly number[], hints?: Readonly<Record<string, string>>): Promise<void>;
  /** Every include in the world has loaded or failed: an `on` link that found no planet warns. */
  settled(): void;
  /** Whether an `on` link still looks for its planet: the world's deferred includes load while it does. */
  seeking(): boolean;
  /** How fast the visitor flies now, m/s. */
  flySpeed(): number;
  /**
   * The gravity on the visitor now, m/s² downward: the holding planet's own
   * (`gravity` as its document's `locomotion` gives it), or the shell's where
   * it gives none; outside every hold sphere, none, unless the root world is
   * not a planet world and gives its own.
   */
  gravity(): number;
}

export interface PlanetSystemOptions extends Omit<PlanetViewOptions, 'planet' | 'fragment' | 'body' | 'loadSite'> {
  /** The world's URL fragment, without '#'. */
  fragment: string;
  /** The root world, when it is a planet, its document's URL, and the gravity its `locomotion` gives, if any. */
  root?: { planet: VemlPlanet; url: string; gravity?: number };
  /** The gravity a root world that is not a planet gives in its own `locomotion`, if any: it pulls outside every hold sphere. */
  spaceGravity?: number;
  /** The root world's own top-level nodes: carried about the floating origin in the world's frame. */
  worldNodes?: () => readonly TransformNode[];
  /** Builds a site's document under `parent`, as an include; undefined when it cannot be. */
  loadSite?: (href: string, integrity: string | undefined, parent: TransformNode) => Promise<{ dispose(): void } | undefined>;
  /** How many documents the world's includes hold now: they count against the 64 loaded documents, sites among them, a world may hold. */
  treeDocuments?: () => number;
  /** Test seam: makes a planet's view (default createPlanetView). */
  createView?: (o: PlanetViewOptions) => Promise<PlanetView>;
  /** Test seam: the comfort fade a link's move is made behind, `go` at its darkest (default: a black veil over the page). */
  fade?: (go: () => void) => void;
}

interface Planet {
  planet: VemlPlanet;
  url: string;
  carrier: TransformNode | null;
  view: PlanetView;
  /** The gravity its document's `locomotion` gives, if any. */
  gravity?: number;
  /** From its frame to the world's, this frame. */
  place: Rigid;
  /** Where its view was last put, and how much smaller about the eye, to put it again only when either changes. */
  placed?: Rigid;
  near?: { scale: number; about: Vec3 } | undefined;
  broken: boolean;
}

/** A black veil over the page, faded in, `go` run under it, and faded out. */
function veilFade(go: () => void): void {
  if (typeof document === 'undefined' || !document.body) return go();
  const veil = document.createElement('div');
  veil.style.cssText = 'position:fixed;inset:0;background:#000;opacity:0;transition:opacity 250ms;pointer-events:none;z-index:50';
  document.body.appendChild(veil);
  requestAnimationFrame(() => (veil.style.opacity = '1'));
  setTimeout(() => {
    go();
    veil.style.opacity = '0';
    setTimeout(() => veil.remove(), 300);
  }, 280);
}

const sameNear = (a: { scale: number; about: Vec3 } | undefined, b: { scale: number; about: Vec3 } | undefined): boolean =>
  a === b || (!!a && !!b && a.scale === b.scale && a.about.every((v, i) => v === b.about[i]));
const same = (a: Rigid | undefined, b: Rigid): boolean =>
  !!a && [0, 1, 2].every((i) => Math.abs(a.t[i]! - b.t[i]!) < 1e-6 && [0, 1, 2].every((j) => Math.abs(a.r[i]![j]! - b.r[i]![j]!) < 1e-12));

export async function createPlanetSystem(o: PlanetSystemOptions): Promise<PlanetSystem> {
  const { scene, camera } = o;
  const { root: rootWorld, spaceGravity, worldNodes, loadSite, treeDocuments, createView = createPlanetView, fade = veilFade, fragment, ...shared } = o;
  // One budget of loaded sites for every planet, with what the world's includes already hold.
  const siteBudget = createSiteBudget(treeDocuments);
  // The root world's frame, carried about the floating origin.
  const world = new TransformNode('planet-world', scene);
  const adopt = () => {
    for (const n of worldNodes?.() ?? []) if (!n.parent && n !== world && !n.isDisposed()) n.parent = world;
  };
  adopt();

  // An `on` link: to the root planet itself, to one found later, or to none at all.
  const link = linkOf(fragment);
  for (const w of link.warnings) o.warn(w, `#${fragment}`);
  let rootFragment = link.rest;
  let lookingFor: { url: string; rest: string } | undefined;
  /** The planet an `on` link names that comes first in the include tree so far: moved to once the world settles. */
  let found: { p: Planet; order: readonly number[] | undefined } | undefined;
  if (link.on !== undefined) {
    rootFragment = '';
    if (!httpUrl(link.on)) o.warn('veml:planet:unknown-fragment', `#${fragment}`);
    else if (rootWorld && sameDocument(link.on, rootWorld.url)) rootFragment = link.rest;
    else lookingFor = { url: link.on, rest: link.rest };
  }

  const planets: Planet[] = [];
  let held: Planet | null = null;
  /** The world's frame to the scene, while no planet holds the visitor. */
  let space: Rigid = IDENTITY;
  /** The world's frame to the scene, this frame. */
  let toScene: Rigid = IDENTITY;
  let controller: PlanetController | undefined;
  let frame = 0;

  const setWorld = (s: Rigid) => {
    toScene = s;
    placeNode(world, s);
  };
  /** Where a planet's frame is in the world's, now: its carrier's place under the world's node, scale aside. */
  const placeOf = (p: Planet): Rigid => {
    if (!p.carrier) return IDENTITY;
    p.carrier.computeWorldMatrix(true);
    const rel = p.carrier.getWorldMatrix().multiply(Matrix.Invert(world.getWorldMatrix()));
    return rigidOfMatrix(rel).rigid;
  };
  const sphereOf = (p: Planet): HoldSphere => ({ centre: p.place.t, radius: p.planet.radius, reach: p.planet.reach });
  const heldScene = (p: Planet): Rigid => compose(rigidOfAnchor(p.view.anchorNow()), invert(p.place));
  /** The visitor's facing, as a direction in the world's frame. */
  const facingInWorld = (): Vec3 | undefined => {
    if (!controller) return undefined;
    const y = controller.yaw, p = controller.pitch ?? 0;
    return turn(transpose(toScene.r), [Math.sin(y) * Math.cos(p), -Math.sin(p), Math.cos(y) * Math.cos(p)]);
  };
  const face = (dirInWorld: Vec3 | undefined) => {
    if (!dirInWorld || !controller?.setOrientation) return;
    const f = turn(toScene.r, dirInWorld);
    controller.setOrientation(Math.atan2(f[0], f[2]), -Math.asin(Math.max(-1, Math.min(1, f[1]))));
  };

  /** The visitor, at `w` in the world's frame, passes to `next` (or out into space), where they are and facing as they were. */
  const handOver = (next: Planet | null, w: Vec3) => {
    const facing = facingInWorld();
    held?.view.setHeld(false);
    if (!next) {
      held = null;
      space = toScene;
      controller?.setFlyMode?.(true);
      return;
    }
    const x = apply(invert(next.place), w);
    const g = geoOf(x, next.planet.radius);
    const a = anchorTransform(next.planet.radius, g.lat, g.lon, 0);
    next.view.setAnchor(a);
    next.placed = undefined;
    next.view.setHeld(true);
    held = next;
    setWorld(heldScene(next));
    const feet = a.apply(x);
    controller?.teleportFeet(new Vector3(...feet));
    face(facing);
    // Its frame now, not the next: the camera's depths and its water fitted to it before this frame is drawn.
    next.view.tick(0);
  };

  /** Lands the visitor on `p` where a link says, behind a fade. */
  const moveTo = (p: Planet, rest: string) => {
    const arrival = arrivalOf(p.planet, rest);
    for (const w of arrival.warnings) o.warn(w, `#${fragment}`);
    fade(() => {
      if (held !== p) {
        held?.view.setHeld(false);
        p.view.setHeld(true);
        held = p;
      }
      p.placed = undefined;
      p.view.arriveAt(arrival.at, arrival.look, arrival.alt);
      setWorld(heldScene(p));
    });
  };

  const viewOf = async (planet: VemlPlanet, url: string, body: boolean, own: Readonly<Record<string, string>> | undefined): Promise<PlanetView> => {
    let me: PlanetView | undefined;
    const isRoot = !body && !!rootWorld;
    me = await createView({
      ...shared,
      // Its own `hints:planet` draw it (the planet profile, What an included planet world contributes); the rest are the root world's.
      ...(own && shared.hint ? { hint: (name: string) => (name.startsWith('planet.') && own[name] !== undefined ? own[name]! : shared.hint!(name)) } : {}),
      // Its air too, which the view takes with the atmosphere rather than through the hints.
      ...(own?.['planet.air'] !== undefined && shared.atmosphere ? { atmosphere: { ...shared.atmosphere, air: own['planet.air'] } } : {}),
      planet,
      fragment: body ? '' : rootFragment,
      siteBudget,
      ...(body ? { body: true } : {}),
      ...(loadSite ? { loadSite: (site, parent) => loadSite(site.href.resolved, site.integrity, parent) } : {}),
      // Where the visitor is, said while this planet holds them: with `on` unless it is the root world.
      onPlace: (f) => {
        if (held?.view !== me) return;
        o.onPlace?.(isRoot ? f : `on=${encodeURIComponent(url)}&${f}`);
      },
    });
    return me;
  };

  const add = async (planet: VemlPlanet, url: string, carrier: TransformNode | null, body: boolean, gravity: number | undefined, hints?: Readonly<Record<string, string>>): Promise<Planet> => {
    const view = await viewOf(planet, url, body, hints);
    const p: Planet = { planet, url, carrier, view, place: IDENTITY, broken: false, ...(gravity !== undefined ? { gravity } : {}) };
    p.place = placeOf(p);
    // Its own size, whatever the scale of what carries it.
    if (carrier && rigidOfMatrix(carrier.getWorldMatrix()).scaled) o.warn('veml:planet:scaled', url);
    planets.push(p);
    if (controller) view.attachController(controller);
    return p;
  };

  if (rootWorld) {
    held = await add(rootWorld.planet, rootWorld.url, null, false, rootWorld.gravity);
    setWorld(heldScene(held));
  }

  // The share of its pace a flight keeps while the terrain where the eye looks is still coming: eased, so it neither
  // jerks nor stalls.
  let brake = 1;
  const flySpeed = (): number => {
    const v = o.hint?.('planet.fly-speed');
    const n = v === null || v === undefined || v === 'auto' ? NaN : Number(v);
    const scale = Number.isFinite(n) && n > 0 ? n : DEFAULT_FLY_SCALE;
    if (held) return flySpeedOf(held.view.height() * brake, scale);
    const f = controller?.feetPosition();
    if (!f) return FLY_SPEED_MPS;
    const w = apply(invert(toScene), [f.x, f.y, f.z]);
    const height = Math.min(...planets.filter((p) => !p.broken).map((p) => Math.hypot(...sub(w, p.place.t)) - p.planet.radius));
    return Number.isFinite(height) ? flySpeedOf(Math.max(0, height), scale) : FLY_SPEED_MPS;
  };

  const system: PlanetSystem = {
    arrival: held ? (held as Planet).view.arrival : { feet: new Vector3(0, 0, 0), yaw: 0, pitch: 0 },
    attachController(c) {
      controller = c;
      for (const p of planets) p.view.attachController(c);
    },
    walkableMeshes(x, z): readonly AbstractMesh[] {
      return held ? held.view.walkableMeshes(x, z) : [];
    },
    waterAt(point) {
      return held ? held.view.waterAt(point) : null;
    },
    async addPlanet(planet, url, carrier, gravity, order, hints) {
      adopt();
      const p = await add(planet, url, carrier, true, gravity, hints);
      // The same planet's document may be included more than once: the link means the first in the include tree,
      // whichever arrives first, so the move waits for every include to be in.
      if (lookingFor && sameDocument(lookingFor.url, url) && (!found || earlierInTree(order, found.order))) found = { p, order };
    },
    settled() {
      if (!lookingFor) return;
      const { rest } = lookingFor;
      const target = found;
      lookingFor = undefined;
      found = undefined;
      if (target) moveTo(target.p, rest);
      else o.warn('veml:planet:unknown-fragment', `#${fragment}`);
    },
    seeking: () => lookingFor !== undefined,
    flySpeed,
    gravity() {
      if (held) return held.gravity ?? -GRAVITY_MPS2;
      return rootWorld ? 0 : (spaceGravity ?? 0);
    },
    tick(deltaMs) {
      frame++;
      const backlog = held?.view.terrainBacklogS?.() ?? 0;
      const target = Math.max(BRAKE_FLOOR, 1 / (1 + Math.max(0, backlog - BRAKE_FREE_S) / BRAKE_FREE_S));
      brake += (target - brake) * (1 - Math.exp(-deltaMs / 1000 / BRAKE_EASE_S));
      if (frame % ADOPT_EVERY === 0) adopt();
      // One sky for the system, its largest planet's: its sun and its stars, which every other planet lights its ground
      // by and draws, held or not, so they stand still as the visitor passes between holds and out into space. A held
      // planet that declares its own day keeps it (planetView.ts), as the planet profile has it.
      const primary = planets.reduce<Planet | null>((best, p) => (!p.broken && (!best || p.planet.radius > best.planet.radius) ? p : best), null);
      const sky = primary?.view.skyNow?.() ?? null;
      for (const p of planets) p.view.setSystemSky?.(p === primary ? null : sky);
      // The planet that holds the visitor first: it may move the origin to them.
      held?.view.tick(deltaMs);
      for (const p of planets) p.place = placeOf(p);
      if (held) setWorld(heldScene(held));
      else setWorld(space);
      // Hold spheres that meet are neither drawn nor hold anyone, until they no longer do.
      const spheres = planets.map(sphereOf);
      const broken = brokenHolds(spheres);
      planets.forEach((p, i) => {
        const now = broken.has(i);
        if (now === p.broken) return;
        p.broken = now;
        p.view.setShown(!now);
        if (now) o.warn('veml:planet:body-overlaps', p.url);
      });
      if (controller) {
        let f = controller.feetPosition();
        if (!held && Math.hypot(f.x, f.y, f.z) > SPACE_REANCHOR_M) {
          // Out in space, the origin follows the visitor.
          space = { r: space.r, t: sub(space.t, [f.x, f.y, f.z]) };
          setWorld(space);
          controller.teleportFeet(new Vector3(0, 0, 0));
          f = controller.feetPosition();
        }
        const w = apply(invert(toScene), [f.x, f.y, f.z]);
        const i = heldBy(spheres, w, broken);
        const next = i < 0 ? null : planets[i]!;
        if (next !== held) handOver(next, w);
        // With no planet holding the visitor, the system's sky sets the sun and draws the stars in space: its planet's.
        for (const p of planets) p.view.setSunFromAfar?.(!held && p === primary);
      }
      // The others where the world now puts them, and drawn as the eye sees them: one too far off for the camera's far
      // plane, which the planet that holds the visitor sets for its own ground, smaller and nearer about the eye, so it
      // looks the same from there. Stretching the far plane to reach it instead would cost every depth the scene keeps.
      camera.computeWorldMatrix();
      const eye: Vec3 = [camera.globalPosition.x, camera.globalPosition.y, camera.globalPosition.z];
      const reach = NEAR_SHARE * camera.maxZ;
      for (const p of planets) {
        if (p === held) continue;
        const s = compose(toScene, p.place);
        const out = Math.hypot(...sub(s.t, eye)) + p.planet.radius + MOUNTAINS_M;
        const near = out > reach ? { scale: reach / out, about: eye } : undefined;
        if (!same(p.placed, s) || !sameNear(p.near, near)) {
          p.view.setAnchor(anchorOfRigid(s, p.planet.radius), near);
          p.placed = s;
          p.near = near;
        }
        p.view.tick(deltaMs);
      }
    },
    wheel(deltaY) {
      held?.view.wheel(deltaY);
    },
    async idle() {
      await Promise.all(planets.map((p) => p.view.idle()));
    },
    dispose() {
      for (const p of planets.splice(0)) p.view.dispose();
      held = null;
      world.dispose(true);
    },
  };
  return system;
}
