/**
 * Terrain tiles swapped for finer or coarser ones dissolve into them. For
 * TILE_FADE_MS both are drawn: the tiles coming in keep the screen's pixels
 * whose pattern value is under a threshold that rises from 0 to 1, the tiles
 * going out keep the rest, so every pixel is drawn by exactly one of them and
 * the swap reads as the ground sharpening, not popping. A tile that comes
 * where nothing was drawn, or goes with nothing in its place, is not faded:
 * it would show the sky through it.
 *
 * The pattern is interleaved gradient noise on the pixel's place on the
 * screen, the same in both shader languages; the material plugin that draws
 * it is tileFadeChunk.ts.
 */

import type { AbstractMesh } from '@babylonjs/core/Meshes/abstractMesh';
import type { Scene } from '@babylonjs/core/scene';

/** How long a swap of tiles takes to dissolve, in milliseconds. */
export const TILE_FADE_MS = 250;

/** A tile's fade: the threshold its pixels are kept under (side 1, coming in) or at and over (side -1, going out). */
export interface TileFade {
  threshold: number;
  side: 1 | -1;
}

export interface TileFadeFrame {
  /** The tiles to draw this frame: those shown, and those still fading out. */
  drawn: Set<string>;
  /** A tile's fade, or undefined when it is drawn whole. */
  fadeOf(url: string): TileFade | undefined;
  /** Whether a tile no longer shown is still drawn, fading out: not to be let go yet. */
  holding(url: string): boolean;
}

export interface TileFades {
  /**
   * The tiles shown now, at `nowMs`: what to draw and how faded. A swap fades only when `canFade` holds for every
   * tile in it; otherwise it is made at once, as one side faded and the other not would leave holes.
   */
  update(shown: ReadonlySet<string>, nowMs: number, canFade?: (url: string) => boolean): TileFadeFrame;
}

export function createTileFades(fadeMs = TILE_FADE_MS): TileFades {
  let before = new Set<string>();
  // The swaps under way: when each began, and the tiles coming in and going out in it.
  const swaps: { at: number; into: Set<string>; outOf: Set<string> }[] = [];
  return {
    update(shown, nowMs, canFade = () => true) {
      const into = new Set([...shown].filter((u) => !before.has(u)));
      const outOf = new Set([...before].filter((u) => !shown.has(u)));
      // A tile coming back while it fades out is drawn whole again: it is no longer in the swap it was going out in.
      for (const s of swaps) for (const u of shown) s.outOf.delete(u);
      if (into.size > 0 && outOf.size > 0 && [...into, ...outOf].every(canFade)) swaps.push({ at: nowMs, into, outOf });
      while (swaps.length > 0 && nowMs - swaps[0]!.at >= fadeMs) swaps.shift();
      before = new Set(shown);
      const fade = new Map<string, TileFade>();
      const drawn = new Set(shown);
      for (const s of swaps) {
        const threshold = Math.min(1, Math.max(0, (nowMs - s.at) / fadeMs));
        for (const u of s.into) if (shown.has(u)) fade.set(u, { threshold, side: 1 });
        for (const u of s.outOf) {
          fade.set(u, { threshold, side: -1 });
          drawn.add(u);
        }
      }
      return {
        drawn,
        fadeOf: (u) => fade.get(u),
        holding: (u) => !shown.has(u) && drawn.has(u),
      };
    },
  };
}

const IGN = '52.9829189';

/** The fragment test, which drops a pixel the tile does not draw while it fades: WGSL on WebGPU, GLSL elsewhere. */
export function selectTileFadeCode(engineKind?: string): { uniforms: string; fragment: string } {
  if (engineKind === 'webgpu')
    return {
      uniforms: 'uniform tileFadeThreshold: f32;\nuniform tileFadeSide: f32;\n',
      fragment: `if (uniforms.tileFadeSide != 0.0) {
  let tileFadeAt = fract(${IGN} * fract(dot(fragmentInputs.position.xy, vec2f(0.06711056, 0.00583715))));
  if ((uniforms.tileFadeSide > 0.0 && tileFadeAt >= uniforms.tileFadeThreshold) || (uniforms.tileFadeSide < 0.0 && tileFadeAt < uniforms.tileFadeThreshold)) { discard; }
}
`,
    };
  return {
    uniforms: 'uniform float tileFadeThreshold;\nuniform float tileFadeSide;\n',
    fragment: `if (tileFadeSide != 0.0) {
  float tileFadeAt = fract(${IGN} * fract(dot(gl_FragCoord.xy, vec2(0.06711056, 0.00583715))));
  if ((tileFadeSide > 0.0 && tileFadeAt >= tileFadeThreshold) || (tileFadeSide < 0.0 && tileFadeAt < tileFadeThreshold)) discard;
}
`,
  };
}

export interface TileFadeHandle {
  /** Takes up the tile materials that have arrived since: called as a tile's materials join the scene, before it draws. */
  update(): void;
  dispose(): void;
}

/** The code-split plugin (tileFadeChunk.ts). */
export interface TileFadeModule {
  createTileFadeOn(scene: Scene, o: { isTileMaterial: (m: object) => boolean; fadeOf: (mesh: AbstractMesh) => TileFade | undefined }): TileFadeHandle;
}
