export interface AnchorTransform {
  lat: number;
  lon: number;
  alt: number;
  /** Planet frame to scene: the anchor to the origin, its local frame to the scene's axes. */
  apply(p: Vec3): Vec3;
  /** Scene to planet frame. */
  unapply(s: Vec3): Vec3;
  /** The local axes (x west, y up, z south) in the planet frame: the rotation's rows. */
  axes: [Vec3, Vec3, Vec3];
  /** The anchor's planet point. */
  origin: Vec3;
}

export function anchorTransform(radius: number, lat: number, lon: number, alt: number): AnchorTransform {
  const f = localFrame(lat, lon);
  return anchorOf(geoPoint(radius, lat, lon, alt), [f.x, f.y, f.z], radius);
}

/** Any anchor: its planet point, and the scene's axes in the planet's frame (orthonormal, the planet's handedness). */
export function anchorOf(origin: Vec3, axes: [Vec3, Vec3, Vec3], radius: number): AnchorTransform {
  const dot = (a: Vec3, b: Vec3) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
  const { lat, lon, alt } = geoOf(origin, radius);
  return {
    lat,
    lon,
    alt,
    axes,
    origin,
    apply(p) {
      const d: Vec3 = [p[0] - origin[0], p[1] - origin[1], p[2] - origin[2]];
      return [dot(axes[0], d), dot(axes[1], d), dot(axes[2], d)];
    },
    unapply(s) {
      return [0, 1, 2].map((k) => origin[k]! + axes[0][k]! * s[0] + axes[1][k]! * s[1] + axes[2][k]! * s[2]) as Vec3;
    },
  };
}

export interface Arrival {
  at: [number, number];
  /** Metres over altitude 0, where the fragment gives one: the visitor arrives there, in the air, flying. */
  alt?: number;
  look: [number, number];
  warnings: string[];
}

/**
 * Where a visitor arrives on a planet opened directly (the profile's Arrival,
 * steps 1, 2 and 4). An `on` pair names the planet, which is the world
 * around it's to find (planetSystem.ts): here it is passed over.
 */
export function arrivalOf(planet: VemlPlanet, fragment: string): Arrival {
  const warnings: string[] = [];
  const fallback = (): Arrival => {
    const d = planet.entries.find((e) => e.id === 'default');
    return d ? { at: d.at, look: d.look, warnings } : { at: planet.spawn, look: [0, 0], warnings };
  };
  if (!fragment) return fallback();
  if (/^(at|on|look)=/.test(fragment)) {
    const pairs = new Map<string, string>();
    for (const part of fragment.split('&')) {
      const eq = part.indexOf('=');
      if (eq < 0) continue;
      let name: string, value: string;
      try {
        name = decodeURIComponent(part.slice(0, eq));
        value = decodeURIComponent(part.slice(eq + 1));
      } catch {
        warnings.push('veml:planet:unknown-fragment');
        continue;
      }
      if (!pairs.has(name)) pairs.set(name, value);
    }
    // Without `at`, the planet's own arrival.
    if (!pairs.has('at')) return fallback();
    const at = geographic(pairs.get('at'), true);
    if (!at) {
      warnings.push('veml:planet:unknown-fragment');
      return fallback();
    }
    let look: [number, number] = [0, 0];
    if (pairs.has('look')) {
      const l = planetList(pairs.get('look'), 2);
      if (!l || l[1]! < -90 || l[1]! > 90) warnings.push('veml:planet:unknown-fragment');
      else look = [l[0]!, l[1]!];
    }
    return { at: [at[0]!, at[1]!], ...(at[2] !== undefined ? { alt: at[2] } : {}), look, warnings };
  }
  let id: string;
  try {
    id = decodeURIComponent(fragment);
  } catch {
    id = fragment;
  }
  const entry = planet.entries.find((e) => e.id === id);
  if (entry) return { at: entry.at, look: entry.look, warnings };
  warnings.push('veml:planet:unknown-fragment');
  return fallback();
}

/** The camera over the feet at height `h`, looking down at them along the heading `yaw`. */
export function zoomPose(feet: Vec3, yaw: number, h: number): { position: Vec3; yaw: number; pitch: number } {
  // From 35° just off the ground to straight down (89°) from about 3 km up.
  const t = Math.min(1, Math.max(0, Math.log(Math.max(h, 1) / 2) / Math.log(3000 / 2)));
  const pitch = ((35 + (89 - 35) * t) * Math.PI) / 180;
  const back = h / Math.tan(pitch);
  // The controller's yaw 0 faces +z; the camera sits behind the feet, along −forward.
  const position: Vec3 = [feet[0] - Math.sin(yaw) * back, feet[1] + h, feet[2] - Math.cos(yaw) * back];
  return { position, yaw, pitch };
}

/** Ground this high over altitude 0 may stand beyond the horizon: higher than any mountain a planet draws. */
const HORIZON_RISE_M = 10_000;

/**
 * The camera's far plane for an eye `d` metres from the centre of a planet
 * of radius `radius`: to its horizon, and on to the tops of mountains past
 * it, or of its air (`air` metres high) where that is higher, from the
 * ground, flying or zoomed out; never under ten kilometres.
 */
export function farPlane(d: number, radius: number, air = 0): number {
  const over = (r: number) => Math.sqrt(Math.max(0, r * r - radius * radius));
  // Above the air, its sky surrounds the eye (atmosphereChunk.ts), reaching
  // a little past the eye's distance from the centre on the far side.
  const sky = air > 0 && d > radius + air ? 2.1 * d : 0;
  return Math.max(10_000, over(d) + over(radius + Math.max(HORIZON_RISE_M, air)), sky);
}

