  update(eye: Vector3, centre: Vector3, toPlanet: Matrix, sun: Vector3, timeS: number, haze: { beta: number; height: number; planetRadius: number }, strength?: number, drawn?: { centre: Vector3; scale: number }): void;
  /** Drawn in this rendering group: the away planets' (BODY_GROUP) for a planet that does not hold the visitor. */
