/**
 * Relief on a planet's blocks, worked out from their own pictures. A block's
 * picture is a cell of the chunk atlas, 16 texels square and drawn texel for
 * texel; each texel's brightness is read as its height, so the lighter specks
 * of stone stand out of the darker, and the face's light turns with the slope
 * between a texel and its neighbours. Neighbours are read only within the
 * block's own cell, so no block takes relief from the next one in the atlas.
 * Where the chunk carries its blocks' real normal maps (glTF's normalTexture,
 * a second atlas laid out as the first), a texel that has one is drawn by it
 * instead (BLOCKMAPS), scaled by the same strength.
 *
 * A world asks for it with `planet.block-relief` (`auto` 1, `none` or 0, up to
 * BLOCK_RELIEF_MAX). It is drawn by the blocks' light (blockLightChunk.ts), on
 * the chunks' ground and leaves only: not on water, plants or the far tiles.
 *
 * `reliefNormal` is the shader's sum on the CPU, for the tests: the same
 * texels read, the same slope, the same turn of the normal.
 */

/** The side of one block's picture in the chunk atlas, in texels. */
export const RELIEF_CELL = 16;
/** The shell's strength. */
export const BLOCK_RELIEF_DEFAULT = 1;
/** The strongest relief a world may ask for. */
export const BLOCK_RELIEF_MAX = 2;
/** How far a face's light turns for a step of the whole range of brightness between two neighbours, at strength 1. */
export const RELIEF_TILT = 2.5;

export type Vec3 = [number, number, number];

/** A world's relief, from its hints in force: `none` for none, `auto` or anything unreadable for the shell's. */
export function blockReliefAskOf(hint: (name: string) => string | null | undefined): number {
  const v = hint('planet.block-relief');
  if (v === null || v === undefined || v === 'auto') return BLOCK_RELIEF_DEFAULT;
  if (v === 'none') return 0;
  const x = Number(v);
  return v.trim() !== '' && Number.isFinite(x) ? Math.min(BLOCK_RELIEF_MAX, Math.max(0, x)) : BLOCK_RELIEF_DEFAULT;
}

/** The relief drawn: the world's ask on the visitor's `auto`, none at `off`, and at `on` the world's or, where it asks for none, the shell's. */
export function blockReliefOf(world: number, choice: string): number {
  if (choice === 'off') return 0;
  if (choice === 'on') return world > 0 ? world : BLOCK_RELIEF_DEFAULT;
  return world;
}

/** A texel's height: its brightness. */
export const reliefHeight = (c: Vec3): number => 0.299 * c[0] + 0.587 * c[1] + 0.114 * c[2];

const norm = (v: Vec3): Vec3 => {
  const l = Math.hypot(v[0], v[1], v[2]) || 1;
  return [v[0] / l, v[1] / l, v[2] / l];
};

/** A texel of a block's normal map as the shader reads it: the normal's components as stored (0 to 1), and 1 where there is one. */
export type MapTexel = [number, number, number, number];

/**
 * The face's normal turned by the relief at atlas texel `at`: `texel` reads the
 * atlas, `n` is the face's normal, `t` and `b` the directions the atlas's x and
 * y run along the face, and `strength` the world's. Where `map` (the chunk's
 * normal atlas) has a normal for the texel, it is the block's own shape: +X
 * along the atlas's x, +Y up the picture (against its y), its tilt scaled by
 * the strength. Elsewhere the relief is read from the picture's brightness.
 */
export function reliefNormal(texel: (x: number, y: number) => Vec3, at: [number, number], n: Vec3, t: Vec3, b: Vec3, strength: number, map?: (x: number, y: number) => MapTexel): Vec3 {
  if (strength <= 0) return n;
  const m = map?.(at[0], at[1]);
  if (m && m[3] > 0.5) {
    const mx = (m[0] * 2 - 1) * strength, my = (m[1] * 2 - 1) * strength, mz = m[2] * 2 - 1;
    const tn = norm(t), bn = norm(b);
    return norm([n[0] * mz + tn[0] * mx - bn[0] * my, n[1] * mz + tn[1] * mx - bn[1] * my, n[2] * mz + tn[2] * mx - bn[2] * my]);
  }
  const cx = Math.floor(at[0] / RELIEF_CELL) * RELIEF_CELL;
  const cy = Math.floor(at[1] / RELIEF_CELL) * RELIEF_CELL;
  const h = (dx: number, dy: number) =>
    reliefHeight(texel(Math.min(cx + RELIEF_CELL - 1, Math.max(cx, at[0] + dx)), Math.min(cy + RELIEF_CELL - 1, Math.max(cy, at[1] + dy))));
  const k = RELIEF_TILT * strength * 0.5;
  const gx = (h(1, 0) - h(-1, 0)) * k;
  const gy = (h(0, 1) - h(0, -1)) * k;
  const tn = norm(t), bn = norm(b);
  return norm([n[0] - gx * tn[0] - gy * bn[0], n[1] - gx * tn[1] - gy * bn[1], n[2] - gx * tn[2] - gy * bn[2]]);
}

const tilt = RELIEF_TILT.toFixed(2);
const cellLast = (RELIEF_CELL - 1).toFixed(0);
const cell = RELIEF_CELL.toFixed(0);

/**
 * The shader's: the texel under the fragment and its four neighbours in the
 * cell, read exactly (the atlas is drawn texel for texel); the atlas's x and y
 * along the face from the screen's derivatives, so no tangent is sent and no
 * varying added.
 */
export const RELIEF_GLSL = `#ifdef RELIEF
#ifdef BLOCKMAPS
uniform sampler2D blockNormalSampler;
#endif
float reliefH(ivec2 p) { return dot(texelFetch(albedoSampler, p, 0).rgb, vec3(0.299, 0.587, 0.114)); }
vec3 reliefOn(vec3 n, vec2 uv, vec3 pos) {
  vec2 size = vec2(textureSize(albedoSampler, 0));
  ivec2 at = ivec2(floor(uv * size));
  vec3 dp1 = dFdx(pos), dp2 = dFdy(pos);
  vec2 du1 = dFdx(uv), du2 = dFdy(uv);
  vec3 dp2perp = cross(dp2, n), dp1perp = cross(n, dp1);
  vec3 t = dp2perp * du1.x + dp1perp * du2.x;
  vec3 b = dp2perp * du1.y + dp1perp * du2.y;
  float lt = length(t), lb = length(b);
  if (lt < 1e-12 || lb < 1e-12) return n;
#ifdef BLOCKMAPS
  vec4 mapped = texelFetch(blockNormalSampler, at, 0);
  if (mapped.a > 0.5) {
    vec3 m = mapped.rgb * 2.0 - 1.0;
    return normalize(n * m.z + (t / lt) * m.x * blockRelief - (b / lb) * m.y * blockRelief);
  }
#endif
  ivec2 lo = (at / ${cell}) * ${cell};
  ivec2 hi = lo + ivec2(${cellLast});
  float k = ${tilt} * blockRelief * 0.5;
  float gx = (reliefH(clamp(at + ivec2(1, 0), lo, hi)) - reliefH(clamp(at - ivec2(1, 0), lo, hi))) * k;
  float gy = (reliefH(clamp(at + ivec2(0, 1), lo, hi)) - reliefH(clamp(at - ivec2(0, 1), lo, hi))) * k;
  return normalize(n - gx * t / lt - gy * b / lb);
}
#endif
`;

export const RELIEF_WGSL = `#ifdef RELIEF
#ifdef BLOCKMAPS
var blockNormalSamplerSampler: sampler;
var blockNormalSampler: texture_2d<f32>;
#endif
fn reliefH(p: vec2i) -> f32 { return dot(textureLoad(albedoSampler, p, 0).rgb, vec3f(0.299, 0.587, 0.114)); }
fn reliefOn(n: vec3f, uv: vec2f, pos: vec3f, dp1: vec3f, dp2: vec3f, du1: vec2f, du2: vec2f) -> vec3f {
  let size = vec2f(textureDimensions(albedoSampler, 0));
  let at = vec2i(floor(uv * size));
  let dp2perp = cross(dp2, n);
  let dp1perp = cross(n, dp1);
  let t = dp2perp * du1.x + dp1perp * du2.x;
  let b = dp2perp * du1.y + dp1perp * du2.y;
  let lt = length(t);
  let lb = length(b);
  if (lt < 1e-12 || lb < 1e-12) { return n; }
#ifdef BLOCKMAPS
  let mapped = textureLoad(blockNormalSampler, at, 0);
  if (mapped.a > 0.5) {
    let m = mapped.rgb * 2.0 - 1.0;
    return normalize(n * m.z + (t / lt) * m.x * uniforms.blockRelief - (b / lb) * m.y * uniforms.blockRelief);
  }
#endif
  let lo = (at / ${cell}) * ${cell};
  let hi = lo + vec2i(${cellLast});
  let k = ${tilt} * uniforms.blockRelief * 0.5;
  let gx = (reliefH(clamp(at + vec2i(1, 0), lo, hi)) - reliefH(clamp(at - vec2i(1, 0), lo, hi))) * k;
  let gy = (reliefH(clamp(at + vec2i(0, 1), lo, hi)) - reliefH(clamp(at - vec2i(0, 1), lo, hi))) * k;
  return normalize(n - gx * t / lt - gy * b / lb);
}
#endif
`;

/** Where the normal is turned, once the albedo is read: GLSL. WGSL takes the derivatives here, in uniform control. */
export const RELIEF_APPLY_GLSL = `#ifdef RELIEF
normalW = reliefOn(normalW, vAlbedoUV, vPositionW);
#endif
`;

export const RELIEF_APPLY_WGSL = `#ifdef RELIEF
normalW = reliefOn(normalW, fragmentInputs.vAlbedoUV, fragmentInputs.vPositionW, dpdx(fragmentInputs.vPositionW), dpdy(fragmentInputs.vPositionW), dpdx(fragmentInputs.vAlbedoUV), dpdy(fragmentInputs.vAlbedoUV));
#endif
`;
