/**
 * The planet profile's frames (specs/veml/profiles/planet.md, The frame;
 * Terrain), as plain arithmetic with no engine:
 * - a planet document's frame is VEML's (left-handed, +y up, metres) with
 *   its origin at the centre and +y the north pole;
 * - a geographic position (lat, lon, alt) is d × (radius + alt), where
 *   d = (cos lat · cos lon, sin lat, cos lat · sin lon);
 * - the local frame follows the sky profile's compass: −z north, −x east,
 *   +y up;
 * - a 3D Tiles tileset point (x, y, z) is the planet frame's (−x, z, −y).
 */

export type Vec3 = [number, number, number];

const RAD = Math.PI / 180;

/** The unit direction of a latitude and longitude, in degrees. */
export function geoDirection(lat: number, lon: number): Vec3 {
  const la = lat * RAD, lo = lon * RAD;
  return [Math.cos(la) * Math.cos(lo), Math.sin(la), Math.cos(la) * Math.sin(lo)];
}

/** A geographic position's point in the planet frame. */
export function geoPoint(radius: number, lat: number, lon: number, alt: number): Vec3 {
  const d = geoDirection(lat, lon);
  const r = radius + alt;
  return [d[0] * r, d[1] * r, d[2] * r];
}

/** A planet-frame point as latitude, longitude (in (−180, 180]) and altitude above `radius`. */
export function geoOf(p: Vec3, radius: number): { lat: number; lon: number; alt: number } {
  const r = Math.hypot(p[0], p[1], p[2]);
  const lat = Math.asin(Math.max(-1, Math.min(1, p[1] / r))) / RAD;
  let lon = Math.atan2(p[2], p[0]) / RAD;
  if (lon === -180) lon = 180;
  return { lat, lon, alt: r - radius };
}

export interface LocalFrame {
  up: Vec3;
  north: Vec3;
  east: Vec3;
  /** The local frame's axes in the planet frame: x west, y up, z south. */
  x: Vec3;
  y: Vec3;
  z: Vec3;
}

/** The local frame at a latitude and longitude. At a pole, north is the limit along the longitude. */
export function localFrame(lat: number, lon: number): LocalFrame {
  const la = lat * RAD, lo = lon * RAD;
  const up: Vec3 = [Math.cos(la) * Math.cos(lo), Math.sin(la), Math.cos(la) * Math.sin(lo)];
  // ∂d/∂lat and ∂d/∂lon, normalised; the longitude derivative's limit at a pole.
  const north: Vec3 = [-Math.sin(la) * Math.cos(lo), Math.cos(la), -Math.sin(la) * Math.sin(lo)];
  const east: Vec3 = [-Math.sin(lo), 0, Math.cos(lo)];
  return {
    up,
    north,
    east,
    x: [-east[0], -east[1], -east[2]],
    y: up,
    z: [-north[0], -north[1], -north[2]],
  };
}

/** The unit direction a heading (degrees clockwise from north, seen from above) points along the ground. */
export function headingDirection(lat: number, lon: number, heading: number): Vec3 {
  const f = localFrame(lat, lon);
  const h = heading * RAD;
  const c = Math.cos(h), s = Math.sin(h);
  return [f.north[0] * c + f.east[0] * s, f.north[1] * c + f.east[1] * s, f.north[2] * c + f.east[2] * s];
}

/** A 3D Tiles tileset point (right-handed, z up) in the planet frame. */
export function tilesetToPlanet(p: Vec3): Vec3 {
  return [-p[0], p[2], -p[1]];
}

/** A planet-frame point in a 3D Tiles tileset's frame. */
export function planetToTileset(p: Vec3): Vec3 {
  return [-p[0], -p[2], p[1]];
}
