/**
 * Sites: worlds placed on a planet's surface (specs/veml/profiles/planet.md,
 * Sites). A site's document frame is the local frame at its position, turned
 * clockwise by its heading: its origin there, its +y up and its −z facing the
 * heading. A planet may declare any number of them, so the bound is spatial:
 * a site loads once its declared bounds reach within the load distance of
 * the viewer, at most so many are held at once (never fewer than 16), and
 * the farthest go first. Never more than 64 at once, the most loaded sites a
 * world's whole include tree may hold.
 *
 * What a site's document is, and how it is built, is the host's (`load`):
 * here it only gets a node to stand under, and is let go of with it.
 */

import { TransformNode } from '@babylonjs/core/Meshes/transformNode';
import { Matrix, Quaternion } from '@babylonjs/core/Maths/math.vector';
import type { Scene } from '@babylonjs/core/scene';
import type { VemlPlanetSite } from '../../veml/documentModel';
import { geoPoint, headingDirection, localFrame, type Vec3 } from './planetFrame';

export interface SitePlace {
  /** The site's origin in the planet's frame. */
  position: Vec3;
  /** The site's own x, y and z axes in the planet's frame. */
  axes: [Vec3, Vec3, Vec3];
}

const neg = (v: Vec3): Vec3 => [-v[0], -v[1], -v[2]];

/** Where a site stands on a planet of radius `radius`, and which way it faces. */
export function sitePlacement(radius: number, site: Pick<VemlPlanetSite, 'at' | 'heading'>): SitePlace {
  const [lat, lon, alt] = [site.at[0] ?? 0, site.at[1] ?? 0, site.at[2] ?? 0];
  return {
    position: geoPoint(radius, lat, lon, alt),
    // Its −z faces the heading and its −x a quarter turn further round, as the local frame's −z north and −x east do.
    axes: [neg(headingDirection(lat, lon, site.heading + 90)), localFrame(lat, lon).up, neg(headingDirection(lat, lon, site.heading))],
  };
}

/** How far off, in metres, a site's bounds may be and still load, and how many are held at once, when the world does not say. */
export const SITE_DEFAULTS = { distance: 2000, limit: 16 };
/** The fewest sites a shell may hold at once. */
const LEAST_LIMIT = 16;
/** The most sites held at once: a world's whole include tree holds no more than 64 loaded sites. */
const MOST_LIMIT = 64;
/** How much further than the load distance a loaded site may be before it is let go: it does not come and go at one line. */
const LET_GO = 1.25;

/** The world's `planet.site-distance` and `planet.site-limit` hints, or the shell's for `auto`, nothing, or what is not a number. */
export function siteAskOf(hint: (name: string) => string | null | undefined): { distance: number; limit: number } {
  const n = (name: string): number | undefined => {
    const v = Number(hint(name) ?? NaN);
    return Number.isFinite(v) && v > 0 ? v : undefined;
  };
  return { distance: n('planet.site-distance') ?? SITE_DEFAULTS.distance, limit: Math.min(MOST_LIMIT, Math.max(LEAST_LIMIT, Math.floor(n('planet.site-limit') ?? SITE_DEFAULTS.limit))) };
}

/**
 * The sites whose bounds reach within the load distance of `eye` (a loaded one
 * until it is well past it), nearest first, with how far off their bounds are.
 */
export function sitesNear(sites: readonly { centre: Vec3; radius: number }[], eye: Vec3, loaded: ReadonlySet<number>, distance: number): { i: number; d: number }[] {
  const near: { i: number; d: number }[] = [];
  sites.forEach((s, i) => {
    const d = Math.hypot(s.centre[0] - eye[0], s.centre[1] - eye[1], s.centre[2] - eye[2]) - s.radius;
    if (d <= distance || (loaded.has(i) && d <= distance * LET_GO)) near.push({ i, d });
  });
  return near.sort((a, b) => a.d - b.d);
}

/**
 * The world's one budget of loaded sites, shared by its planets: a world's
 * whole include tree holds no more than 64 loaded documents, its includes'
 * (`taken`) and its sites' together, and no more sites than the world asks
 * for. Each planet says how far off the sites it wants are; its share is how
 * many of them are among the nearest the budget allows across every planet,
 * so where the budget is short, the farthest go first wherever they are.
 */
export interface SiteBudget {
  /** `owner`'s share, given the distances of the sites it wants (nearest first) and the world's own limit. */
  allowance(owner: object, wanted: readonly number[], limit: number): number;
  /** `owner` wants no more sites: its share goes back. */
  release(owner: object): void;
}

export function createSiteBudget(taken: () => number = () => 0): SiteBudget {
  const wants = new Map<object, readonly number[]>();
  return {
    allowance(owner, wanted, limit) {
      wants.set(owner, wanted);
      const cap = Math.max(0, Math.min(limit, MOST_LIMIT - taken()));
      const all: { owner: object; d: number }[] = [];
      for (const [o, ds] of wants) for (const d of ds) all.push({ owner: o, d });
      all.sort((a, b) => a.d - b.d);
      return all.slice(0, cap).filter((w) => w.owner === owner).length;
    },
    release(owner) {
      wants.delete(owner);
    },
  };
}

/**
 * Which sites to load and which to let go, for a viewer at `eye`: those whose
 * bounds reach within the load distance, nearest first, up to the limit; a
 * loaded one stays until it is well past it. Let go farthest first.
 */
export function sitesToHold(
  sites: readonly { centre: Vec3; radius: number }[],
  eye: Vec3,
  loaded: ReadonlySet<number>,
  ask: { distance: number; limit: number },
): { load: number[]; unload: number[] } {
  const near = sitesNear(sites, eye, loaded, ask.distance);
  const keep = new Set(near.slice(0, Math.min(ask.limit, MOST_LIMIT)).map((n) => n.i));
  const load = near.filter((n) => keep.has(n.i) && !loaded.has(n.i)).map((n) => n.i);
  const distance = (i: number) => {
    const c = sites[i]!.centre;
    return Math.hypot(c[0] - eye[0], c[1] - eye[1], c[2] - eye[2]) - sites[i]!.radius;
  };
  const unload = [...loaded].filter((i) => !keep.has(i)).sort((a, b) => distance(b) - distance(a));
  return { load, unload };
}

/** A site's world, built by the host: let go of with `dispose`. */
export interface SiteHandle {
  dispose(): void;
}

/** Builds a site's document under `parent`; undefined when it cannot be (a failed fetch, a planet). */
export type LoadSite = (site: VemlPlanetSite, parent: TransformNode) => Promise<SiteHandle | undefined>;

export interface Sites {
  /** The viewer is at `eye`, in the planet's frame: load and let go. */
  tick(eye: Vec3): void;
  /** The sites held, or on their way, by their place in the list. */
  loaded(): number[];
  idle(): Promise<void>;
  dispose(): void;
}

export function createSites(o: {
  scene: Scene;
  /** The node the planet's frame hangs from. */
  root: TransformNode;
  radius: number;
  sites: readonly VemlPlanetSite[];
  load: LoadSite;
  ask: () => { distance: number; limit: number };
  /** The world's budget of loaded sites, shared with its other planets; without it, this planet's alone. */
  budget?: SiteBudget;
  warn: (name: string, detail: string) => void;
}): Sites {
  const self = {};
  const places = o.sites.map((s) => ({ site: s, place: sitePlacement(o.radius, s) }));
  const bounds = places.map((p) => ({ centre: p.place.position, radius: p.site.radius }));
  const held = new Map<number, { node: TransformNode; handle?: SiteHandle; gone: boolean }>();
  const pending = new Set<Promise<unknown>>();
  const letGo = (i: number) => {
    const h = held.get(i);
    if (!h) return;
    held.delete(i);
    h.gone = true;
    h.handle?.dispose();
    h.node.dispose();
  };
  const bring = (i: number) => {
    const { site, place } = places[i]!;
    const node = new TransformNode(`site:${site.href.raw}`, o.scene);
    node.parent = o.root;
    node.position.set(...place.position);
    const [x, y, z] = place.axes;
    // Babylon's rows are the images of the node's own axes.
    node.rotationQuaternion = Quaternion.FromRotationMatrix(Matrix.FromValues(x[0], x[1], x[2], 0, y[0], y[1], y[2], 0, z[0], z[1], z[2], 0, 0, 0, 0, 1));
    const entry: { node: TransformNode; handle?: SiteHandle; gone: boolean } = { node, gone: false };
    held.set(i, entry);
    const p = (async () => {
      try {
        const handle = await o.load(site, node);
        if (!handle) return;
        if (entry.gone) handle.dispose();
        else entry.handle = handle;
      } catch (err) {
        o.warn('veml:planet:invalid-site', `${site.href.resolved}: ${String(err)}`);
      }
    })();
    pending.add(p);
    void p.finally(() => pending.delete(p));
  };
  return {
    tick(eye) {
      if (!places.length) return;
      const loaded = new Set(held.keys());
      const ask = o.ask();
      // This planet's share of the world's budget, by how near its wanted sites are against every other planet's.
      const limit = o.budget ? o.budget.allowance(self, sitesNear(bounds, eye, loaded, ask.distance).map((n) => n.d), ask.limit) : ask.limit;
      const { load, unload } = sitesToHold(bounds, eye, loaded, { distance: ask.distance, limit });
      for (const i of unload) letGo(i);
      for (const i of load) bring(i);
    },
    loaded: () => [...held.keys()].sort((a, b) => a - b),
    async idle() {
      while (pending.size) await Promise.allSettled([...pending]);
    },
    dispose() {
      for (const i of [...held.keys()]) letGo(i);
      o.budget?.release(self);
    },
  };
}
