/**
 * The cube-sphere surface scheme (specs/veml/profiles/planet-cube-sphere.md),
 * as plain arithmetic with no engine: the description's `surface`, the
 * mapping between a face's grid and the sphere, an area's blocks, and the map
 * that draws an area near the viewer.
 *
 * Directions and points here are in the planet frame (planet.md, left-handed,
 * +y north). The scheme's table is written in a right-handed frame, which is
 * the planet frame with z negated.
 */

import { resolveWorldUri } from '../../veml/uriResolve';
import type { Vec3 } from './planetFrame';

export const CUBE_SPHERE_SCHEME = 'https://www.fivesqd.com/schemas/veml/4.0/profiles/planet/schemes/cube-sphere/1';

export type Face = 'px' | 'nx' | 'py' | 'ny' | 'pz' | 'nz';
const FACES: readonly Face[] = ['px', 'nx', 'py', 'ny', 'pz', 'nz'];

export interface CubeSphere {
  faceBlocks: number;
  /** W: blocks along an area slot's side. */
  areaBlocks: number;
  areasPerFaceEdge: number;
  altitudeZeroY: number;
  /** Chunk templates by slot key (`face,ax,az`), resolved against `base` when used. */
  areas: ReadonlyMap<string, string>;
  base: string;
}

/** An area slot on a face. */
export interface Slot {
  face: Face;
  ax: number;
  az: number;
  key: string;
}

const INVALID = 'veml:planet:cube-sphere-invalid';
const MAX_AREAS = 100_000;
const isInt = (n: unknown): n is number => typeof n === 'number' && Number.isInteger(n);

const originOf = (url: string): string | undefined => {
  try {
    return new URL(url).origin;
  } catch {
    return undefined;
  }
};

/** A chunk template filled: its corner, and the style the ground is drawn in (planetDescription.ts); any other name, nothing. */
const expand = (template: string, x: number, y: number, z: number, style = ''): string =>
  template.replace(/\{([^{}]*)\}/g, (_, name: string) => (name === 'x' ? String(x) : name === 'y' ? String(y) : name === 'z' ? String(z) : name === 'style' ? style : ''));

/** The description's `surface`, or nothing (with a warning) when it is invalid. */
export function readCubeSphere(surface: Record<string, unknown>, descriptionUrl: string): { surface?: CubeSphere; warnings: string[] } {
  const warnings: string[] = [];
  const T = surface.tilesPerFaceEdge, B = surface.tileBlocks, n = surface.areasPerFaceEdge, zeroY = surface.altitudeZeroY;
  const valid =
    isInt(T) && T >= 1 && (T & (T - 1)) === 0 &&
    isInt(B) && B >= 1 &&
    isInt(n) && n >= 1 && T % n === 0 &&
    T * B <= 2 ** 24 &&
    typeof zeroY === 'number' && Number.isFinite(zeroY);
  if (!valid) return { warnings: [INVALID] };
  const areas = new Map<string, string>();
  const list = Array.isArray(surface.areas) ? surface.areas.slice(0, MAX_AREAS) : [];
  for (const entry of list) {
    const e = entry && typeof entry === 'object' ? (entry as Record<string, unknown>) : {};
    const m = typeof e.slot === 'string' ? /^(px|nx|py|ny|pz|nz),(\d+),(\d+)$/.exec(e.slot) : null;
    if (!m || Number(m[2]) >= n || Number(m[3]) >= n) return { warnings: [INVALID] };
    const key = `${m[1]},${Number(m[2])},${Number(m[3])}`;
    if (areas.has(key)) continue;
    const t = e.chunks;
    const ok =
      typeof t === 'string' && t.includes('{x}') && t.includes('{y}') && t.includes('{z}') &&
      originOf(resolveWorldUri(expand(t, 0, 0, 0), descriptionUrl)) === originOf(descriptionUrl);
    if (!ok) {
      warnings.push(INVALID);
      continue;
    }
    areas.set(key, t);
  }
  return {
    surface: { faceBlocks: T * B, areaBlocks: (T / n) * B, areasPerFaceEdge: n, altitudeZeroY: zeroY, areas, base: descriptionUrl },
    warnings,
  };
}

// ---- the mapping -----------------------------------------------------------------

/** A face coordinate (u, v) as a cube point, right-handed (the scheme's table). */
function cubePoint(face: Face, u: number, v: number): Vec3 {
  switch (face) {
    case 'px': return [1, v, -u];
    case 'nx': return [-1, v, u];
    case 'py': return [u, 1, -v];
    case 'ny': return [u, -1, v];
    case 'pz': return [u, v, 1];
    case 'nz': return [-u, v, -1];
  }
}

function spherify(c: Vec3): Vec3 {
  const x2 = c[0] * c[0], y2 = c[1] * c[1], z2 = c[2] * c[2];
  return [
    c[0] * Math.sqrt(1 - y2 / 2 - z2 / 2 + (y2 * z2) / 3),
    c[1] * Math.sqrt(1 - x2 / 2 - z2 / 2 + (x2 * z2) / 3),
    c[2] * Math.sqrt(1 - x2 / 2 - y2 / 2 + (x2 * y2) / 3),
  ];
}

/** The unit direction, in the planet frame, of grid position (gx, gz) on a face. */
export function gridDirection(faceBlocks: number, face: Face, gx: number, gz: number): Vec3 {
  const s = spherify(cubePoint(face, -1 + (2 * gx) / faceBlocks, -1 + (2 * gz) / faceBlocks));
  return [s[0], s[1], -s[2]];
}

/**
 * The grid position of a planet-frame direction: the face of its largest
 * component (x before y before z on a tie), then Newton's method from the
 * gnomonic estimate for the cube point that the spherification sends to it.
 */
export function gridOfDirection(faceBlocks: number, dir: Vec3): { face: Face; gx: number; gz: number } {
  const len = Math.hypot(dir[0], dir[1], dir[2]);
  const r: Vec3 = [dir[0] / len, dir[1] / len, -dir[2] / len];
  const a = r.map(Math.abs);
  const i = a[0]! >= a[1]! && a[0]! >= a[2]! ? 0 : a[1]! >= a[2]! ? 1 : 2;
  const j = (i + 1) % 3, k = (i + 2) % 3;
  const sign = r[i]! >= 0 ? 1 : -1;
  const c: Vec3 = [0, 0, 0];
  c[i] = sign;
  c[j] = r[j]! / a[i]!;
  c[k] = r[k]! / a[i]!;
  for (let it = 0; it < 30; it++) {
    const s = spherify(c);
    const fj = s[j]! - r[j]!, fk = s[k]! - r[k]!;
    if (Math.abs(fj) < 1e-15 && Math.abs(fk) < 1e-15) break;
    // The Jacobian of the two free components, by central differences.
    const h = 1e-7;
    const at = (dj: number, dk: number) => {
      const p: Vec3 = [c[0], c[1], c[2]];
      p[j] = p[j]! + dj;
      p[k] = p[k]! + dk;
      return spherify(p);
    };
    const pj = at(h, 0), mj = at(-h, 0), pk = at(0, h), mk = at(0, -h);
    const a11 = (pj[j]! - mj[j]!) / (2 * h), a21 = (pj[k]! - mj[k]!) / (2 * h);
    const a12 = (pk[j]! - mk[j]!) / (2 * h), a22 = (pk[k]! - mk[k]!) / (2 * h);
    const det = a11 * a22 - a12 * a21;
    if (det === 0) break;
    c[j] = Math.max(-1, Math.min(1, c[j] - (a22 * fj - a12 * fk) / det));
    c[k] = Math.max(-1, Math.min(1, c[k] - (a11 * fk - a21 * fj) / det));
  }
  let face: Face, u: number, v: number;
  if (i === 0) [face, u, v] = sign > 0 ? ['px', -c[2], c[1]] : ['nx', c[2], c[1]];
  else if (i === 1) [face, u, v] = sign > 0 ? ['py', c[0], -c[2]] : ['ny', c[0], c[2]];
  else [face, u, v] = sign > 0 ? ['pz', c[0], c[1]] : ['nz', -c[0], c[1]];
  return { face, gx: ((u + 1) / 2) * faceBlocks, gz: ((v + 1) / 2) * faceBlocks };
}

// ---- areas -----------------------------------------------------------------------

/** The slot holding grid position (gx, gz), or nothing off the face. */
export function slotOfGrid(cs: CubeSphere, face: Face, gx: number, gz: number): Slot | undefined {
  if (!FACES.includes(face) || !(gx >= 0 && gz >= 0 && gx < cs.faceBlocks && gz < cs.faceBlocks)) return undefined;
  const ax = Math.floor(gx / cs.areaBlocks), az = Math.floor(gz / cs.areaBlocks);
  return { face, ax, az, key: `${face},${ax},${az}` };
}

/** The grid block that is the area's block (0, ·, 0). */
const areaBase = (cs: CubeSphere, slot: Slot) => {
  const half = Math.floor(cs.areaBlocks / 2);
  return { gx: slot.ax * cs.areaBlocks + half, gz: slot.az * cs.areaBlocks + half };
};

/** A point in a slot's area coordinates (blocks, +y up) as a planet-frame point. */
export function areaToPlanet(cs: CubeSphere, radius: number, slot: Slot, a: Vec3): Vec3 {
  const b = areaBase(cs, slot);
  const d = gridDirection(cs.faceBlocks, slot.face, b.gx + a[0] + 0.5, b.gz + a[2] + 0.5);
  const r = radius + a[1] - cs.altitudeZeroY;
  return [d[0] * r, d[1] * r, d[2] * r];
}

/** A planet-frame point in a slot's area coordinates, or nothing when it lies on another face. */
export function planetToArea(cs: CubeSphere, radius: number, slot: Slot, p: Vec3): Vec3 | undefined {
  const g = gridOfDirection(cs.faceBlocks, p);
  if (g.face !== slot.face) return undefined;
  const b = areaBase(cs, slot);
  return [g.gx - b.gx - 0.5, Math.hypot(p[0], p[1], p[2]) - radius + cs.altitudeZeroY, g.gz - b.gz - 0.5];
}

/** The URL of the area chunk with lowest corner (x, y, z), in a style, or nothing for a slot with no area. */
export function chunkUrl(cs: CubeSphere, slot: Slot, x: number, y: number, z: number, style?: string): string | undefined {
  const t = cs.areas.get(slot.key);
  return t === undefined ? undefined : resolveWorldUri(expand(t, x, y, z, style), cs.base);
}

/**
 * The map that draws a slot's area near the viewer, as a row-vector matrix
 * (scene = [a, 1] · M, Babylon's order): the mapping's first-order expansion
 * at the viewer's own area point `at`, carried into the scene by `toScene`.
 * Blocks under the viewer land exactly where the planet has them, and stay
 * within the planet's curvature of it nearby, so the blocks meet the terrain
 * drawn through the mapping without a seam.
 */
export function areaMap(cs: CubeSphere, radius: number, slot: Slot, at: Vec3, toScene: (p: Vec3) => Vec3): number[] {
  const S = (a: Vec3) => toScene(areaToPlanet(cs, radius, slot, a));
  const axis = (k: number): Vec3 => {
    const p: Vec3 = [at[0], at[1], at[2]];
    const m: Vec3 = [at[0], at[1], at[2]];
    p[k] = p[k]! + 0.5;
    m[k] = m[k]! - 0.5;
    const sp = S(p), sm = S(m);
    return [sp[0] - sm[0], sp[1] - sm[1], sp[2] - sm[2]];
  };
  const X = axis(0), Y = axis(1), Z = axis(2);
  const o = S(at);
  const t = [0, 1, 2].map((c) => o[c]! - (at[0] * X[c]! + at[1] * Y[c]! + at[2] * Z[c]!));
  return [X[0], X[1], X[2], 0, Y[0], Y[1], Y[2], 0, Z[0], Z[1], Z[2], 0, t[0]!, t[1]!, t[2]!, 1];
}
