/**
 * The sky's fill light on a planet, turned and coloured as the day makes
 * it: a face turned up takes the sky's own colour (bluer under a clear noon
 * sky, warmer at sunset), a face turned down the light the sunlit ground
 * about the visitor throws back up (warm over sand, dim over dark grass),
 * and a face turned sideways a blend of the two by how it is turned. This is
 * what fills the shadows; the sun's own light is not touched.
 *
 * The world's own hemispheric light is left as it set it. What changes is
 * added on the planet's ground (blockLightChunk.ts): the difference between
 * that light recoloured and the light as set, so where the world asks for
 * none (`planet.sky-fill`: `auto` 1, `none` or 0, up to 2) nothing is added
 * and the ground is drawn exactly as before. On a chunk's face it is scaled
 * by the face's sky light, so a face the sky never reaches, as in a sealed
 * cave, takes none of it; the far tiles, open to the sky, take all of it.
 *
 * Pure: the planet view reads the sky and the ground, and the block light's
 * plugin draws the difference.
 */

export type Vec3 = [number, number, number];

/** The shell's strength, and the strongest a world may ask for. */
export const SKY_FILL_DEFAULT = 1;
export const SKY_FILL_MAX = 2;
/** The brightest the ground's colour may be made, so a sunlit snowfield does not light the undersides of things past reason. */
const GROUND_MAX = 1.5;
/**
 * How far toward the sky's hue the light from above goes at strength 1: the
 * sky's colour as seen is far more saturated than the light it casts, which
 * the whole sky's spread of colours and the sun's own glow in it pale. All
 * the way, sunlit grey gravel turned plainly blue.
 */
const SKY_HUE = 0.5;
/** At or below this sky light a face is shut from the sky, as in a cave, and takes none of the change; at or above OPEN, all of it. */
export const SKY_SHUT = 0.05;
export const SKY_OPEN = 0.3;

/** A world's sky fill, from its hints in force: `none` for none, `auto` or anything unreadable for the shell's. */
export function skyFillAskOf(hint: (name: string) => string | null | undefined): number {
  const v = hint('planet.sky-fill');
  if (v === null || v === undefined || v === 'auto') return SKY_FILL_DEFAULT;
  if (v === 'none') return 0;
  const x = Number(v);
  return v.trim() !== '' && Number.isFinite(x) ? Math.min(SKY_FILL_MAX, Math.max(0, x)) : SKY_FILL_DEFAULT;
}

/** How bright a linear colour looks (Rec. 709). */
export const luma = (c: Vec3): number => 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];

export interface SkyFillInput {
  /** The world's hemispheric light as it set it: its sky colour and its ground colour. */
  world: { sky: Vec3; ground: Vec3 };
  /** What the sky gives a face turned up: its colour overhead and about the horizon, together. */
  sky: Vec3;
  /** The ground about the visitor: its mean colour, linear. */
  ground: Vec3;
  /** The sun's light on the ground: its colour times its strength, times how squarely it meets level ground (0 once it has set). */
  sunOnGround: Vec3;
  /** The hemispheric light's strength this frame, as the planet sets it. */
  fill: number;
  /** The world's strength, 0 to SKY_FILL_MAX. */
  strength: number;
}

/**
 * The hemispheric light's sky and ground colours, recoloured for this
 * moment. At strength 0 they are the world's exactly; at 1, the sky colour
 * is the world's turned SKY_HUE of the way to the sky's hue at the same
 * brightness, and the ground
 * colour is what the sunlit ground throws back up, over the light's
 * strength (so a face turned down takes the ground's light); past 1, further.
 */
export function skyFillOf(i: SkyFillInput): { sky: Vec3; ground: Vec3 } {
  const s = Math.min(SKY_FILL_MAX, Math.max(0, i.strength));
  if (s === 0) return { sky: [...i.world.sky], ground: [...i.world.ground] };
  const l = luma(i.sky);
  const hue: Vec3 = l > 1e-6 ? (i.sky.map((c) => c / l) as Vec3) : [1, 1, 1];
  const sky = i.world.sky.map((c, k) => Math.max(0, c * (1 + s * SKY_HUE * (hue[k]! - 1)))) as Vec3;
  const target = i.ground.map((c, k) => Math.min(GROUND_MAX, (c * i.sunOnGround[k]!) / Math.max(i.fill, 1e-3))) as Vec3;
  const ground = i.world.ground.map((c, k) => Math.min(GROUND_MAX, Math.max(0, c + s * (target[k]! - c)))) as Vec3;
  return { sky, ground };
}

/** What the ground's plugin adds: the recoloured light less the light as set, each times the light's strength. Zero at strength 0. */
export function skyFillChange(i: SkyFillInput): { sky: Vec3; ground: Vec3 } {
  const c = skyFillOf(i);
  return {
    sky: c.sky.map((v, k) => (v - i.world.sky[k]!) * i.fill) as Vec3,
    ground: c.ground.map((v, k) => (v - i.world.ground[k]!) * i.fill) as Vec3,
  };
}

/** What a hemispheric light gives a face whose normal is at cosine `up` to straight up, as Babylon lights it: the ground colour turned down, the sky colour turned up, between them by how it is turned. */
export function hemisphericOn(up: number, sky: Vec3, ground: Vec3, fill: number): Vec3 {
  const t = 0.5 + 0.5 * up;
  return [0, 1, 2].map((k) => (ground[k]! + (sky[k]! - ground[k]!) * t) * fill) as Vec3;
}

const smoothstep = (a: number, b: number, v: number) => {
  const t = Math.min(1, Math.max(0, (v - a) / (b - a)));
  return t * t * (3 - 2 * t);
};

/**
 * What the change adds to a face of colour `albedo` turned at cosine `up` to
 * straight up, as the plugin adds it: the change's light on the face, in its
 * colour, by how open it is to the sky (`sky` 0 to 1; a far tile is open).
 */
export function skyFillAdded(albedo: Vec3, sky: number, up: number, change: { sky: Vec3; ground: Vec3 }): Vec3 {
  const open = smoothstep(SKY_SHUT, SKY_OPEN, sky);
  const light = hemisphericOn(up, change.sky, change.ground, 1);
  return [0, 1, 2].map((k) => albedo[k]! * light[k]! * open) as Vec3;
}
