/**
 * A planet's water reflects its sky. Water mirrors little of the sky looking
 * straight down and nearly all of it at a grazing angle (Fresnel's law, in
 * Schlick's form, for water's reflectance of about 2% head on); the sky it
 * mirrors is the sky where the reflected view points: its colour overhead,
 * toward the sun and away from it at the horizon, as the air makes it
 * (atmosphere.ts); the sun shows as a glint, coloured by the air its light
 * came through, sharp close to and spreading with distance, as far water's
 * ripples blur into it, and gone once it has set; far water keeps a sheen of
 * sky. The surface moves as waterMotion.ts lays out: the swell and the ripple
 * lean it, the swell and the tide raise it. Water hides its bed as it
 * deepens: as far as the eye sees through it, where its depth is measured,
 * or a few metres' depth along the eye's slant where it is not. Under it, the
 * eye sees the world's water colour, darker and bluer-green the deeper it is
 * (underwaterLook).
 *
 * This is the reference the water's shader (waterReflectChunk.ts) follows,
 * on the processor, and the small controller the planet view drives it with:
 * it fetches the code-split chunk only when the reflections are on, and feeds
 * it each frame.
 */
import type { Scene } from '@babylonjs/core/scene';
import { skyColour, sunlight, type Atmosphere } from './atmosphere';
import type { Vec3 } from './planetFrame';
import { mirrorOf } from './waterMirror';
import {
  SHORE_DEFAULTS,
  STILL_DAY_TIDE_S,
  WATER_MOTION_DEFAULTS,
  WAVE_CLOCK_S,
  glintSharpness,
  rangeSheen,
  rippleSlope,
  swellSlope,
  tideHeight,
  waterOpacity,
  waterRaise,
  waveFrameAt,
  type WaterMotion,
  type WaveFrame,
} from './waterMotion';

/** Water's reflectance looking straight down. */
export const WATER_F0 = 0.02;
/** How bright the sun's glint is close to; spread wider far off, it dims as the square root of its sharpness. */
const GLINT_STRENGTH = 6;
/** Metres of water the eye is taken to look down through where the water's depth is not measured. */
const ASSUMED_DEPTH_M = 2.5;
/** How far over the horizon the horizon's sky colours are taken from, as a share of the up direction. */
const HORIZON_RISE = 0.08;

/** The numbers the shader must carry as the reference does, written as it writes them. */
export const WATER_CONSTANTS = ['0.02', '6.0', '2.5'] as const;

/** The sky a water surface reflects: three of its colours and the sun's glint. */
export interface WaterSky {
  zenith: Vec3;
  /** At the horizon, toward the sun and away from it. */
  towardSun: Vec3;
  awaySun: Vec3;
  /** The sun's light reaching the water, 0 once it has set. */
  glint: Vec3;
}

/** What the water's shader is given each frame. Positions and directions are the scene's. */
export interface WaterReflectState {
  eye: Vec3;
  centre: Vec3;
  /** Toward the sun. */
  sun: Vec3;
  sky: WaterSky;
  /** How much of the sky the water mirrors, against water's own reflectance: 0 none, 1 as water does. */
  strength: number;
  /** How much the ripple leans the surface: 0 still water, 1 a light ripple. */
  ripple: number;
  /** The waves' clock, seconds, starting again every WAVE_CLOCK_S. */
  timeS: number;
  /** How the water moves, as the world asks. */
  motion: WaterMotion;
  /** The frame the waves are laid out in, in the scene: a point near the visitor, and east and north there. */
  waveOrigin: Vec3;
  waveEast: Vec3;
  waveNorth: Vec3;
  /** The tide's height now, metres over the level the water is drawn at (0 or less). */
  tideNow: number;
  /** Whether the water measures how deep it is from what lies behind it (the quality tier's). */
  depth: boolean;
  /** How white the foam on the shores is (0 none, 1 the shell's), and how deep a band of water it lies on, metres; drawn where the depth is measured. */
  foam: number;
  foamWidth: number;
  /** How bright the sun's caustics on the beds are: 0 none, 1 the shell's. */
  caustics: number;
  /** The colour of the water about an eye under it, which its surface mirrors to that eye outside the window it sees the sky through. */
  under: Vec3;
  /** Metres of water over an eye under it, up to its surface; 0 while the eye is out of the water. */
  overEye: number;
  /** How far the eye is under the water, 0 out of it to 1 under it, blended over a few centimetres at the surface: the surface is seen from below by it. */
  eyeUnder: number;
  /** How thick the fog about an eye under the water is, per metre: laid on every lit material by the water's plugins. */
  fogDensity: number;
  /** How much the water mirrors what stands over it, from the picture drawn (waterMirror.ts): 0 none, 1 all of it; none where left out. */
  mirror?: number;
  /** The share of the trace's full detail the visitor's tier takes, 0 to 1. */
  mirrorDetail?: number;
}

/** What a world asks of its water's reflections (read live). */
export interface WaterReflectAsk {
  on: boolean;
  strength: number;
  ripple: number;
  /** The shore's: as SHORE_DEFAULTS, the shell's where left out. */
  foam?: number;
  foamWidth?: number;
  caustics?: number;
  /** How much the water mirrors what stands over it, 0 to 1: all of it where left out. */
  mirror?: number;
}

/** A picture the engine has drawn (Babylon's internal texture), handed through here without this module knowing its type. */
export interface DrawnPicture {
  readonly width: number;
  readonly height: number;
}

/** The shell's defaults: water reflects as water does, with a light ripple. */
export const WATER_DEFAULTS: WaterReflectAsk = { on: true, strength: 1, ripple: 1 };

export interface WaterReflectHandle {
  update(state: WaterReflectState): void;
  dispose(): void;
}

export interface WaterReflectModule {
  /**
   * With `groundCaustics`, the ground under the water takes the sun's caustics while the eye is in it. `previousFrame` gives
   * the picture drawn the frame before, which the water mirrors what stands over it from; without it, the water keeps its own.
   */
  createWaterReflectionsOn(scene: Scene, opts: { engineKind?: string; groundCaustics?: boolean; previousFrame?: () => DrawnPicture | null }): WaterReflectHandle;
}

const dot = (a: Vec3, b: Vec3) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const unit = (v: Vec3): Vec3 => {
  const l = Math.hypot(v[0], v[1], v[2]) || 1;
  return [v[0] / l, v[1] / l, v[2] / l];
};

/** How much water mirrors, looking at it with `cosine` the cosine of the angle from its normal. */
export function fresnel(cosine: number, f0 = WATER_F0): number {
  const c = Math.min(1, Math.max(0, cosine));
  return f0 + (1 - f0) * (1 - c) ** 5;
}

/**
 * The water's normal at the scene point `p`: up from the planet's centre,
 * leaned by the swell and the ripple, as seen from `distance` metres. Here
 * the scene's axes are taken to be the planet's (its centre at `centre`); the
 * waves lie in `frame` (by default, about the scene's origin).
 */
export function waterNormal(p: Vec3, centre: Vec3, o: { ripple: number; timeS: number; distance: number; motion?: WaterMotion; frame?: WaveFrame }): Vec3 {
  const q: Vec3 = [p[0] - centre[0], p[1] - centre[1], p[2] - centre[2]];
  const n = unit(q);
  const motion = o.motion ?? { ...WATER_MOTION_DEFAULTS, tidePeriod: STILL_DAY_TIDE_S };
  const frame = o.frame ?? waveFrameAt([-centre[0], -centre[1], -centre[2]]);
  const a = swellSlope(q, motion, o.timeS, o.distance, frame);
  const b = rippleSlope(q, motion, o.timeS, o.distance, frame, o.ripple);
  let slope: Vec3 = [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
  const along = dot(slope, n);
  slope = [slope[0] - n[0] * along, slope[1] - n[1] * along, slope[2] - n[2] * along];
  return unit([n[0] - slope[0], n[1] - slope[1], n[2] - slope[2]]);
}

/**
 * The water's colour at the scene point `p` given its own `base` colour and
 * see-through `alpha`, as the eye sees it with the sky in it: the sky mixed in
 * by Fresnel's share, the sun's glint added, and the water as opaque as it
 * mirrors.
 */
export function waterReflected(
  base: Vec3,
  p: Vec3,
  s: { eye: Vec3; centre: Vec3; sun: Vec3; sky: WaterSky; strength: number; ripple: number; timeS: number; motion?: WaterMotion; thickness?: number; clarity?: number },
  alpha = 0.6,
): { color: Vec3; alpha: number } {
  if (s.strength <= 0) return { color: base, alpha };
  const up = unit([p[0] - s.centre[0], p[1] - s.centre[1], p[2] - s.centre[2]]);
  const toEye: Vec3 = [s.eye[0] - p[0], s.eye[1] - p[1], s.eye[2] - p[2]];
  const distance = Math.hypot(...toEye);
  const v = unit(toEye);
  const n = waterNormal(p, s.centre, { ripple: s.ripple, timeS: s.timeS, distance, ...(s.motion ? { motion: s.motion } : {}) });
  // The view reflected in the surface: r = −v + 2 (v·n) n.
  const vn = dot(v, n);
  const r: Vec3 = [2 * vn * n[0] - v[0], 2 * vn * n[1] - v[1], 2 * vn * n[2] - v[2]];
  const e = Math.min(1, Math.max(0, dot(r, up)));
  const sun = unit(s.sun);
  const rh: Vec3 = [r[0] - up[0] * dot(r, up), r[1] - up[1] * dot(r, up), r[2] - up[2] * dot(r, up)];
  const sh: Vec3 = [sun[0] - up[0] * dot(sun, up), sun[1] - up[1] * dot(sun, up), sun[2] - up[2] * dot(sun, up)];
  const toward = Math.hypot(...rh) > 1e-4 && Math.hypot(...sh) > 1e-4 ? dot(unit(rh), unit(sh)) * 0.5 + 0.5 : 0.5;
  // Fresnel's share, and at the least a sheen of sky far off.
  const f = s.strength * Math.max(fresnel(vn), rangeSheen(distance));
  // The glint: sharp close to, spread and dimmer far off, where many ripples catch the sun at once.
  const sharp = glintSharpness(distance);
  const glint = Math.max(0, dot(r, sun)) ** sharp * GLINT_STRENGTH * Math.sqrt(sharp / glintSharpness(0)) * s.strength;
  const color = [0, 1, 2].map((k) => {
    const horizon = s.sky.awaySun[k]! + (s.sky.towardSun[k]! - s.sky.awaySun[k]!) * toward;
    const sky = horizon + (s.sky.zenith[k]! - horizon) * Math.sqrt(e);
    return base[k]! + (sky - base[k]!) * f + s.sky.glint[k]! * glint;
  }) as Vec3;
  // As deep as it is measured, or a few metres along the eye's slant: the deeper, the less of the bed shows.
  const thickness = s.thickness ?? ASSUMED_DEPTH_M / Math.max(vn, 0.1);
  const deep = waterOpacity(thickness, s.clarity ?? WATER_MOTION_DEFAULTS.clarity);
  return { color, alpha: Math.max(alpha + (1 - alpha) * f, deep, Math.min(1, glint * Math.max(...s.sky.glint))) };
}

/**
 * The sky the water reflects, for an eye at `eye` (metres from the planet's
 * centre, in its frame) with the sun along the unit `sun`: the air's colour
 * overhead and at the horizon toward and away from the sun, and the sun's
 * light through it, as they are over the water under the eye (at altitude 0,
 * or the eye's own altitude where that is lower). The sky over the eye would
 * be space's from over the air: the sea would mirror black.
 */
export function waterSkyOf(a: Atmosphere, eye: Vec3, sun: Vec3): WaterSky {
  const up = unit(eye);
  const level = Math.min(Math.hypot(...eye), a.radius);
  const at: Vec3 = [up[0] * level, up[1] * level, up[2] * level];
  const along = dot(sun, up);
  let h: Vec3 = [sun[0] - up[0] * along, sun[1] - up[1] * along, sun[2] - up[2] * along];
  if (Math.hypot(...h) < 1e-6) h = Math.abs(up[0]) < 0.9 ? [1, 0, 0] : [0, 0, 1];
  h = unit([h[0] - up[0] * dot(h, up), h[1] - up[1] * dot(h, up), h[2] - up[2] * dot(h, up)]);
  const toward = unit([h[0] + up[0] * HORIZON_RISE, h[1] + up[1] * HORIZON_RISE, h[2] + up[2] * HORIZON_RISE]);
  const away = unit([-h[0] + up[0] * HORIZON_RISE, -h[1] + up[1] * HORIZON_RISE, -h[2] + up[2] * HORIZON_RISE]);
  return {
    zenith: skyColour(a, at, up, sun, 8, 2),
    towardSun: skyColour(a, at, toward, sun, 8, 2),
    awaySun: skyColour(a, at, away, sun, 8, 2),
    glint: sunlight(a, at, sun),
  };
}

/** The shell's look under a planet's water: as thick as the water profile's fog, in the blue-green of shallow water lit from overhead. */
export const UNDERWATER_DEFAULTS: { density: number; colour: Vec3 } = { density: 0.08, colour: [0.12, 0.36, 0.42] };
/** How much of each of red, green and blue the water takes from the light a metre down: the red goes first, so deeper water is blue-green. */
const UNDERWATER_ABSORB: Vec3 = [0.4, 0.06, 0.07];

/**
 * The look about an eye `depth` metres under the water: the world's water
 * colour, lit by `light` (the day's light reaching the water, by channel),
 * its red, then its green and blue, taken by the water over the eye; and as
 * thick as `density` asks.
 */
export function underwaterLook(depth: number, o: { colour: Vec3; density: number; light: Vec3 }): { colour: Vec3; density: number } {
  const d = Math.max(0, depth);
  return { colour: [0, 1, 2].map((k) => o.colour[k]! * o.light[k]! * Math.exp(-UNDERWATER_ABSORB[k]! * d)) as Vec3, density: o.density };
}

/** What the planet view hands the reflections each frame. */
export interface WaterFrame {
  eye: Vec3;
  centre: Vec3;
  /** The eye and the sun in the planet's frame, for the air's sums. */
  eyeOnPlanet: Vec3;
  sunOnPlanet: Vec3;
  /** Toward the sun, in the scene. */
  sunInScene: Vec3;
  /** The planet's air, or undefined for none: then the sky is the world's background colour. */
  air: Atmosphere | undefined;
  background: Vec3;
  deltaMs: number;
  /** The tide's clock, in seconds since the epoch, where the tide is the planet's; absent, it keeps the view's own, from when it opened. */
  tideS?: number;
  /** How the water moves, as the world asks. */
  motion: WaterMotion;
  /** The frame the waves are laid out in, in the planet's frame and in the scene. */
  waves: WaveFrame;
  wavesInScene: { origin: Vec3; east: Vec3; north: Vec3 };
  /** The look under the water: its colour about the eye, and the surface's distance from the centre while the eye is under it (else 0). */
  under?: { colour: Vec3; overEye: number; eyeUnder: number; fogDensity: number };
}

/** The planet view's water: its reflections and its motion, as the chunk draws them and as a swimmer floats on them. */
export interface WaterController {
  frame(f: WaterFrame): void;
  /** How far the surface stands over its drawn level at the planet point `p`, for an eye `distance` metres off; 0 until the water is drawn moving. */
  raiseAt(p: Vec3, distance: number): number;
  dispose(): void;
}

/**
 * The planet view's water: the chunk fetched the first time the world asks
 * for its reflections, its waves or its tide, then fed each frame (mirroring
 * nothing while the world, or the visitor's tier, has reflections off), and
 * let go with `dispose`.
 */
export function createWaterReflections(o: {
  scene: Scene;
  load: () => Promise<WaterReflectModule>;
  ask: () => WaterReflectAsk;
  engineKind?: string;
  track: <T>(p: Promise<T>) => Promise<T>;
  warn: (name: string, detail: string) => void;
  /** The visitor's tier: whether the water mirrors anything, whether it measures its depth, and whether foam and caustics are drawn where it does. */
  reflect?: boolean;
  depth?: boolean;
  foam?: boolean;
  caustics?: boolean;
  /** The visitor's tier: the share of full detail the water's mirror of what stands over it is traced at, 0 for none. */
  mirror?: number;
  /** The picture drawn the frame before, where another pass keeps one (the temporal anti-aliasing's). */
  previousFrame?: () => DrawnPicture | null;
}): WaterController {
  let handle: WaterReflectHandle | undefined;
  let asked = false;
  let gone = false;
  let timeS = 0;
  // The waves' clock, which runs at the world's wave speed; the tide keeps `timeS` where the planet gives it no clock of its own.
  let waveS = 0;
  let last: { motion: WaterMotion; waves: WaveFrame; tideS: number } | undefined;
  const reflect = o.reflect !== false;
  return {
    raiseAt(p, distance) {
      if (!handle || !last) return 0;
      const clock = waveS % WAVE_CLOCK_S;
      return waterRaise(p, last.motion, clock, distance, last.waves, tideHeight(last.motion, last.tideS));
    },
    frame(f) {
      timeS += f.deltaMs / 1000;
      waveS += (f.deltaMs / 1000) * Math.max(0, f.motion.waveSpeed);
      const ask = o.ask();
      last = { motion: f.motion, waves: f.waves, tideS: f.tideS ?? timeS };
      if (!handle) {
        if (asked || (!ask.on && f.motion.waves <= 0 && f.motion.tide <= 0)) return;
        asked = true;
        void o.track(
          (async () => {
            try {
              const m = await o.load();
              const h = m.createWaterReflectionsOn(o.scene, { ...(o.engineKind ? { engineKind: o.engineKind } : {}), groundCaustics: o.caustics === true, ...(o.previousFrame ? { previousFrame: o.previousFrame } : {}) });
              if (gone) h.dispose();
              else handle = h;
            } catch (err) {
              o.warn('veml:planet:water-reflections-unavailable', String(err));
            }
          })(),
        );
        return;
      }
      const sky: WaterSky = f.air
        ? waterSkyOf(f.air, f.eyeOnPlanet, f.sunOnPlanet)
        : { zenith: f.background, towardSun: f.background, awaySun: f.background, glint: dot(f.sunOnPlanet, unit(f.eyeOnPlanet)) > 0 ? [1, 1, 1] : [0, 0, 0] };
      // What stands over the water, mirrored where the sky is, so as the world's reflections are turned down, so is it.
      const mirror = mirrorOf({ ask: reflect && ask.on ? (ask.mirror ?? 1) : 0, detail: o.mirror ?? 0, depth: o.depth === true });
      handle.update({
        eye: f.eye,
        centre: f.centre,
        sun: f.sunInScene,
        sky,
        strength: reflect && ask.on ? ask.strength : 0,
        ripple: reflect ? ask.ripple : 0,
        timeS: waveS % WAVE_CLOCK_S,
        motion: f.motion,
        waveOrigin: f.wavesInScene.origin,
        waveEast: f.wavesInScene.east,
        waveNorth: f.wavesInScene.north,
        tideNow: tideHeight(f.motion, last.tideS),
        depth: o.depth === true,
        foam: o.foam === true ? Math.max(0, ask.foam ?? SHORE_DEFAULTS.foam) : 0,
        foamWidth: Math.max(0.01, ask.foamWidth ?? SHORE_DEFAULTS.foamWidth),
        caustics: o.caustics === true ? Math.max(0, ask.caustics ?? SHORE_DEFAULTS.caustics) : 0,
        under: f.under?.colour ?? UNDERWATER_DEFAULTS.colour,
        overEye: f.under?.overEye ?? 0,
        eyeUnder: f.under?.eyeUnder ?? 0,
        fogDensity: f.under?.fogDensity ?? 0,
        mirror: mirror.strength,
        mirrorDetail: mirror.detail,
      });
    },
    dispose() {
      gone = true;
      handle?.dispose();
      handle = undefined;
    },
  };
}
