/**
 * A planet's night sky: stars made from a seed, as many as the world asks.
 * Two layers of them, a coarse one of the brighter stars and a fine one of
 * many faint ones; each star sits somewhere in its cell of the sky, a soft
 * point whose light falls off from its middle, its brightness drawn so that
 * most are faint and a few bright, and its colour from blue-white to orange.
 * The sky they hang in is fixed while the planet turns under it, so they
 * wheel across the night as the sun does across the day.
 *
 * This is the reference the sky's shader (atmosphereChunk.ts) follows, with
 * the same hash and numbers.
 */
import type { Vec3 } from './planetFrame';

/** The shell's defaults: a rich sky, from seed 1. */
export const STAR_DEFAULTS = { density: 0.7, seed: 1 };

/** The layers: cells across a radian of sky, the share of cells with a star at full density, how bright. */
const LAYERS: [number, number, number][] = [
  [220, 0.35, 1],
  [700, 0.5, 0.35],
];
/** A star's light falls by e this far from its middle, in its cell's width. */
const STAR_RADIUS = 0.22;

/** The numbers the shader carries as the reference does, written as it writes them. */
export const STAR_CONSTANTS = ['0.1031', '0.103', '0.0973', '33.33', '220.0', '700.0', '0.22'] as const;

const fract = (x: number) => x - Math.floor(x);

/** Three hashes of a lattice point, 0 to 1, without `sin`. */
function hash3(x: number, y: number, z: number): Vec3 {
  let a = fract(x * 0.1031), b = fract(y * 0.103), c = fract(z * 0.0973);
  const d = a * (b + 33.33) + b * (a + 33.33) + c * (c + 33.33);
  a += d; b += d; c += d;
  return [fract((a + a) * c), fract((a + b) * b), fract((b + a) * a)];
}

/**
 * The light of the stars toward the unit direction `dir` (in the stars' own
 * sky), red, green and blue, with `density` from 0 (none) to 1 and the
 * world's `seed`.
 */
export function starLight(dir: Vec3, density: number, seed: number): Vec3 {
  const out: Vec3 = [0, 0, 0];
  if (density <= 0) return out;
  for (const [scale, share, bright] of LAYERS) {
    const px = dir[0] * scale, py = dir[1] * scale, pz = dir[2] * scale;
    const cx = Math.floor(px), cy = Math.floor(py), cz = Math.floor(pz);
    const h = hash3(cx + seed * 17.0, cy - seed * 31.0, cz + seed * 7.0);
    if (h[0] >= share * density) continue;
    // Where in its cell the star sits, kept off the edges so its light is not cut.
    const at = hash3(cx - 5.0, cy + 11.0 + seed, cz + 3.0);
    const sx = cx + 0.3 + 0.4 * at[0], sy = cy + 0.3 + 0.4 * at[1], sz = cz + 0.3 + 0.4 * at[2];
    const r2 = ((px - sx) ** 2 + (py - sy) ** 2 + (pz - sz) ** 2) / (STAR_RADIUS * STAR_RADIUS);
    const fall = Math.exp(-r2);
    if (fall < 1e-3) continue;
    // Most faint, a few bright.
    const glow = bright * (0.15 + 3 * Math.pow(h[1], 8)) * fall;
    // From blue-white to orange.
    const t = h[2];
    const colour: Vec3 = t < 0.5 ? [0.8 + 0.4 * t, 0.88 + 0.24 * t, 1.12 - 0.12 * t] : [1 + 0.25 * (t - 0.5), 1 - 0.2 * (t - 0.5), 1 - 0.5 * (t - 0.5)];
    out[0] += glow * colour[0];
    out[1] += glow * colour[1];
    out[2] += glow * colour[2];
  }
  return out;
}

/** How far the stars' sky has turned, in radians about the planet's axis, at `hour` at longitude 0: none at noon. */
export function starsTurn(hour: number): number {
  const a = (((hour - 12) / 24) * 2 * Math.PI) % (2 * Math.PI);
  return a < 0 ? a + 2 * Math.PI : a;
}
