/**
 * A planet's water in motion, as the world sets it. A swell: four waves about
 * the world's bearing, the longest `waveLength` metres from crest to crest,
 * as high as `waves` asks, each moving at `waveSpeed` times the speed deep
 * water carries a wave of its length. A ripple: nine finer waves crossing at bearings a golden
 * angle apart, so the glitter they make breaks up instead of lying in lines;
 * each fades once the eye is far enough that a pixel spans it, the finest
 * first, so the ripple thins with distance and never ends at a line. A tide:
 * the water falls from the level it is drawn at (high water) to `tide` metres
 * under it and back, once in `tidePeriod` seconds, so shores dry at low tide
 * and the water never stands over the land.
 *
 * Positions are metres in the planet's frame (its centre the origin, +y the
 * north pole); a wave's bearing is degrees clockwise from north, as the
 * planet profile's headings are. The waves lie in one frame for all the
 * water about the visitor (a `WaveFrame`: east and north at a point near
 * them), so their pattern is continuous everywhere the visitor can see it; a
 * planet view moves the frame only once the visitor is far from it.
 *
 * The shore too: foam in a soft band where the water is shallow, and the
 * sun's caustics on a shallow bed (foamAt, causticPattern, causticFade).
 *
 * This is the reference the water's shader (waterReflectChunk.ts) follows,
 * on the processor, and what a swimmer floats on.
 */
import type { Vec3 } from './planetFrame';

export interface WaterMotion {
  /** How high the swell is: 0 none, 1 the shell's. */
  waves: number;
  /** Metres from crest to crest of the swell's longest wave. */
  waveLength: number;
  /** Degrees clockwise from north the swell travels toward. */
  waveBearing: number;
  /** Metres the tide falls under the drawn level at low water. */
  tide: number;
  /** Seconds from one high water to the next. */
  tidePeriod: number;
  /** Metres of water the eye sees through before its bed is a third hidden. */
  clarity: number;
  /** How fast the swell and the ripple move, as a share of the speed deep water gives a wave of their length: the waves' clock runs this fast. */
  waveSpeed: number;
  /**
   * Metres from the eye within which the swell moves the surface itself, up
   * and down. Past it the swell shows in the water's shading only and the
   * surface lies at its drawn level, so a beach drawn at the waterline is
   * never uncovered, in strips, by a trough seen at a glancing angle.
   */
  waveReach: number;
  /**
   * The share of its depth to its bed, 0 to 1, that water whose depth is
   * known falls at most with the tide and the swell (bedShare): shallow
   * water falls less, and never under its bed.
   */
  shallowFall: number;
}

/** The shell's defaults; the tide's period is the planet view's, half a day. */
export const WATER_MOTION_DEFAULTS = { waves: 1, waveLength: 14, waveBearing: 70, tide: 0.8, clarity: 3, waveSpeed: 0.6, waveReach: 40, shallowFall: 0.75 };
/** The tide's period where no motion is given at all (the water's own sums, `waterNormal`). */
export const STILL_DAY_TIDE_S = 600;

/** The swell: each wave's length as a share of the longest, bearing off the swell's, height as a share of its length, and phase. */
export const SWELL: readonly (readonly [number, number, number, number])[] = [
  [1, 0, 0.016, 0],
  [0.71, 24, 0.013, 1.7],
  [0.53, -31, 0.011, 4.1],
  [0.38, 52, 0.008, 2.6],
];
/** The ripple: each wave's length in metres, bearing in degrees, slope (height × wavenumber) and phase. */
export const RIPPLE: readonly (readonly [number, number, number, number])[] = Array.from({ length: 9 }, (_, i) => [
  Number((2.6 * 0.74 ** i).toFixed(4)),
  Number(((i * 137.508) % 360).toFixed(3)),
  Number((0.06 * 0.86 ** i).toFixed(4)),
  Number(((i * 2.39996) % 6.2832).toFixed(4)),
] as const);
/** The swell's crest, as a share of its length: its waves' heights summed, the most they can stand over the still level together. */
export const SWELL_CREST = Number(SWELL.reduce((s, [share, , height]) => s + share * height, 0).toFixed(5));
/** Gravity, metres per second squared: a deep-water wave of wavenumber k moves at sqrt(g k) radians a second. */
const G = 9.81;
/** The share of a metre a pixel spans at a metre's distance, about; a wave fades as a pixel grows to span it. */
const PIXEL_PER_M = 0.0025;
/** Where, as a share of the wave reach, the swell's lift begins to fade. */
const SWELL_LIFT_FROM = 0.4;
/** Where the tide shows: all of it within the first distance, none past the second, where the water is drawn coarse over beds drawn coarse too. */
const TIDE_SEEN_FROM_M = 300;
const TIDE_SEEN_TO_M = 1000;
/** How sharp the sun's glint is close to, and over how many metres it spreads. */
const GLINT_SHARPNESS = 900;
const GLINT_SPREAD_M = 250;
/** The sky's sheen on far water, at most, and where it begins and is whole. */
const SHEEN = 0.15;
const SHEEN_FROM_M = 300;
const SHEEN_TO_M = 3000;
/** Seconds the waves' clock runs before it starts again: the shader's sums keep their precision. */
export const WAVE_CLOCK_S = 4096;

/** The numbers the shader must carry as the reference does, written as it writes them. */
export const WATER_MOTION_CONSTANTS = ['9.81', '0.0025', '0.4', '900.0', '250.0', '0.15', '300.0', '3000.0', '1000.0'] as const;

const smoothstep = (e0: number, e1: number, x: number) => {
  const t = Math.min(1, Math.max(0, (x - e0) / (e1 - e0)));
  return t * t * (3 - 2 * t);
};

/** East and north at a point near the visitor, from which the waves are laid out. */
export interface WaveFrame {
  origin: Vec3;
  east: Vec3;
  north: Vec3;
}

/** Up, east and north at the planet point `p`. */
export function surfaceFrame(p: Vec3): { up: Vec3; east: Vec3; north: Vec3 } {
  const l = Math.hypot(p[0], p[1], p[2]) || 1;
  const up: Vec3 = [p[0] / l, p[1] / l, p[2] / l];
  let east: Vec3 = [-up[2], 0, up[0]];
  const el = Math.hypot(east[0], east[2]);
  east = el > 1e-9 ? [east[0] / el, 0, east[2] / el] : [1, 0, 0];
  const north: Vec3 = [east[1] * up[2] - east[2] * up[1], east[2] * up[0] - east[0] * up[2], east[0] * up[1] - east[1] * up[0]];
  return { up, east, north };
}

const bearingDir = (f: { east: Vec3; north: Vec3 }, deg: number): Vec3 => {
  const b = (deg * Math.PI) / 180;
  const c = Math.cos(b), s = Math.sin(b);
  return [f.north[0] * c + f.east[0] * s, f.north[1] * c + f.east[1] * s, f.north[2] * c + f.east[2] * s];
};

/** How much of a wave `length` metres long is left seen from `distance` metres: all near, less as a pixel grows to span it. */
export function waveSeen(length: number, distance: number): number {
  const r = (distance * PIXEL_PER_M) / length;
  return 1 / (1 + r * r);
}

/** The frame the waves are laid out in, at the planet point `p`. */
export function waveFrameAt(p: Vec3): WaveFrame {
  const s = surfaceFrame(p);
  return { origin: p, east: s.east, north: s.north };
}

const along = (p: Vec3, f: WaveFrame, d: Vec3) => (p[0] - f.origin[0]) * d[0] + (p[1] - f.origin[1]) * d[1] + (p[2] - f.origin[2]) * d[2];

/** The swell's height at the planet point `p`, metres over the still level, at `timeS` seconds. */
export function swellHeight(p: Vec3, m: WaterMotion, timeS: number, f: WaveFrame): number {
  if (m.waves <= 0) return 0;
  let h = 0;
  for (const [share, bearing, height, phase] of SWELL) {
    const length = m.waveLength * share;
    const k = (2 * Math.PI) / length;
    const d = bearingDir(f, m.waveBearing + bearing);
    h += height * length * Math.sin(k * along(p, f, d) - Math.sqrt(G * k) * timeS + phase);
  }
  return h * m.waves;
}

/** How high the swell's crest can stand over the still level, metres. */
export function swellCrest(m: WaterMotion): number {
  return m.waves <= 0 ? 0 : SWELL_CREST * m.waveLength * m.waves;
}

/** The swell's slope at `p` (a vector along the surface, uphill), as the eye sees it from `distance` metres. */
export function swellSlope(p: Vec3, m: WaterMotion, timeS: number, distance: number, f: WaveFrame): Vec3 {
  const out: Vec3 = [0, 0, 0];
  if (m.waves <= 0) return out;
  for (const [share, bearing, height, phase] of SWELL) {
    const length = m.waveLength * share;
    const k = (2 * Math.PI) / length;
    const d = bearingDir(f, m.waveBearing + bearing);
    const g = height * length * k * Math.cos(k * along(p, f, d) - Math.sqrt(G * k) * timeS + phase) * m.waves * waveSeen(length, distance);
    out[0] += d[0] * g;
    out[1] += d[1] * g;
    out[2] += d[2] * g;
  }
  return out;
}

/** The ripple's slope at `p`, as the eye sees it from `distance` metres, as strong as `ripple` asks (1 the shell's). */
export function rippleSlope(p: Vec3, m: WaterMotion, timeS: number, distance: number, f: WaveFrame, ripple = 1): Vec3 {
  const out: Vec3 = [0, 0, 0];
  if (ripple <= 0) return out;
  for (const [length, bearing, slope, phase] of RIPPLE) {
    const k = (2 * Math.PI) / length;
    const d = bearingDir(f, m.waveBearing + bearing);
    const g = slope * ripple * Math.cos(k * along(p, f, d) - Math.sqrt(G * k) * timeS + phase) * waveSeen(length, distance);
    out[0] += d[0] * g;
    out[1] += d[1] * g;
    out[2] += d[2] * g;
  }
  return out;
}

/**
 * The tide's height at `timeS` seconds: 0 at high water (the drawn level, at
 * each whole period), −`tide` at low water. The phase is taken within its
 * period first, so a clock counted from the epoch keeps its precision.
 */
export function tideHeight(m: WaterMotion, timeS: number): number {
  if (m.tide <= 0 || m.tidePeriod <= 0) return 0;
  const phase = (timeS / m.tidePeriod) % 1;
  return (m.tide * (Math.cos(2 * Math.PI * phase) - 1)) / 2;
}

/**
 * How much of the swell's rise and fall is left with the tide at `tide`
 * metres (0 or less): all of it at high water, less as the water falls, so
 * the two together sink it no further than the deeper of them alone would.
 * Added up whole, a trough at low tide sinks the water under the bed of a
 * lake a block deep, baring it in patches that move with the waves.
 */
export function swellShare(m: WaterMotion, tide: number): number {
  const trough = 2 * swellCrest(m);
  if (trough <= 0) return 1;
  return Math.min(1, Math.max(0, (Math.max(m.tide, trough) + tide) / trough));
}

/**
 * How far the water's surface stands over its drawn level at `p`, for an
 * eye `distance` metres off: the tide and the swell, close to. Far water lies
 * at the level it is drawn at: drawn coarse, over beds drawn coarse, a lower
 * tide there would sink it under its own bed. The swell runs on `timeS`, the
 * tide stands at `tideNow` (its height at `timeS` unless the tide keeps
 * another clock). Where the water's depth to its bed is known (`bed`,
 * metres), it falls at most the world's share of it (bedShare).
 */
export function waterRaise(p: Vec3, m: WaterMotion, timeS: number, distance: number, f: WaveFrame, tideNow = tideHeight(m, timeS), bed?: number): number {
  const reach = Math.max(m.waveReach, 1e-3);
  const lift = 1 - smoothstep(SWELL_LIFT_FROM * reach, reach, distance);
  const tide = tideNow * (1 - smoothstep(TIDE_SEEN_FROM_M, TIDE_SEEN_TO_M, distance));
  const raise = tide + (lift > 0 ? (swellHeight(p, m, timeS, f) - swellCrest(m)) * swellShare(m, tide) * lift : 0);
  return bed === undefined ? raise : raise * bedShare(m, bed);
}

/**
 * How much of its fall water `bed` metres deep keeps: all of it where it is
 * deep enough for the deepest fall (the deeper of the tide's and the swell's,
 * as swellShare keeps them) to stay within the world's `shallowFall` share of
 * its depth, less where it is shallower, none over a dry bed. Shallow water
 * so never sinks under its bed, and a bank stays dry; its waves keep their
 * shape, only lower.
 */
export function bedShare(m: WaterMotion, bed: number): number {
  const most = Math.max(m.tide, 2 * swellCrest(m));
  return most > 0 ? Math.min(1, Math.max(0, (m.shallowFall * bed) / most)) : 1;
}

/** How much of what lies under `thickness` metres of water the water hides, for a clarity of `clarity` metres. */
export function waterOpacity(thickness: number, clarity: number): number {
  if (thickness <= 0) return 0;
  return 1 - Math.exp(-thickness / Math.max(clarity, 1e-3));
}

// ---- The shore: foam where the water is shallow, and the sun's caustics on a shallow bed. ----

/**
 * The shell's shore: foam as white as `foam` asks (0 none, 1 the shell's)
 * over a band of water `foamWidth` metres deep at the waterline, and the
 * sun's caustics on the bed as bright as `caustics` asks (0 none, 1 the
 * shell's).
 */
export const SHORE_DEFAULTS = { foam: 1, foamWidth: 0.35, caustics: 1 };
/** How far from the waterline's depth to the band's, as a share of the band, the noise's edge is spread: no line where the foam ends. */
const FOAM_SOFT = 0.45;
/** How much the band widens as a crest comes in, and narrows in a trough, as a share of its width. */
const FOAM_SWELL_BREATH = 0.4;
/** Where the foam begins to fade from the eye, and where it is gone: short of where the water's depth stops being measured. */
const FOAM_FROM_M = 120;
const FOAM_TO_M = 240;
/** Metres across one of the caustics' cells. */
export const CAUSTIC_CELL_M = 0.8;
/** How sharp the caustics' lines are: the larger, the thinner. */
const CAUSTIC_SHARPNESS = 14;
/** Metres of water over the bed by which its caustics have come in whole, and the depth over which they fade by e. */
const CAUSTIC_SHALLOW_M = 0.2;
const CAUSTIC_DEPTH_M = 6;
/** Where, from the eye, the caustics begin to fade, and where they are gone: they are drawn near the visitor only. */
const CAUSTIC_FROM_M = 25;
const CAUSTIC_TO_M = 60;
/** The cosine, from the surface's normal, of the edge of the window through which water shows the sky to an eye under it (Snell's, for water's 1.333). */
export const SNELL_WINDOW_COS = 0.6614;

/** The shore's numbers, for the shader to write out. */
export const SHORE = {
  foamSoft: FOAM_SOFT,
  foamSwellBreath: FOAM_SWELL_BREATH,
  foamFromM: FOAM_FROM_M,
  foamToM: FOAM_TO_M,
  causticCellM: CAUSTIC_CELL_M,
  causticSharpness: CAUSTIC_SHARPNESS,
  causticShallowM: CAUSTIC_SHALLOW_M,
  causticDepthM: CAUSTIC_DEPTH_M,
  causticFromM: CAUSTIC_FROM_M,
  causticToM: CAUSTIC_TO_M,
  windowCos: SNELL_WINDOW_COS,
} as const;

/** The numbers the shader must carry as the reference does, written as it writes them. */
export const SHORE_CONSTANTS = ['0.45', '0.4', '120.0', '240.0', '0.8', '14.0', '0.2', '6.0', '25.0', '60.0', '0.6614'] as const;

const fract = (x: number) => x - Math.floor(x);
/** A cell's random number, 0 to 1, as the shader makes it. */
const cellHash = (x: number, y: number) => fract(Math.sin(x * 127.1 + y * 311.7) * 43758.5453);
const cellHash2 = (x: number, y: number): [number, number] => [cellHash(x, y), fract(Math.sin(x * 269.5 + y * 183.3) * 43758.5453)];

/** Smooth noise, 0 to 1, over a lattice a unit apart. */
function valueNoise(x: number, y: number): number {
  const ix = Math.floor(x), iy = Math.floor(y);
  const fx = x - ix, fy = y - iy;
  const ux = fx * fx * (3 - 2 * fx), uy = fy * fy * (3 - 2 * fy);
  const a = cellHash(ix, iy), b = cellHash(ix + 1, iy), c = cellHash(ix, iy + 1), d = cellHash(ix + 1, iy + 1);
  return a + (b - a) * ux + (c + (d - c) * ux - (a + (b - a) * ux)) * uy;
}

/** The foam's breakup at the point `x` metres east and `y` north in the waves' frame, 0 to 1, drifting with the waves' clock. */
export function foamNoise(x: number, y: number, timeS: number): number {
  return 0.65 * valueNoise(x * 2.3 + timeS * 0.15, y * 2.3) + 0.35 * valueNoise(x * 5.9 - timeS * 0.23, y * 5.9 + timeS * 0.11);
}

/**
 * How much foam lies on water `depth` metres deep over its bed, 0 to 1. The
 * band is `width` metres deep, widening as a crest comes in (`swell` 1) and
 * narrowing in a trough (−1); in it the foam shows where the breakup `noise`
 * stands over how far out the point is, so it lies whole along the waterline
 * and breaks into patches toward the band's edge, with no line where it ends.
 * It fades out far from the eye.
 */
export function foamAt(depth: number, o: { foam: number; width: number; swell: number; noise: number; distance: number }): number {
  if (o.foam <= 0 || depth < 0) return 0;
  const w = Math.max(1e-3, o.width * (1 + FOAM_SWELL_BREATH * o.swell));
  const t = Math.min(1, depth / w);
  return Math.min(1, o.foam * smoothstep(t, t + FOAM_SOFT, o.noise)) * (1 - smoothstep(FOAM_FROM_M, FOAM_TO_M, o.distance));
}

/** One web of the caustics at the point (`qx`, `qy`), in cells: the edges between moving cells, warped so they do not lie straight. */
function causticWeb(qx: number, qy: number, timeS: number): number {
  const px = qx + 0.25 * Math.sin(qy * 1.7 + timeS * 0.8);
  const py = qy + 0.25 * Math.sin(qx * 1.9 - timeS * 0.6);
  const cx = Math.floor(px), cy = Math.floor(py);
  const fx = px - cx, fy = py - cy;
  let d1 = 8, d2 = 8;
  for (let j = -1; j <= 1; j++)
    for (let i = -1; i <= 1; i++) {
      const [hx, hy] = cellHash2(cx + i, cy + j);
      const ox = i + 0.5 + 0.4 * Math.sin(timeS * (0.6 + 0.5 * hx) + 6.2831 * hx);
      const oy = j + 0.5 + 0.4 * Math.sin(timeS * (0.6 + 0.5 * hy) + 6.2831 * hy);
      const d = Math.hypot(ox - fx, oy - fy);
      if (d < d1) {
        d2 = d1;
        d1 = d;
      } else if (d < d2) d2 = d;
    }
  return Math.exp(-(d2 - d1) * CAUSTIC_SHARPNESS);
}

/**
 * The sun's caustics at the point `x` metres east and `y` north on a bed, 0
 * to 1: the bright lines where the light the ripples bend gathers, two webs
 * of different sizes moving at different speeds laid over each other, so the
 * lines cross and part as they do under real ripples.
 */
export function causticPattern(x: number, y: number, timeS: number): number {
  const qx = x / CAUSTIC_CELL_M, qy = y / CAUSTIC_CELL_M;
  return Math.min(1, 0.7 * (causticWeb(qx, qy, timeS) + causticWeb(qx * 1.6 + 3.1, qy * 1.6 + 7.7, timeS * 1.3)));
}

/** How much of the caustics shows on a bed `depth` metres under the water, seen from `distance` metres: none out of the water, fading as it deepens and far from the eye. */
export function causticFade(depth: number, distance: number): number {
  if (depth <= 0) return 0;
  return smoothstep(0, CAUSTIC_SHALLOW_M, depth) * Math.exp(-depth / CAUSTIC_DEPTH_M) * (1 - smoothstep(CAUSTIC_FROM_M, CAUSTIC_TO_M, distance));
}

/** How bright the caustics are on such a bed, with `sunUp` the cosine of the sun from straight up and `strength` the world's: none once the sun has set. */
export function causticLight(depth: number, distance: number, sunUp: number, strength: number): number {
  return strength * Math.max(0, sunUp) * causticFade(depth, distance);
}

/** How sharp the sun's glint is seen from `distance` metres: a point close to, spreading as the far water's ripples blur into it. */
export function glintSharpness(distance: number): number {
  return GLINT_SHARPNESS / (1 + distance / GLINT_SPREAD_M);
}

/** How much of the sky far water mirrors at the least, seen from `distance` metres: none close to, a sheen far off. */
export function rangeSheen(distance: number): number {
  return SHEEN * smoothstep(SHEEN_FROM_M, SHEEN_TO_M, distance);
}
