/**
 * How the things that move on a planet are drawn (client hints `planet.things`,
 * `planet.things-color`, `planet.things-glide`): whether at all, their colour
 * where drawn as their boxes, and whether they glide between the places they
 * are told at. The visitor's own choice of whether they are drawn wins over
 * the world's.
 */
import { parseColor } from '@fivesqd/veml-parse';

export interface ThingsLook {
  shown: boolean;
  /** Red, green and blue, 0–1, as the world writes them; null for the shell's own. */
  colour: [number, number, number] | null;
  glide: boolean;
}

/** The visitor's choice: `auto` follows the world. */
export type ThingsChoice = 'auto' | 'shown' | 'hidden';

export function thingsLookOf(hint: (name: string) => string | null | undefined, visitor: string = 'auto'): ThingsLook {
  const asked = hint('planet.things-color');
  const c = asked && asked !== 'auto' ? parseColor(asked).color : undefined;
  return {
    shown: visitor === 'shown' ? true : visitor === 'hidden' ? false : hint('planet.things') !== 'none',
    colour: c && c.form !== 'neutral' ? [c.r, c.g, c.b] : null,
    glide: hint('planet.things-glide') !== 'none',
  };
}
