/**
 * Letting go of a chunk's or a tile's meshes that new ones replace: hidden
 * at once, disposed a few rendered frames later. On WebGPU a frame already
 * in flight can still bind a material disposed under it, which fails
 * ("Texture … not found in the material context") and can stop the view
 * drawing; waiting out those frames avoids it.
 */
import type { AssetContainer } from '@babylonjs/core/assetContainer';
import type { AbstractMesh } from '@babylonjs/core/Meshes/abstractMesh';
import type { Scene } from '@babylonjs/core/scene';

/** Frames a replaced container stays (hidden) before it is disposed. */
export const RETIRE_FRAMES = 3;
/** Rendered frames a replaced container is kept drawn under its successor at most, waiting for the successor to draw. */
export const HANDOVER_FRAMES = 90;

/**
 * A container replaced by meshes drawn in its place stays drawn until they are ready to draw in every pass (their
 * pipelines built), so no frame goes without it; then it is retired as below. Until then the two draw the same faces
 * in the same places, which looks like one. Ready on two frames running: a mesh left out of a frame while its pipeline
 * is built is drawn the frame after.
 */
export function retireWhenDrawn(scene: Scene, container: AssetContainer, successor: readonly AbstractMesh[], ready: (m: AbstractMesh) => boolean, frames = RETIRE_FRAMES): void {
  let seen = 0;
  let readyFrames = 0;
  const observer = scene.onAfterRenderObservable.add(() => {
    seen++;
    if (successor.every((m) => m.isDisposed() || ready(m))) readyFrames++;
    else readyFrames = 0;
    if (readyFrames < 2 && seen < HANDOVER_FRAMES) return;
    scene.onAfterRenderObservable.remove(observer);
    retireAfterFrames(scene, container, frames);
  });
}

export function retireAfterFrames(scene: Scene, container: AssetContainer, frames = RETIRE_FRAMES): void {
  for (const m of container.meshes) m.setEnabled(false);
  let seen = 0;
  const observer = scene.onAfterRenderObservable.add(() => {
    if (++seen < frames) return;
    scene.onAfterRenderObservable.remove(observer);
    container.dispose();
  });
}
