/**
 * A reader for the part of OGC 3D Tiles 1.1 the planet profile allows
 * (specs/veml/profiles/planet.md, Terrain): JSON tilesets and external
 * tilesets, glTF content, `box` and `sphere` bounding volumes, `REPLACE`
 * refinement, and tiles chosen by how large their geometric error would look
 * on screen. It holds no engine: it says which contents to show and which to
 * fetch, and the caller loads and draws them.
 *
 * Refinement: a tile whose error would look larger than the limit, and that
 * has children, is replaced by its children only once every child it
 * refines to is ready. Until then the tile itself stays drawn, so the ground
 * never has a hole while finer tiles arrive.
 *
 * Each tile has a key, its place in the tree (the path of child indices
 * from the root), so two trees of one shape, a host's terrain in two
 * styles, name the same tile alike. A caller changing from one tree to
 * another lets the tiles the old tree drew stand in for the new tree's that
 * are not ready yet: the old tile at a tile's own place, or the old tiles
 * under it, which cover it whole, since what a tree draws covers each place
 * once. So the ground the old tree drew is never replaced by coarser new
 * ground, only by the new ground at its own level or finer.
 */

export type Vec3 = [number, number, number];

export interface TileCamera {
  /** In the tileset's frame (right-handed, z up), metres. */
  position: Vec3;
  /** The view's height in pixels, and its vertical field of view in radians. */
  screenHeight: number;
  fovY: number;
  /**
   * Where the view looks (a unit vector in the tileset's frame) and its width over its height. With them, what lies
   * outside the view is drawn coarser (OUT_OF_VIEW_ERROR) and fetched after what is in it; without, every way alike.
   */
  forward?: Vec3;
  aspect?: number;
}

/**
 * How many times the screen error a tile outside the view may have: it is fetched coarser, so far fewer tiles arrive
 * for the ground behind the eye, which is there still, and refined once the eye turns to it.
 */
export const OUT_OF_VIEW_ERROR = 8;

/**
 * Which `count` of the tiles not drawn to let go of: the finest first, then those shown longest ago. The coarse ones
 * are few, and every view near them needs them again (an eye rising, turning, coming back); let go first, as the
 * tiles finer ones replaced earliest, they were fetched again.
 */
export function tilesToLetGo(idle: readonly { url: string; depth: number; lastShown: number }[], count: number): string[] {
  if (count <= 0) return [];
  return [...idle].sort((a, b) => b.depth - a.depth || a.lastShown - b.lastShown).slice(0, count).map((t) => t.url);
}

export interface TileSelection {
  /** Content URLs to draw now: this tree's, and any standing in for them. */
  show: string[];
  /** Whether `show` covers the tree: false until its tileset has arrived, and while nothing covers some part of it. */
  ready: boolean;
  /** Content URLs that are wanted and not ready: those in view first, then coarser levels first, nearest the camera first within a level. */
  request: string[];
  /** Content URLs that are ready and wanted, but not drawn until the tiles beside them are: never let go meanwhile. */
  waiting: string[];
  /** How many of `request` are wanted where the eye looks: the terrain it is still waiting for. */
  wantedInView: number;
}

export interface TileTree {
  /**
   * The tiles to draw and to fetch. `stand` gives ready contents that
   * together cover a tile, by its key, and stand in for it while its own
   * is not ready or its tileset not yet read.
   */
  /**
   * `occluder`, when given, is the radius of a sphere at the tileset's origin
   * that nothing of the tiles lies under, such as a planet's lowest ground: a
   * tile wholly hidden behind it from the camera is not refined.
   */
  select(camera: TileCamera, opts: { maxScreenError: number; ready: (url: string) => boolean; stand?: (key: string) => string[] | undefined; occluder?: number }): TileSelection;
  /** A content's key: its tile's place in the tree; undefined for a content the tree has not read. */
  keyOf(url: string): string | undefined;
  /** Resolves when no tileset fetch is pending. */
  idle(): Promise<void>;
  /** The profile's warnings this tree has raised, each once. */
  warnings(): string[];
}

interface Volume {
  box?: number[];
  sphere?: number[];
}

interface Tile {
  /** Its place in the tree: the child indices from the root, joined. */
  key: string;
  volume: Volume;
  error: number;
  content?: string;
  children: Tile[];
  /** An external tileset this tile stands for, not yet read into it. */
  /** A fetch that failed is asked for again from `retryAt` (ms), its wait doubling with each failure in a row. */
  external?: { url: string; path: string[]; state: 'none' | 'loading' | 'loaded' | 'failed'; failures?: number; retryAt?: number };
}

/** The wait before a failed external tileset is asked for again, doubling with each failure in a row up to the most. */
const EXTERNAL_RETRY_MS = 1_000;
const EXTERNAL_RETRY_MAX_MS = 30_000;

interface TilesetJson {
  root?: TileJson;
}
interface TileJson {
  boundingVolume?: { box?: number[]; sphere?: number[]; region?: number[] };
  geometricError?: number;
  refine?: string;
  content?: { uri?: string };
  children?: TileJson[];
}

export function createTileTree(opts: { url: string; fetchJson: (url: string) => Promise<unknown>; maxExternalDepth?: number; now?: () => number }): TileTree {
  const maxDepth = opts.maxExternalDepth ?? 32;
  const now = opts.now ?? Date.now;
  const warned = new Set<string>();
  const warn = (name: string) => warned.add(name);
  const pending = new Set<Promise<void>>();
  const keys = new Map<string, string>();

  /** A tile from its JSON, at `key` in the tree; null for one this reader skips. */
  const readTile = (j: TileJson, base: string, path: string[], key: string): Tile | null => {
    const bv = j.boundingVolume ?? {};
    if (bv.region) {
      warn('veml:planet:region-volume');
      return null;
    }
    if (!bv.box && !bv.sphere) return null;
    if (j.refine === 'ADD') warn('veml:planet:refine-add');
    const tile: Tile = { key, volume: { ...(bv.box ? { box: bv.box } : {}), ...(bv.sphere ? { sphere: bv.sphere } : {}) }, error: j.geometricError ?? 0, children: [] };
    const uri = j.content?.uri;
    if (uri) {
      const abs = new URL(uri, base).href;
      if (/\.json(\?|$)/i.test(abs)) tile.external = { url: abs, path, state: 'none' };
      else {
        tile.content = abs;
        keys.set(abs, key);
      }
    }
    (j.children ?? []).forEach((c, i) => {
      const t = readTile(c, base, path, `${key}/${i}`);
      if (t) tile.children.push(t);
    });
    return tile;
  };

  /** Read an external tileset into the tile that stands for it. */
  const loadExternal = (tile: Tile) => {
    const ext = tile.external!;
    // A fetch that failed is asked for again once its wait is over; a tileset that cannot be read never is.
    if (ext.state === 'failed' && ext.retryAt !== undefined && now() >= ext.retryAt) ext.state = 'none';
    if (ext.state !== 'none') return;
    if (ext.path.includes(ext.url)) {
      warn('veml:planet:tileset-cycle');
      ext.state = 'failed';
      return;
    }
    if (ext.path.length >= maxDepth) {
      warn('veml:planet:tileset-depth');
      ext.state = 'failed';
      return;
    }
    ext.state = 'loading';
    const p = opts
      .fetchJson(ext.url)
      .then((json) => {
        const root = (json as TilesetJson | null)?.root;
        // The external tileset's root stands at the tile's own place in the tree.
        const read = root ? readTile(root, ext.url, [...ext.path, ext.url], tile.key) : null;
        if (!read) {
          ext.state = 'failed';
          return;
        }
        // The external tileset's root takes the tile's place: its content and children.
        tile.volume = read.volume;
        tile.error = read.error;
        if (read.content !== undefined) tile.content = read.content;
        tile.children = read.children;
        if (read.external) tile.external = read.external;
        else ext.state = 'loaded';
        if (read.external) loadExternal(tile);
      })
      .catch(() => {
        ext.state = 'failed';
        ext.failures = (ext.failures ?? 0) + 1;
        ext.retryAt = now() + Math.min(EXTERNAL_RETRY_MAX_MS, EXTERNAL_RETRY_MS * 2 ** (ext.failures - 1));
      })
      .finally(() => pending.delete(p));
    pending.add(p);
  };

  // The tree starts as one external reference: the tileset itself.
  const top: Tile = { key: '', volume: { sphere: [0, 0, 0, Number.MAX_VALUE] }, error: Number.MAX_VALUE, children: [], external: { url: opts.url, path: [], state: 'none' } };
  loadExternal(top);

  /** The sphere around a volume: its centre and radius. */
  const sphereOf = (v: Volume): [number, number, number, number] => {
    if (v.sphere) return v.sphere as [number, number, number, number];
    const b = v.box!;
    let r2 = 0;
    for (let i = 0; i < 3; i++) r2 += b[3 + 3 * i]! ** 2 + b[4 + 3 * i]! ** 2 + b[5 + 3 * i]! ** 2;
    return [b[0]!, b[1]!, b[2]!, Math.sqrt(r2)];
  };
  /** Whether any of a volume may lie in a view cone from `p` along `f` of half-angle whose cosine and sine are given. */
  const inCone = (p: Vec3, f: Vec3, cosHalf: number, sinHalf: number, v: Volume): boolean => {
    const [cx, cy, cz, r] = sphereOf(v);
    const d: Vec3 = [cx - p[0], cy - p[1], cz - p[2]];
    const len = Math.hypot(d[0], d[1], d[2]);
    if (len <= r) return true;
    // The sphere meets the cone where its angle from the axis, less the angle it spans, is within the half-angle.
    const cosA = (d[0] * f[0] + d[1] * f[1] + d[2] * f[2]) / len;
    const sinA = Math.sqrt(Math.max(0, 1 - cosA * cosA));
    const sinS = r / len, cosS = Math.sqrt(Math.max(0, 1 - sinS * sinS));
    // cos(A - S) >= cos(half)
    return cosA * cosS + sinA * sinS >= cosHalf || sinHalf >= 1;
  };
  const distance = (p: Vec3, v: Volume): number => {
    if (v.sphere) {
      const [cx, cy, cz, r] = v.sphere as [number, number, number, number];
      return Math.max(0, Math.hypot(p[0] - cx, p[1] - cy, p[2] - cz) - r);
    }
    const b = v.box!;
    const d = [p[0] - b[0]!, p[1] - b[1]!, p[2] - b[2]!];
    let sum = 0;
    for (let i = 0; i < 3; i++) {
      const a = [b[3 + 3 * i]!, b[4 + 3 * i]!, b[5 + 3 * i]!];
      const len = Math.hypot(a[0]!, a[1]!, a[2]!);
      if (len === 0) continue;
      const t = (d[0]! * a[0]! + d[1]! * a[1]! + d[2]! * a[2]!) / len;
      const excess = Math.max(0, Math.abs(t) - len);
      sum += excess * excess;
    }
    return Math.sqrt(sum);
  };

  /**
   * Whether all of a box lies hidden behind a sphere of radius `r` at the
   * origin, from `p`: every corner beyond the horizon's plane and inside the
   * sphere's shadow cone. Both are convex, so a box whose corners are in both
   * is in both. A sphere volume, and any eye inside the sphere, is never hidden.
   */
  const hidden = (p: Vec3, v: Volume, r: number): boolean => {
    const b = v.box;
    if (!b) return false;
    const pp = p[0] * p[0] + p[1] * p[1] + p[2] * p[2];
    if (pp <= r * r) return false;
    const cosCone = Math.sqrt(1 - (r * r) / pp);
    const pl = Math.sqrt(pp);
    for (let n = 0; n < 8; n++) {
      const c: Vec3 = [b[0]!, b[1]!, b[2]!];
      for (let i = 0; i < 3; i++) {
        const sgn = n & (1 << i) ? 1 : -1;
        c[0] += sgn * b[3 + 3 * i]!;
        c[1] += sgn * b[4 + 3 * i]!;
        c[2] += sgn * b[5 + 3 * i]!;
      }
      if (c[0] * p[0] + c[1] * p[1] + c[2] * p[2] >= r * r) return false;
      const d: Vec3 = [c[0] - p[0], c[1] - p[1], c[2] - p[2]];
      const dl = Math.hypot(d[0], d[1], d[2]);
      if (dl === 0 || -(d[0] * p[0] + d[1] * p[1] + d[2] * p[2]) / (dl * pl) < cosCone) return false;
    }
    return true;
  };

  return {
    select(camera, { maxScreenError, ready, stand, occluder }) {
      const k = camera.screenHeight / (2 * Math.tan(camera.fovY / 2));
      // The view as a cone round its corners: half the diagonal field of view.
      const f = camera.forward;
      const half = Math.atan(Math.tan(camera.fovY / 2) * Math.hypot(1, camera.aspect ?? 1));
      const cosHalf = Math.cos(half), sinHalf = Math.sin(half);
      const seen = (v: Volume) => !f || inCone(camera.position, f, cosHalf, sinHalf, v);
      // Wanted contents in view first, then by level, then by distance from the camera: coarser levels first, so each
      // refinement completes, and the nearest first within a level.
      const request = new Map<string, [number, number, number]>();
      const waiting: string[] = [];
      /** A tile's own content when it is ready, or what stands in for it (its tileset not read yet, too); undefined when neither is. */
      const drawn = (tile: Tile): string[] | undefined => {
        const read = !(tile.external && tile.external.state !== 'loaded');
        if (read && tile.content && ready(tile.content)) return [tile.content];
        return stand?.(tile.key);
      };
      /** Ready contents among a tile's descendants that cover all of it, or nothing when any part is missing. */
      const covered = (tile: Tile): string[] | undefined => {
        if (tile.children.length === 0 || (tile.external && tile.external.state !== 'loaded')) return undefined;
        const out: string[] = [];
        for (const c of tile.children) {
          const d = drawn(c);
          if (d) {
            out.push(...d);
            continue;
          }
          const deeper = covered(c);
          if (!deeper) return undefined;
          out.push(...deeper);
        }
        return out;
      };
      // `group` is whether the tile's parent is in view: siblings are fetched as one, since a parent gives way only to
      // all of them, and one fetched long before the rest waits unshown and may be let go.
      const visit =(tile: Tile, depth: number, group = true): { show: string[]; ready: boolean } => {
        if (tile.external && tile.external.state !== 'loaded') {
          loadExternal(tile);
          // Until its tileset is read, what stands in for the tile is drawn, as for a tile whose content is not ready.
          const standing = stand?.(tile.key);
          return standing ? { show: standing, ready: true } : { show: [], ready: false };
        }
        const d = distance(camera.position, tile.volume);
        const inView = seen(tile.volume);
        const own = (): { show: string[]; ready: boolean } => {
          if (tile.content && !ready(tile.content) && !request.has(tile.content)) request.set(tile.content, [group ? 0 : 1, depth, d]);
          const shown = drawn(tile);
          return { show: shown ?? [], ready: shown !== undefined };
        };
        // The tile itself; until it is ready, finer tiles that are ready and cover all of it stand in, so nothing goes blank.
        const ownOrFiner = (): { show: string[]; ready: boolean } => {
          const o = own();
          if (o.ready) return o;
          const finer = covered(tile);
          return finer ? { show: finer, ready: true } : o;
        };
        const sse = (tile.error * k) / Math.max(d, 1e-3);
        // A tile with nothing of its own to draw (a planet's root, which holds only its faces) passes down whatever its
        // error: drawn at its own level it would draw nothing, and a small far planet would not be there at all.
        if ((sse <= maxScreenError * (inView ? 1 : OUT_OF_VIEW_ERROR) && tile.content) || tile.children.length === 0) return ownOrFiner();
        // Wholly behind the planet: nothing finer would show.
        if (occluder !== undefined && hidden(camera.position, tile.volume, occluder)) return ownOrFiner();
        const kids = tile.children.map((c) => visit(c, depth + 1, inView));
        if (kids.every((c) => c.ready)) return { show: kids.flatMap((c) => c.show), ready: true };
        for (const c of kids) if (c.ready) waiting.push(...c.show);
        return ownOrFiner();
      };
      const s = visit(top, 0);
      const order = [...request].filter(([u]) => !s.show.includes(u)).sort((a, b) => a[1][0] - b[1][0] || a[1][1] - b[1][1] || a[1][2] - b[1][2]);
      return { show: s.show, ready: s.ready, request: order.map(([u]) => u), waiting: waiting.filter((u) => !s.show.includes(u)), wantedInView: order.filter(([, k]) => k[0] === 0).length };
    },
    async idle() {
      while (pending.size > 0) await Promise.all([...pending]);
    },
    keyOf: (url) => keys.get(url),
    warnings: () => [...warned],
  };
}
