/**
 * A planet's clouds as the world asks for them (the client-hints profile's
 * `hints:planet`, specs/veml/profiles/client-hints.md), read from the hints
 * in force into the values the planet view draws with. Each cloud attribute
 * is a list of entries, one per layer, lowest first; `auto`, or a missing
 * entry, leaves that layer's value to the shell. Read each time it is
 * wanted, so a world script's `ClientHints.Set` shows at once.
 *
 * Read by the planet view, which is code-split, so none of this is in the
 * main bundle.
 */

import { parseColor } from '@fivesqd/veml-parse';

type Entry = number | 'auto';

export interface CloudHints {
  /** How many layers there are and the share of the sky each covers; `auto` leaves both to the shell, `none` asks for none. */
  cover: Entry[] | 'auto' | 'none';
  /** Metres over altitude 0. */
  altitude: Entry[];
  /** About how wide one cloud is, in metres. */
  size: Entry[];
  /** Metres per second eastward around the planet's axis; negative westward. */
  wind: Entry[];
  /** Red, green and blue, 0 to 1, in full sunlight. */
  color: ([number, number, number] | 'auto')[];
  /** How much of the sky behind its thickest cloud a layer hides, 0 to 1. */
  opacity: Entry[];
  /** How much of the sun's direct light its thickest cloud keeps from the ground, 0 to 1. */
  shadow: Entry[];
}

/** A layered value's entries, split at spaces outside parentheses. */
const entriesOf = (raw: string | null): string[] => {
  if (raw === null || raw === 'auto') return [];
  const out: string[] = [];
  let depth = 0;
  let current = '';
  for (const ch of raw) {
    if (ch === '(') depth++;
    if (ch === ')') depth = Math.max(0, depth - 1);
    if (/\s/.test(ch) && depth === 0) {
      if (current) out.push(current);
      current = '';
    } else current += ch;
  }
  if (current) out.push(current);
  return out;
};

const numbers = (raw: string | null): Entry[] =>
  entriesOf(raw).map((e) => {
    const n = Number(e);
    return e !== 'auto' && Number.isFinite(n) ? n : 'auto';
  });

/** The clouds the hints in force ask for; `get` is a client-hints reader (`ClientHints.Get`). */
export function cloudHintsOf(get: (name: string) => string | null): CloudHints {
  const clouds = get('planet.clouds');
  return {
    cover: clouds === null || clouds === 'auto' ? 'auto' : clouds === 'none' ? 'none' : numbers(clouds),
    altitude: numbers(get('planet.cloud-altitude')),
    size: numbers(get('planet.cloud-size')),
    wind: numbers(get('planet.wind')),
    color: entriesOf(get('planet.cloud-color')).map((e) => {
      if (e === 'auto') return 'auto';
      const c = parseColor(e).color;
      return c.form === 'neutral' ? 'auto' : [c.r, c.g, c.b];
    }),
    opacity: numbers(get('planet.cloud-opacity')),
    shadow: numbers(get('planet.cloud-shadow')),
  };
}
