/**
 * The world boxes of a list of meshes, kept as flat numbers, so that a line
 * cast at the list is tested against those numbers and handed only the
 * meshes whose box it crosses. Reading a box from a mesh follows several
 * objects through memory; across the thousand or so meshes a planet walks on,
 * for every line a frame casts, that was most of what the lines cost.
 *
 * A box is kept only for a mesh whose place is held (its world matrix frozen,
 * see holdPlaces): such a mesh, and its box, move only when its place is held
 * again. So when places have been held, or the list differs from the one the
 * boxes were read for (a mesh added, taken away or put in another's place),
 * the index looks again: it reads the boxes of the meshes new to it and of
 * those whose places were held since, and keeps the rest. Every other mesh
 * (one that moves freely, one whose box Babylon does not keep in step, a line,
 * a disposed mesh) is always handed on, for the caller to test as it would
 * have without the index.
 */
import type { Ray } from '@babylonjs/core/Culling/ray.core';
import type { AbstractMesh } from '@babylonjs/core/Meshes/abstractMesh';
import { BOX_SLACK_M, boxSaysNothing, rayCrossesBox } from '../../controller/groundProbe';
import { heldWhen, placesHeld } from './holdPlaces';

export interface BoxIndex {
  /** The meshes of `meshes`, in order, that `ray` may meet: each whose kept box it crosses, and each with no box kept. */
  meeting(meshes: readonly AbstractMesh[], ray: Ray): AbstractMesh[];
  /** The same, for a line straight up or down through (x, z): each whose kept box reaches it, and each with no box kept. */
  column(meshes: readonly AbstractMesh[], x: number, z: number): AbstractMesh[];
}

/** An index for one list at a time; `freshen` brings a mesh's world matrix up to date before its box is read. */
export function createBoxIndex(freshen: (mesh: AbstractMesh) => void): BoxIndex {
  let list: AbstractMesh[] = [];
  // The count of places held when the boxes were last read.
  let readAt = -1;
  // Six numbers a mesh, its box's least and greatest x, y and z; and whether it has one kept. Two of each, the
  // last read's and the one being read, so a box still good is copied across rather than read again.
  let boxes = new Float64Array(0);
  let keptBox = new Uint8Array(0);
  let spareBoxes = new Float64Array(0);
  let spareKept = new Uint8Array(0);

  const sync = (meshes: readonly AbstractMesh[]) => {
    const held = placesHeld();
    if (held === readAt && meshes.length === list.length) {
      let same = true;
      for (let i = 0; i < meshes.length; i++)
        if (meshes[i] !== list[i]) {
          same = false;
          break;
        }
      if (same) return;
    }
    const was = list, wasBoxes = boxes, wasKept = keptBox, wasAt = readAt;
    let wasIndex: Map<AbstractMesh, number> | undefined;
    const n = meshes.length;
    if (spareKept.length < n) {
      spareBoxes = new Float64Array(n * 6);
      spareKept = new Uint8Array(n);
    }
    boxes = spareBoxes;
    keptBox = spareKept;
    spareBoxes = wasBoxes;
    spareKept = wasKept;
    list = meshes.slice();
    readAt = held;
    for (let i = 0; i < n; i++) {
      const m = list[i]!;
      keptBox[i] = 0;
      // Where the mesh was in the last list, and so its box then, if it had one and its place is not held since.
      let j = was[i] === m ? i : -1;
      if (j < 0 && was.length) {
        if (!wasIndex) {
          wasIndex = new Map();
          for (let k = 0; k < was.length; k++) wasIndex.set(was[k]!, k);
        }
        j = wasIndex.get(m) ?? -1;
      }
      if (j >= 0 && wasKept[j] && heldWhen(m) <= wasAt) {
        for (let k = 0; k < 6; k++) boxes[i * 6 + k] = wasBoxes[j * 6 + k]!;
        keptBox[i] = 1;
        continue;
      }
      if (m.isDisposed() || !m.isWorldMatrixFrozen || boxSaysNothing(m)) continue;
      freshen(m);
      const b = m.getBoundingInfo().boundingBox;
      const lo = b.minimumWorld, hi = b.maximumWorld;
      boxes[i * 6] = lo.x;
      boxes[i * 6 + 1] = lo.y;
      boxes[i * 6 + 2] = lo.z;
      boxes[i * 6 + 3] = hi.x;
      boxes[i * 6 + 4] = hi.y;
      boxes[i * 6 + 5] = hi.z;
      keptBox[i] = 1;
    }
  };

  return {
    meeting(meshes, ray) {
      sync(meshes);
      const out: AbstractMesh[] = [];
      for (let i = 0; i < list.length; i++) {
        const k = i * 6;
        if (!keptBox[i] || rayCrossesBox(ray, boxes[k]!, boxes[k + 1]!, boxes[k + 2]!, boxes[k + 3]!, boxes[k + 4]!, boxes[k + 5]!)) out.push(list[i]!);
      }
      return out;
    },
    column(meshes, x, z) {
      sync(meshes);
      const out: AbstractMesh[] = [];
      for (let i = 0; i < list.length; i++) {
        const k = i * 6;
        if (!keptBox[i] || (x >= boxes[k]! - BOX_SLACK_M && x <= boxes[k + 3]! + BOX_SLACK_M && z >= boxes[k + 2]! - BOX_SLACK_M && z <= boxes[k + 5]! + BOX_SLACK_M)) out.push(list[i]!);
      }
      return out;
    },
  };
}
