/**
 * What a frame need not do for the terrain's tiles and blocks. They never
 * move against the node they hang from, so their world matrices (and the
 * bounds read from them) are worked out once and frozen, not again every
 * frame; whoever moves that node holds the places again after it, parents
 * before children, since a child's matrix is made from its parent's. And the
 * meshes in them with nothing to draw (a glTF's root, which turns its
 * right-handed data into the scene's left-handed frame) become plain nodes,
 * which no frame looks over to see whether they are in view.
 */
import { TransformNode } from '@babylonjs/core/Meshes/transformNode';
import type { AbstractMesh } from '@babylonjs/core/Meshes/abstractMesh';
import type { Scene } from '@babylonjs/core/scene';

/** A loaded asset's nodes and meshes, parents first. */
export function placesOf(container: { meshes: readonly TransformNode[]; transformNodes: readonly TransformNode[] }): TransformNode[] {
  const depth = new Map<TransformNode, number>();
  for (const n of [...container.transformNodes, ...container.meshes]) {
    let d = 0;
    for (let p = n.parent; p; p = p.parent) d++;
    depth.set(n, d);
  }
  return [...depth.keys()].sort((a, b) => depth.get(a)! - depth.get(b)!);
}

let held = 0;
const heldAt = new WeakMap<TransformNode, number>();

/** Works out each node's world matrix from its parent's as they are now, and holds it there. */
export function holdPlaces(nodes: readonly TransformNode[]): void {
  held++;
  for (const n of nodes)
    if (!n.isDisposed()) {
      n.freezeWorldMatrix();
      heldAt.set(n, held);
    }
}

/** A count that grows whenever places are held: until it does, a held mesh, and its box, stay where they are. */
export const placesHeld = (): number => held;

/** The count at which a node's place was last held, or -1 if never: a box read at that count or later still holds. */
export const heldWhen = (node: TransformNode): number => heldAt.get(node) ?? -1;

/**
 * Puts a node in place of each mesh of a loaded asset (already in the scene)
 * that has nothing to draw, with its transform, parent and children, and lets
 * the mesh go: the asset looks and lies as it did.
 */
export function emptiesAsNodes(container: { meshes: AbstractMesh[]; transformNodes: TransformNode[] }, scene: Scene): void {
  const empty = container.meshes.filter((m) => m.getClassName() === 'Mesh' && m.getTotalVertices() === 0);
  if (!empty.length) return;
  for (const m of empty) {
    const n = new TransformNode(m.name, scene);
    n.position.copyFrom(m.position);
    if (m.rotationQuaternion) n.rotationQuaternion = m.rotationQuaternion.clone();
    else n.rotation.copyFrom(m.rotation);
    n.scaling.copyFrom(m.scaling);
    n.parent = m.parent;
    for (const c of m.getChildren()) c.parent = n;
    container.transformNodes.push(n);
    m.dispose(true);
  }
  const gone = new Set(empty);
  container.meshes = container.meshes.filter((m) => !gone.has(m));
}
