/**
 * When a planet's contact shadows and motion blur are drawn, and the
 * fetching of their code-split passes (contactShadowsChunk.ts,
 * motionBlurChunk.ts). Both are the visitor's device and comfort settings,
 * not the world's look:
 *
 * - Contact shadows come with the quality tier, and only while the sun casts
 *   shadows on the visitor's device: they refine those shadows where a block
 *   meets the ground. A tier without them, or a view whose sun casts none,
 *   never fetches their chunk.
 * - Motion blur comes only with the visitor's choice, and never while they
 *   are presenting in VR: there it is made only once they are out, and given
 *   back as they go in or turn it off. Off by default, its chunk is never
 *   fetched.
 *
 * Off, nothing is fetched or added to the camera, so the picture is today's.
 */
import type { Scene } from '@babylonjs/core/scene';
import type { FreeCamera } from '@babylonjs/core/Cameras/freeCamera';
import type { ShadowGenerator } from '@babylonjs/core/Lights/Shadows/shadowGenerator';

export interface ContactShadowsHandle {
  /** Each frame: the sun's shadow generator, or null while it casts none. */
  update(frame: { shadows: ShadowGenerator | null }): void;
  dispose(): void;
}

export interface ContactShadowsModule {
  createContactShadows(scene: Scene, camera: FreeCamera, opts: { engineKind?: string }): ContactShadowsHandle;
}

export interface MotionBlurHandle {
  /** Each frame: seconds since the frame before. */
  update(frame: { dtS: number }): void;
  dispose(): void;
}

export interface MotionBlurModule {
  createMotionBlur(scene: Scene, camera: FreeCamera, opts: { engineKind?: string }): MotionBlurHandle;
}

export interface ContactAndBlurOptions {
  scene: Scene;
  camera: FreeCamera;
  engineKind?: string;
  /** Whether the visitor's tier draws contact shadows. */
  contactShadows: boolean;
  /** The visitor's motion blur choice, read each frame; off without it. */
  motionBlur?: () => boolean;
  /** Whether the visitor is presenting in VR, read each frame; without it, whether another camera owns the view, as WebXR's does while presenting. */
  presenting?: () => boolean;
  loadContactShadows: () => Promise<ContactShadowsModule>;
  loadMotionBlur: () => Promise<MotionBlurModule>;
  /** Told of each fetch, so the view knows when none is pending. */
  track?: (p: Promise<unknown>) => void;
  warn: (name: string, detail: string) => void;
}

export function createContactAndBlur(o: ContactAndBlurOptions): { frame(f: { dtS: number; shadows: ShadowGenerator | null }): void; dispose(): void } {
  const kind = o.engineKind ? { engineKind: o.engineKind } : {};
  let gone = false;
  let contact: ContactShadowsHandle | undefined;
  let contactAsked = false;
  let blurModule: MotionBlurModule | undefined;
  let blur: MotionBlurHandle | undefined;
  let blurAsked = false;

  const fetch = <T>(load: () => Promise<T>, name: string, then: (m: T) => void) => {
    const p = (async () => {
      try {
        const m = await load();
        if (!gone) then(m);
      } catch (err) {
        o.warn(name, String(err));
      }
    })();
    o.track?.(p);
  };

  return {
    frame({ dtS, shadows }) {
      if (o.contactShadows) {
        if (contact) contact.update({ shadows });
        else if (shadows && !contactAsked) {
          contactAsked = true;
          fetch(o.loadContactShadows, 'veml:planet:contact-shadows-unavailable', (m) => {
            contact = m.createContactShadows(o.scene, o.camera, kind);
          });
        }
      }
      const blurWanted = (o.motionBlur?.() ?? false) && !(o.presenting ? o.presenting() : o.scene.activeCamera !== o.camera);
      if (!blurWanted) {
        blur?.dispose();
        blur = undefined;
      } else if (blur) blur.update({ dtS });
      else if (blurModule) blur = blurModule.createMotionBlur(o.scene, o.camera, kind);
      else if (!blurAsked) {
        blurAsked = true;
        fetch(o.loadMotionBlur, 'veml:planet:motion-blur-unavailable', (m) => {
          blurModule = m;
        });
      }
    },
    dispose() {
      gone = true;
      contact?.dispose();
      contact = undefined;
      blur?.dispose();
      blur = undefined;
    },
  };
}
