/**
 * A planet's water mirrors what stands over it: the shore, the trees and the
 * cliffs, taken from the picture already drawn (screen-space reflections).
 *
 * From a point on the water, the view reflected in the surface is followed
 * across the screen in steps that lengthen as they go, each step's point
 * looked up in the depth map of the scene without its water. Where the ray
 * passes just behind what is drawn there, it has met it: the meeting is found
 * closer by halving the last step, and the water shows the colour drawn at
 * that place in the frame before, found again where the camera has moved it.
 * Where the ray leaves the screen, turns back into the water or meets nothing,
 * the water keeps the sky it mirrors already. The mirror fades out toward the
 * screen's edges and toward the depth map's reach, so the change to the sky
 * shows no edge. The swell and the ripple lean the surface, and so the ray,
 * which breaks the mirror up as they break up the sky: by a share of their
 * lean only, since at the low angles a shore is seen at, the whole of it
 * turns many rays down into the water, which would leave the mirror in holes.
 *
 * At less than full detail the march takes every second (third...) point of
 * the full march's: fewer steps, each as long as the ones it stands for, so it
 * reaches as far.
 *
 * This is the reference the water's shader (waterReflectChunk.ts) follows,
 * with these constants. Pure: no Babylon, no DOM.
 */
import type { Vec3 } from './planetFrame';

export const MIRROR = {
  /** Steps along the reflected ray at full detail. */
  steps: 32,
  /** Each step this much longer than the one before, at full detail. */
  growth: 1.12,
  /** The first step: this share of the water's distance from the eye, and at least `firstStepM` metres. */
  firstShare: 0.03,
  firstStepM: 0.5,
  /** Halvings of the last step, to find where the ray met what is drawn. */
  refine: 5,
  /** How far behind what is drawn the ray may pass and still have met it: this share of the step, and at least `thickM` metres. */
  thickShare: 1.5,
  thickM: 1,
  /** The share of the screen's width and height at its edges over which the mirror fades out. */
  edge: 0.08,
  /** How far along the view the depth map is drawn, metres: past it the ray meets nothing, and is followed no further. */
  reachM: 400,
  /** The water's distance from the eye over which the mirror fades out, metres: the depth map is drawn to 400 m. */
  fadeFromM: 300,
  fadeToM: 400,
  /** Below this share of the sky mirrored (Fresnel's), the trace is not taken: looking down, little is mirrored. */
  minShare: 0.03,
  /** The share of the swell's and the ripple's lean the traced ray takes. */
  lean: 0.35,
  /** A camera that moves further than this in a frame has jumped: the frame before shows another place. */
  jumpM: 25,
} as const;

/** The numbers the shader must carry as the reference does, written as it writes them. */
export const MIRROR_CONSTANTS = [String(MIRROR.firstShare), String(MIRROR.thickShare), String(MIRROR.edge), String(MIRROR.minShare), String(MIRROR.lean)] as const;

/** The march at a share of full detail, 0 to 1: its steps, its growth, and its first step's length against the full march's first. None at 0. */
export function mirrorMarch(detail: number): { steps: number; growth: number; firstScale: number } {
  const d = Number.isFinite(detail) ? Math.min(1, Math.max(0, detail)) : 0;
  if (d <= 0) return { steps: 0, growth: MIRROR.growth, firstScale: 1 };
  const k = 1 / d;
  const growth = MIRROR.growth ** k;
  return { steps: Math.max(1, Math.round(MIRROR.steps * d)), growth, firstScale: (growth - 1) / (MIRROR.growth - 1) };
}

/** How much of the mirror is kept at a place on the screen (0 to 1 each way): none at its edges, all of it a little way in. */
export function mirrorEdge(uv: readonly [number, number]): number {
  const inside = Math.min(uv[0], 1 - uv[0], uv[1], 1 - uv[1]);
  return smoothstep(0, MIRROR.edge, inside);
}

/** How much of the mirror is kept on water this far from the eye: all of it near, none past the depth map's reach. */
export function mirrorReach(distance: number): number {
  return 1 - smoothstep(MIRROR.fadeFromM, MIRROR.fadeToM, distance);
}

/** The screen the ray is followed across. Points are relative to the eye. */
export interface MirrorScreen {
  /** The point on the screen now, -1 to 1 each way (up the screen positive), and its depth along the view; null at or behind the eye. */
  project(q: Vec3): { ndc: [number, number]; z: number } | null;
  /** The depth along the view of what is drawn at a place on the screen (0 to 1 each way, up positive), the water left out; 0 where nothing is. */
  depthAt(uv: [number, number]): number;
}

/**
 * Follows the view reflected at the water point `p` (relative to the eye)
 * along `r`, from `startUv`, the point's own place on the screen. Returns
 * where the ray met what is drawn, as a place on the screen and a point
 * relative to the eye, with how much of the mirror the screen's edges leave
 * there; or null where it leaves the screen, turns into the water (against
 * `up`) or meets nothing.
 */
export function mirrorTrace(p: Vec3, r: Vec3, up: Vec3, startUv: [number, number], screen: MirrorScreen, detail: number): { uv: [number, number]; q: Vec3; weight: number } | null {
  const march = mirrorMarch(detail);
  if (march.steps <= 0 || dot(r, up) <= 0) return null;
  const start = screen.project(p);
  if (!start) return null;
  const at = (t: number): { uv: [number, number]; z: number; q: Vec3 } | null => {
    const q: Vec3 = [p[0] + r[0] * t, p[1] + r[1] * t, p[2] + r[2] * t];
    const s = screen.project(q);
    if (!s) return null;
    return { uv: [startUv[0] + (s.ndc[0] - start.ndc[0]) * 0.5, startUv[1] + (s.ndc[1] - start.ndc[1]) * 0.5], z: s.z, q };
  };
  const off = (uv: [number, number]) => uv[0] < 0 || uv[0] > 1 || uv[1] < 0 || uv[1] > 1;
  let step = Math.max(MIRROR.firstStepM, MIRROR.firstShare * Math.hypot(p[0], p[1], p[2])) * march.firstScale;
  let before = 0;
  let t = 0;
  for (let i = 0; i < march.steps; i++) {
    t += step;
    const s = at(t);
    if (!s || off(s.uv) || s.z > MIRROR.reachM) return null;
    const drawn = screen.depthAt(s.uv);
    if (drawn > 0 && s.z > drawn && s.z - drawn < Math.max(MIRROR.thickM, MIRROR.thickShare * step)) {
      // Met: halve the last step toward the meeting.
      let lo = before;
      let hi = t;
      for (let j = 0; j < MIRROR.refine; j++) {
        const mid = (lo + hi) * 0.5;
        const m = at(mid);
        if (m && !off(m.uv) && screen.depthAt(m.uv) > 0 && m.z > screen.depthAt(m.uv)) hi = mid;
        else lo = mid;
      }
      const hit = at(hi) ?? s;
      return { uv: hit.uv, q: hit.q, weight: mirrorEdge(hit.uv) };
    }
    before = t;
    step *= march.growth;
  }
  return null;
}

/** The ray traced from water whose surface leans to `n` (up from the planet `up`), seen along `v` (toward the eye): the view reflected in a surface leaned by a share of it. */
export function mirrorRay(v: Vec3, n: Vec3, up: Vec3): Vec3 {
  const m: Vec3 = [up[0] + (n[0] - up[0]) * MIRROR.lean, up[1] + (n[1] - up[1]) * MIRROR.lean, up[2] + (n[2] - up[2]) * MIRROR.lean];
  const l = Math.hypot(m[0], m[1], m[2]) || 1;
  const t: Vec3 = [m[0] / l, m[1] / l, m[2] / l];
  const vt = dot(v, t);
  return [2 * vt * t[0] - v[0], 2 * vt * t[1] - v[1], 2 * vt * t[2] - v[2]];
}

/** What a world's `water-mirror` hint asks: `none` for none, a share 0 to 1, or the shell's (all of it) for `auto` and anything else. */
export function mirrorAskOf(value: string | null | undefined): number {
  if (value === 'none') return 0;
  if (value === null || value === undefined || value === 'auto' || value.trim() === '') return 1;
  const x = Number(value);
  return Number.isFinite(x) ? Math.min(1, Math.max(0, x)) : 1;
}

/** The mirror's strength and detail as drawn: the world's ask, where the visitor's tier traces it (detail over 0) and the water's depth is measured; else none. */
export function mirrorOf(o: { ask: number; detail: number; depth: boolean }): { strength: number; detail: number } {
  const detail = Number.isFinite(o.detail) ? Math.min(1, Math.max(0, o.detail)) : 0;
  if (!o.depth || detail <= 0) return { strength: 0, detail: 0 };
  return { strength: Math.min(1, Math.max(0, o.ask)), detail };
}

function smoothstep(a: number, b: number, x: number): number {
  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
}

function dot(a: Vec3, b: Vec3): number {
  return a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
}
