/**
 * A planet's plants and leaves sway in its wind. A plant's foot stays where it
 * grows and its top leans the way the wind blows (each point weighed by its
 * chunk: 0 at the foot, 1 at the top); a tree's leaves rustle less and more
 * slowly, the whole crown together. The wind comes in gusts: a smooth pattern
 * of stronger and weaker air, a few tens of metres across, carried downwind,
 * so the sway differs from place to place and moment to moment. Over the
 * gusts each point flutters back and forth, its timing set by where it is.
 *
 * Every part is a smooth function of a point's position (and the clock), so
 * faces that share a corner move together and nothing tears. The movement is
 * along the ground only: with the wind, and a little across it.
 *
 * The world sets how strongly (`planet.sway`) and how fast (`planet.sway-speed`)
 * its plants move; the wind's direction and its strength are its clouds'
 * (`planet.wind`, eastward around the planet's axis, negative westward), so the
 * plants lean the way the clouds drift.
 *
 * This is the reference the sway's shader (swayChunk.ts) follows, on the
 * processor, and the small controller the planet view drives it with: it
 * fetches the code-split chunk only when the world wants any sway and the
 * visitor's tier draws it, and feeds it each frame. The clock keeps each
 * motion's phase, so a change of speed never jumps.
 */
import type { Scene } from '@babylonjs/core/scene';
import type { Vec3 } from './planetFrame';

/** What a world asks of its plants' sway (read live): how strongly they move and how fast, each 0 to SWAY_MAX. */
export interface SwayAsk {
  strength: number;
  speed: number;
}

/** The shell's: the sway as it is drawn here, at its own pace. */
export const SWAY_DEFAULTS: SwayAsk = { strength: 1, speed: 1 };
/** The most a world may ask of either. */
export const SWAY_MAX = 4;
/** The clouds' wind the shell's sway is drawn for, metres a second: the lowest layer's own (clouds.ts). */
export const SWAY_WIND_MS = 8;

/** How a kind of plant moves at strength 1, in metres at weight 1: its steady lean, the gusts' push, its flutter with the wind and across it, and how often it flutters (a second). */
export interface SwayKind {
  lean: number;
  gust: number;
  flutter: number;
  side: number;
  flutterHz: number;
  sideHz: number;
}

/** A plant a block tall: leaning tens of centimetres at the top in a gust. */
export const SWAY_PLANT: SwayKind = { lean: 0.03, gust: 0.14, flutter: 0.04, side: 0.025, flutterHz: 1.1, sideHz: 0.83 };
/** A tree's leaves: a few centimetres, more slowly. */
export const SWAY_LEAVES: SwayKind = { lean: 0.008, gust: 0.03, flutter: 0.012, side: 0.01, flutterHz: 0.55, sideHz: 0.41 };
/** The gusts: each wave's length downwind and across it in metres, and its share of the gusts' swing. */
export const SWAY_GUSTS: readonly (readonly [number, number, number])[] = [
  [48, 90, 0.3],
  [23, -37, 0.2],
];
/** Radians of flutter phase per metre downwind and across it, so neighbouring plants are out of step. */
export const SWAY_SPREAD: readonly [number, number] = [0.35, 0.55];
/** The flutter's least share of its swing, in the stillest air between gusts. */
export const SWAY_FLUTTER_FLOOR = 0.4;
/** How much faster the swing across the wind falls out of step from point to point than the flutter with it. */
export const SWAY_SIDE_SPREAD = 1.3;
/** How fast the gusts travel, as a share of the wind's speed, and the least they travel at. */
const GUST_SHARE = 0.6;
const GUST_LEAST_MS = 1;
/** How much of the sway is left in a calm, and the strongest wind the sway grows with, as a share of SWAY_WIND_MS. */
const CALM_SHARE = 0.3;
const WINDIEST = 2;

/** A number as both shader languages write a float. */
export const f = (x: number): string => (Number.isInteger(x) ? x.toFixed(1) : String(x));

/** The numbers the shader must carry as the reference does, written as it writes them. */
export const SWAY_CONSTANTS: readonly string[] = [
  ...[SWAY_PLANT, SWAY_LEAVES].flatMap((k) => [k.lean, k.gust, k.flutter, k.side].map(f)),
  ...SWAY_GUSTS.flatMap(([a, b, s]) => [f(a), f(b), f(s)]),
  ...SWAY_SPREAD.map(f),
  f(SWAY_FLUTTER_FLOOR),
  f(SWAY_SIDE_SPREAD),
];

/** Each motion's phase, radians: the plants' flutter and their side swing, the leaves' two, and the two gust waves' travel. */
export interface SwayClock {
  phase: [number, number, number, number];
  gust: [number, number];
}

export const SWAY_START: SwayClock = { phase: [0, 0, 0, 0], gust: [0, 0] };

const TAU = Math.PI * 2;

/** How fast the gusts travel downwind, metres a second, in a wind of `windMs` (either way). */
export function gustSpeed(windMs: number): number {
  return Math.max(GUST_LEAST_MS, Math.abs(windMs) * GUST_SHARE);
}

/** The clock `dtS` seconds on, at `speed` times the shell's pace, in a wind of `windMs`. */
export function advanceSway(c: SwayClock, dtS: number, speed: number, windMs: number): SwayClock {
  const t = dtS * Math.max(0, speed);
  if (t === 0) return c;
  const turn = (a: number, rate: number) => (a + rate * t) % TAU;
  const v = gustSpeed(windMs);
  return {
    phase: [turn(c.phase[0], TAU * SWAY_PLANT.flutterHz), turn(c.phase[1], TAU * SWAY_PLANT.sideHz), turn(c.phase[2], TAU * SWAY_LEAVES.flutterHz), turn(c.phase[3], TAU * SWAY_LEAVES.sideHz)],
    gust: [turn(c.gust[0], (TAU / SWAY_GUSTS[0]![0]) * v), turn(c.gust[1], (TAU / SWAY_GUSTS[1]![0]) * v)],
  };
}

/** What the sway's shader is given each frame. Positions and directions are the scene's. */
export interface SwayState extends SwayClock {
  /** A point the gusts' pattern is laid out about, which moves with the planet, not the eye. */
  origin: Vec3;
  /** Along the ground, the way the wind blows; and across it. */
  wind: Vec3;
  side: Vec3;
  /** How strongly everything sways: the world's strength, grown or shrunk by its wind. */
  strength: number;
}

/** The sway's strength for a world asking `strength`, in a wind of `windMs`: a little in a calm, up to twice the shell's in a gale. */
export function swayStrength(strength: number, windMs: number): number {
  const windy = Math.min(Math.abs(windMs) / SWAY_WIND_MS, WINDIEST);
  return Math.max(0, strength) * (CALM_SHARE + (1 - CALM_SHARE) * windy);
}

/** The state for the shader, from east and north at `origin`, the clouds' wind and the world's strength. */
export function swayStateOf(o: { origin: Vec3; east: Vec3; north: Vec3; windMs: number; strength: number }, c: SwayClock): SwayState {
  const sign = o.windMs < 0 ? -1 : 1;
  return {
    origin: o.origin,
    wind: [o.east[0] * sign, o.east[1] * sign, o.east[2] * sign],
    side: [o.north[0] * sign, o.north[1] * sign, o.north[2] * sign],
    strength: swayStrength(o.strength, o.windMs),
    phase: c.phase,
    gust: c.gust,
  };
}

const dot = (a: Vec3, b: Vec3) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];

/** Where `p` lies downwind and across the wind from the pattern's origin, metres. */
function along(p: Vec3, s: SwayState): [number, number] {
  const r: Vec3 = [p[0] - s.origin[0], p[1] - s.origin[1], p[2] - s.origin[2]];
  return [dot(r, s.wind), dot(r, s.side)];
}

/** How strong the gust at `p` is now: 0 still air to 1 the strongest. */
export function gustAt(p: Vec3, s: SwayState): number {
  const [a, b] = along(p, s);
  let g = 0.5;
  SWAY_GUSTS.forEach(([down, across, share], i) => {
    g += share * Math.sin((TAU / down) * a + (TAU / across) * b - s.gust[i]!);
  });
  return g * g;
}

/**
 * How far the wind moves the point `p` now, in the scene: a plant's (weighed
 * 0 at its foot to 1 at its top) or a tree's leaves (weight 1).
 */
export function swayOffset(p: Vec3, weight: number, kind: 'plant' | 'leaves', s: SwayState): Vec3 {
  const scale = weight * s.strength;
  if (scale === 0) return [0, 0, 0];
  const k = kind === 'plant' ? SWAY_PLANT : SWAY_LEAVES;
  const [flutterPhase, sidePhase] = kind === 'plant' ? [s.phase[0], s.phase[1]] : [s.phase[2], s.phase[3]];
  const [a, b] = along(p, s);
  const g = gustAt(p, s);
  const spread = SWAY_SPREAD[0] * a + SWAY_SPREAD[1] * b;
  const swing = SWAY_FLUTTER_FLOOR + g;
  const down = (k.lean + k.gust * g + k.flutter * swing * Math.sin(flutterPhase + spread)) * scale;
  const across = k.side * swing * Math.sin(sidePhase + SWAY_SIDE_SPREAD * spread) * scale;
  return [s.wind[0] * down + s.side[0] * across, s.wind[1] * down + s.side[1] * across, s.wind[2] * down + s.side[2] * across];
}

/** A world's sway, from its hints in force (`ClientHints.Get`): `none` for none, `auto` or anything unreadable for the shell's. */
export function swayAskOf(hint: (name: string) => string | null | undefined): SwayAsk {
  const read = (name: string, d: number): number => {
    const v = hint(name);
    if (v === null || v === undefined || v === 'auto') return d;
    if (v === 'none') return 0;
    const x = Number(v);
    return v.trim() !== '' && Number.isFinite(x) ? Math.min(SWAY_MAX, Math.max(0, x)) : d;
  };
  return { strength: read('planet.sway', SWAY_DEFAULTS.strength), speed: read('planet.sway-speed', SWAY_DEFAULTS.speed) };
}

export interface SwayHandle {
  update(state: SwayState): void;
  dispose(): void;
}

export interface SwayModule {
  createSwayOn(scene: Scene, opts: { engineKind?: string }): SwayHandle;
}

/** What the planet view hands the sway each frame, in the scene: a point near the visitor that holds still, east and north there, and the clouds' wind. */
export interface SwayFrame {
  origin: Vec3;
  east: Vec3;
  north: Vec3;
  windMs: number;
  deltaMs: number;
}

/**
 * The planet view's sway: the chunk fetched the first time the world asks for
 * any (and the visitor's tier, `allowed`, draws it), then fed each frame, and
 * let go with `dispose`.
 */
export function createSway(o: {
  scene: Scene;
  load: () => Promise<SwayModule>;
  ask: () => SwayAsk;
  engineKind?: string;
  track: <T>(p: Promise<T>) => Promise<T>;
  warn: (name: string, detail: string) => void;
  allowed?: boolean;
}): { frame(f: SwayFrame): void; dispose(): void } {
  let handle: SwayHandle | undefined;
  let asked = false;
  let gone = false;
  let clock = SWAY_START;
  return {
    frame(f) {
      if (o.allowed === false) return;
      const ask = o.ask();
      clock = advanceSway(clock, f.deltaMs / 1000, ask.speed, f.windMs);
      if (!handle) {
        if (asked || ask.strength <= 0) return;
        asked = true;
        void o.track(
          (async () => {
            try {
              const m = await o.load();
              const h = m.createSwayOn(o.scene, o.engineKind ? { engineKind: o.engineKind } : {});
              if (gone) h.dispose();
              else handle = h;
            } catch (err) {
              o.warn('veml:planet:sway-unavailable', String(err));
            }
          })(),
        );
        return;
      }
      handle.update(swayStateOf({ origin: f.origin, east: f.east, north: f.north, windMs: f.windMs, strength: ask.strength }, clock));
    },
    dispose() {
      gone = true;
      handle?.dispose();
      handle = undefined;
    },
  };
}
