/**
 * How much on-screen error a planet's far terrain may show, by how high the
 * eye is over its ground. A far tile is refined while its height error would
 * show as more than this many pixels; but a tile's colours change from cell
 * to cell over about twice its height error, so from high up a planet drawn to
 * the ground's error shows its cells as squares. Near the ground the tier's
 * own error stands, and the ground costs what it did; from high up, where the
 * whole planet is a few hundred pixels and few tiles cover it, the tier's far
 * error, which is finer, so the planet is drawn in detail from space.
 */

/** Below this altitude, metres, the tier's own error. */
export const FAR_DETAIL_FROM_M = 2_000;
/** Above this altitude, metres, the tier's far error. */
export const FAR_DETAIL_AT_M = 30_000;

/** The error, in pixels, at `altitude` metres over the ground: `near` low down, `far` high up, eased between; never coarser than `near`. */
export function screenErrorAt(altitude: number, near: number, far: number): number {
  const goal = Math.min(near, far);
  const t = Math.min(1, Math.max(0, (altitude - FAR_DETAIL_FROM_M) / (FAR_DETAIL_AT_M - FAR_DETAIL_FROM_M)));
  const s = t * t * (3 - 2 * t);
  return near + (goal - near) * s;
}
