/**
 * A planet's fog and haze, as the world sets them. Both are summed along the
 * line from the eye to what it sees, through air whose thickness falls off
 * with height, so they belong to the place and not to the eye: from orbit the
 * ground shows the same fog it shows from a hill, and the empty air around an
 * eye in space holds none.
 *
 * Fog lies low: its thickness falls by e for every `height` metres over its
 * `floor` (the sea's level unless it is given one), so it pools in hollows and over
 * water. It is thickest about sunrise and burns off by noon, and it comes in
 * patches, a slow noise over the planet, as far as the world asks. Haze is
 * the air's own, from its atmosphere, as strong as the world asks: by
 * default, half of what lies a third of the air's height away at the ground
 * is hidden.
 *
 * This is the reference the fog's shader (atmosphereChunk.ts) follows. Along
 * a line the altitude is taken to change evenly from one end to the other,
 * which the planet's curve bends little over the distances fog is seen across.
 */
import type { Atmosphere, Vec3 } from './atmosphere';
import { cloudNoise } from './clouds';

/** What a world says of its fog; anything left out is the shell's default. */
export interface FogSettings {
  /** How thick, 0 (none) to 1 (thickest), at its floor at dawn in its dampest patches. */
  amount?: number;
  /** Metres over the floor in which its thickness falls by e. */
  height?: number;
  /** Its colour in full light, red, green and blue, 0 to 1. */
  color?: Vec3;
  /** How patchy, 0 (even everywhere) to 1 (some places clear). */
  patchiness?: number;
  /** The altitude, in metres, it lies on: by default the sea's. */
  floor?: number;
}

export interface FogLayer {
  amount: number;
  /** The thickness at the floor, at full amount, per metre. */
  density: number;
  height: number;
  /** The altitude, in metres, the fog lies on. */
  floor: number;
  color: Vec3;
  patchiness: number;
  /** Metres across a patch, about. */
  patchSize: number;
  /** Metres from the planet's centre to the floor: where the patches are drawn. */
  radius: number;
}

/** The shell's defaults: a light morning mist, eighty metres deep, pale grey, in patches. */
export const FOG_DEFAULTS = { amount: 0.15, height: 80, color: [0.82, 0.84, 0.86] as Vec3, patchiness: 0.7, patchSize: 6000 };
/** Thickness, per metre, at the floor of the thickest fog: about two hundred metres to see through. */
const THICKEST_PER_M = 0.02;

export function fogLayerOf(a: Atmosphere, s: FogSettings): FogLayer {
  const amount = Math.min(1, Math.max(0, s.amount ?? FOG_DEFAULTS.amount));
  return {
    amount,
    density: THICKEST_PER_M * amount,
    height: Math.max(1, s.height ?? FOG_DEFAULTS.height),
    floor: s.floor ?? 0,
    color: s.color ?? FOG_DEFAULTS.color,
    patchiness: Math.min(1, Math.max(0, s.patchiness ?? FOG_DEFAULTS.patchiness)),
    patchSize: FOG_DEFAULTS.patchSize,
    radius: a.radius,
  };
}

/**
 * The thickness summed along a line `length` metres long from altitude
 * `fromAlt` to `toAlt`, of a medium `density` per metre at `floor` falling by
 * e every `height` metres: the altitude taken to change evenly along it.
 */
function depthAlong(density: number, height: number, floor: number, fromAlt: number, toAlt: number, length: number): number {
  if (density <= 0 || length <= 0) return 0;
  const u0 = Math.max(fromAlt - floor, 0) / height;
  const u1 = Math.max(toAlt - floor, 0) / height;
  const du = u1 - u0;
  if (Math.abs(du) < 1e-6) return density * length * Math.exp(-u0);
  return (density * length * (Math.exp(-u0) - Math.exp(-u1))) / du;
}

/** The fog along a line, at full strength: as dawn and the patches leave it, see `dawnFactor` and `humidity`. */
export function fogDepth(f: FogLayer, fromAlt: number, toAlt: number, length: number): number {
  return depthAlong(f.density, f.height, f.floor, fromAlt, toAlt, length);
}

/** How far off, as a share of the air's height, the haze hides half of what lies at the ground, by default. */
export const HAZE_HALF_SHARE = 0.35;

/** The haze's thickness per metre at altitude 0, as strong as the world asks (1 the shell's). */
export const hazeBeta = (a: Atmosphere, strength = 1): number => (strength * Math.LN2) / (HAZE_HALF_SHARE * a.top);

/**
 * How much of what lies behind a thickness `depth` of haze the eye still sees:
 * little lost near, half at the haze's distance (`depth` ln 2), most beyond,
 * as aerial haze is seen, so the ground nearby keeps its grain and colour.
 */
export const hazeSeen = (depth: number): number => Math.exp(-depth * depth * HAZE_SEEN);
/** 1 / ln 2: the haze's sight falls as the square of its thickness, halving at ln 2. */
const HAZE_SEEN = 1.4427;
/** The number the shaders carry as the reference does, written as they write it. */
export const HAZE_SEEN_K = '1.4427';

/** The air's haze along a line: by default, half of what lies a third of the air's height away at the ground is hidden (see `hazeSeen`). */
export function hazeDepth(a: Atmosphere, fromAlt: number, toAlt: number, length: number, strength = 1): number {
  return depthAlong(hazeBeta(a, strength), a.rayleighHeight, 0, fromAlt, toAlt, length);
}

const smoothstep = (e0: number, e1: number, x: number) => {
  const t = Math.min(1, Math.max(0, (x - e0) / (e1 - e0)));
  return t * t * (3 - 2 * t);
};

/**
 * How much of the fog there is with the sun `sunUp` over the horizon (the
 * sine of its height): all of it about sunrise, less in the night, and little
 * once the sun is high.
 */
export function dawnFactor(sunUp: number): number {
  return sunUp < 0.1 ? 0.6 + 0.4 * smoothstep(-0.3, 0, sunUp) : 1 - 0.85 * smoothstep(0.1, 0.55, sunUp);
}

/** How damp the place under the unit direction `dir` (planet frame) is, 0 to 1: the fog's patches. */
export function humidity(f: FogLayer, dir: Vec3): number {
  if (f.patchiness <= 0) return 1;
  const k = f.radius / f.patchSize;
  const n = cloudNoise(dir[0] * k + 17.3, dir[1] * k, dir[2] * k - 5.1, 3);
  return 1 - f.patchiness * (1 - smoothstep(0.35, 0.65, n));
}
