/**
 * A cube-sphere planet's areas near the viewer
 * (specs/veml/profiles/planet-cube-sphere.md, Areas and chunks).
 *
 * Around the visitor, the area's chunks are fetched column by column, nearest
 * first. A column's chunks are the ones whose heights meet the terrain over
 * it, with a few blocks below for hollows and more above for trees.
 *
 * The chunks hang under one node whose map is the scheme's mapping expanded
 * at the visitor's own area point (cubeSphere.ts, areaMap), recomputed every
 * frame. Blocks under the visitor are exactly where the planet has them, so
 * the blocks meet the terrain drawn through the mapping. This stretches a
 * block as the mapping does, rather than drawing it one metre square.
 *
 * The hand-over: a terrain triangle is cut away when every corner of it lies
 * in a column whose chunks have all arrived (200, or 204), and kept
 * otherwise, so a visitor never falls through a hole. A visitor stands on a
 * chunk's `ground` and `leaves`. What a tile draws standing on its ground,
 * one shape drawn many times (a mesh's thin instances), goes an instance at
 * a time, where the column under it is complete: the blocks show what stands
 * there themselves.
 *
 * The chunks are fetched in the style the ground is drawn in (smoothed, or
 * whole blocks). When the style changes, each chunk drawn stays drawn, stood
 * on and cut under until its chunk in the new style arrives and takes its
 * place, so the ground changes chunk by chunk with no gap.
 *
 * Not yet: blocks past a slot's edge are drawn, not clipped; a neighbouring
 * slot's area is not drawn until the visitor is in it.
 */

import { TransformNode } from '@babylonjs/core/Meshes/transformNode';
import { SubMesh } from '@babylonjs/core/Meshes/subMesh';
import { Matrix, Quaternion, Vector3 } from '@babylonjs/core/Maths/math.vector';
import type { Mesh } from '@babylonjs/core/Meshes/mesh';
import type { AbstractMesh } from '@babylonjs/core/Meshes/abstractMesh';
import type { AssetContainer } from '@babylonjs/core/assetContainer';
import type { Scene } from '@babylonjs/core/scene';
import { areaMap, chunkUrl, gridOfDirection, planetToArea, slotOfGrid, type CubeSphere, type Slot } from './cubeSphere';
import type { Vec3 } from './planetFrame';
import { emptiesAsNodes, holdPlaces, placesOf } from './holdPlaces';
import { retireAfterFrames, retireWhenDrawn } from './retire';
import { compileAhead, pipelineWaiting } from '../../engine/compileAhead';

/** Blocks along a chunk's edge. */
const CHUNK = 16;
/** Columns out from the visitor whose chunks are fetched, without a quality tier: the high tier's. */
export const DEFAULT_CHUNK_RADIUS = 8;
const RADIUS = DEFAULT_CHUNK_RADIUS;
/** Columns past that reach beyond which loaded chunks are let go. */
const KEEP_MARGIN = 3;
/** Chunks fetched at once. */
const PARALLEL = 6;
/** How long an edited chunk being baked again is waited for before it is left to the next time it is drawn, ms. */
const RELOAD_WAIT_MS = 30_000;
/** Blocks under the terrain's lowest point, and over its highest, that a column's chunks cover. */
const BELOW = 3;
const ABOVE = 10;
/** Terrain tiles read into area coordinates per frame. */
const READS_PER_FRAME = 2;
/**
 * How far, in metres, the area's map may shift, and how much its axes may turn, before the chunks are placed by it
 * again: a visitor at rest still stirs by fractions of a millimetre, and a chunk that far off is not one anyone sees.
 */
const HOLD_MOVE_M = 1e-4;
const HOLD_TURN = 1e-7;

/** A terrain tile's drawn meshes: its `ground` and `water`. */
export interface TileSurface {
  url: string;
  meshes: readonly AbstractMesh[];
}

export interface AreaChunksState {
  toScene(p: Vec3): Vec3;
  fromScene(s: Vec3): Vec3;
  /** The visitor's feet in the scene, when there is a visitor. */
  feet: Vec3 | undefined;
  /** Whether blocks are drawn. The planet view keeps them at every zoom, so they never swap for the terrain. */
  active: boolean;
  /** The terrain tiles shown. */
  tiles: readonly TileSurface[];
  /** The style the chunks are fetched in, filling their template's `{style}`; none fills it with nothing. */
  style?: string | undefined;
}

export interface AreaChunks {
  update(state: AreaChunksState): void;
  walkable(): AbstractMesh[];
  /** The water surfaces of the chunks drawn: what a visitor swims under. */
  water(): AbstractMesh[];
  /** Every mesh of the chunks drawn: their blocks, leaves and water. */
  meshes(): AbstractMesh[];
  /** The ground and leaves of the chunks drawn within `radius` of a point in the area. */
  walkableNear(at: readonly [number, number, number], radius: number): AbstractMesh[];
  /**
   * Draw a chunk again, by its slot and lowest corner, because the planet has
   * changed it. The chunk as it was stays drawn until the new one is in. A
   * chunk not drawn, or in another slot, is left alone.
   */
  reload(slot: string, corner: readonly [number, number, number]): Promise<boolean>;
  /** The slot drawn about the visitor, and the node its chunks hang under (its map takes area blocks to the scene). */
  area(): { slot: string; node: TransformNode } | undefined;
  idle(): Promise<void>;
  dispose(): void;
}

export interface AreaChunksOptions {
  scene: Scene;
  surface: CubeSphere;
  radius: number;
  fetchImpl: (url: string) => Promise<Response>;
  loadGlb: (bytes: ArrayBuffer, name: string) => Promise<AssetContainer>;
  warn: (name: string, detail: string) => void;
  /** Columns out from the visitor's whose chunks are fetched: the quality tier's reach. Default RADIUS. */
  chunkRadius?: number;
  /** The clock a failed chunk's next ask is timed by, in milliseconds. Default performance.now. */
  now?: () => number;
  /** Whether a mesh of a chunk drawn again is ready to draw in every pass, so the chunk as it was may go. Default: its material ready, no pipeline building. */
  drawable?: (mesh: AbstractMesh) => boolean;
}

interface Chunk {
  state: 'loading' | 'ready' | 'failed';
  /** For a chunk not there yet (503, 429, any failure but another 4xx), when to ask for it again. */
  retryAt?: number;
  column: number;
  container?: AssetContainer;
  meshes: AbstractMesh[];
  walk: AbstractMesh[];
  /** Its water surfaces, known when it arrives. */
  wet: AbstractMesh[];
  /** Its nodes and meshes, parents first, their world matrices held. */
  places: TransformNode[];
  /** How many times it has been asked to be drawn again: only the newest asking's answer is drawn. */
  redraws?: number;
}

/**
 * A terrain mesh read into the current slot's area coordinates, triangle by
 * triangle: the columns each one lies over, and the heights it spans there.
 */
interface TileRead {
  slot: string;
  full: Uint32Array;
  /** Per triangle, the columns under it: lowest cx, cz, then highest; cx0 is OFF_FACE when it is not on the slot's face. */
  columns: Int32Array;
  /** Per triangle, its lowest and highest block y. */
  heights: Float64Array;
  /** The complete-columns version the mesh's indices were last cut for. */
  cutFor: number;
  /** A mesh of several parts: each part's material index and its run of `full`. */
  parts?: { materialIndex: number; start: number; count: number }[];
}

/** A tile's mesh drawn many times (thin instances): the column under each instance, and each one's matrix as it came. */
interface InstanceRead {
  slot: string;
  /** Per instance, the column under it: cx, cz; cx is OFF_FACE when it is not on the slot's face. */
  columns: Int32Array;
  matrices: Matrix[];
  /** The complete-columns version its instances were last hidden for. */
  cutFor: number;
}

const OFF_FACE = -(2 ** 31);
/**
 * A triangle over more columns than this is too coarse to hand over from: it
 * neither says which chunks a column needs nor is cut. Finer terrain replaces
 * it near the visitor before the blocks are drawn.
 */
const MAX_TRIANGLE_COLUMNS = 16;

const OFFSET = 1 << 15;
const columnKey = (cx: number, cz: number) => (cx + OFFSET) * (1 << 16) + (cz + OFFSET);
const columnXZ = (key: number): [number, number] => [Math.floor(key / (1 << 16)) - OFFSET, (key % (1 << 16)) - OFFSET];

/** The lowest corners' y of the chunks a column with terrain between `min` and `max` needs. */
function levelsFor(min: number, max: number): number[] {
  const low = Math.ceil(min - 0.5) - BELOW, high = Math.floor(max - 0.5) + ABOVE;
  const out: number[] = [];
  for (let y = Math.floor(low / CHUNK) * CHUNK; y <= high; y += CHUNK) out.push(y);
  return out;
}

export function createAreaChunks(o: AreaChunksOptions): AreaChunks {
  const { scene, surface: cs, radius } = o;
  const chunkRadius = o.chunkRadius ?? RADIUS;
  const now = o.now ?? (() => performance.now());
  const keepRadius = chunkRadius + KEEP_MARGIN;
  const node = new TransformNode('planet-area', scene);
  const chunks = new Map<string, Chunk>();
  // Chunks of the style drawn before, each kept drawn until its chunk in the style now arrives.
  const old = new Map<string, Chunk>();
  let style: string | undefined;
  const reads = new WeakMap<AbstractMesh, TileRead>();
  const touched = new Set<AbstractMesh>();
  const instanceReads = new WeakMap<AbstractMesh, InstanceRead>();
  const hidden = new Set<Mesh>();
  const pending = new Set<Promise<unknown>>();
  let slot: Slot | undefined;
  // The map the area's node was last placed by.
  let placedBy: number[] = [];
  let active = false;
  let loading = 0;
  let complete = new Set<number>();
  let completeVersion = 0;
  let heights = new Map<number, [number, number]>();
  let heightsFor = '';

  const dropChunk = (key: string) => {
    const c = chunks.get(key);
    if (!c) return;
    chunks.delete(key);
    c.container?.dispose();
  };
  // An old chunk let go: hidden at once, disposed a few rendered frames later (retire.ts).
  const dropOld = (key: string) => {
    const c = old.get(key);
    old.delete(key);
    if (c?.container) retireAfterFrames(scene, c.container);
  };
  /**
   * A new style: the chunks drawn are kept, as old ones, until each one's
   * chunk in the new style arrives; one not yet arrived is let go, and the
   * old one it was to replace, if any, stays.
   */
  const changeStyle = (next: string | undefined) => {
    style = next;
    for (const [key, c] of [...chunks]) {
      chunks.delete(key);
      if (c.state !== 'ready') {
        c.container?.dispose();
        continue;
      }
      dropOld(key);
      old.set(key, c);
    }
  };

  /** A chunk's meshes, arrived, drawn in the area. */
  const adopt = (c: Chunk, container: AssetContainer) => {
    container.addAllToScene();
    for (const m of container.meshes) {
      if (!m.parent) m.parent = node;
      m.isPickable = false;
      // Drawn once what it is drawn with is built: a chunk of a new kind does not stall the frame.
      compileAhead(m);
      m.setEnabled(active);
    }
    for (const n of container.transformNodes) if (!n.parent) n.parent = node;
    emptiesAsNodes(container, scene);
    // A chunk never moves in its area: its places are worked out here, and again only when the area's node moves.
    c.places = placesOf(container);
    holdPlaces(c.places);
    c.container = container;
    c.meshes = container.meshes;
    c.walk = container.meshes.filter((m) => m.material?.name === 'ground' || m.material?.name === 'leaves');
    for (const m of c.walk) m.checkCollisions = true;
    c.wet = container.meshes.filter((m) => m.material?.name === 'water');
    // The chunks' water first among the see-through, and keeping its depth: the terrain's water under it,
    // drawn after and pushed back, does not show as well (the two together read as a darker band).
    for (const m of container.meshes) {
      if (m.material?.name !== 'water') continue;
      m.alphaIndex = 0;
      m.material.forceDepthWrite = true;
    }
  };

  // Each fetch of a chunk drawn again asks for it afresh, so no cache answers with the chunk as it was.
  let asked = 0;

  /**
   * A chunk that failed as one not there yet is asked for again (planet.md,
   * Answers a shell can rely on): after its Retry-After, or a second, doubling
   * each time up to a minute. A 4xx other than 429 is not asked for again.
   */
  const tries = new Map<string, number>();
  const failed = (key: string, c: Chunk, status: number, retryAfter: string | null) => {
    c.state = 'failed';
    if (status >= 400 && status < 500 && status !== 429) return;
    const n = tries.get(key) ?? 0;
    tries.set(key, n + 1);
    const after = Number(retryAfter);
    c.retryAt = now() + (retryAfter !== null && Number.isFinite(after) && after >= 0 ? after * 1000 : Math.min(60_000, 1000 * 2 ** n));
  };
  const loadChunk = (key: string, column: number, url: string) => {
    const c: Chunk = { state: 'loading', column, meshes: [], walk: [], wet: [], places: [] };
    chunks.set(key, c);
    loading++;
    // The fetch is what is limited (a browser has six connections to a host): its slot is free once the chunk's
    // bytes are in, and the next fetched while this one is made into meshes.
    let fetching = true;
    const fetched = () => {
      if (fetching) loading--;
      fetching = false;
    };
    const p = (async () => {
      try {
        const res = await o.fetchImpl(url);
        if (res.status === 204) {
          c.state = 'ready';
          tries.delete(key);
          return;
        }
        if (!res.ok) {
          failed(key, c, res.status, res.headers.get('retry-after'));
          // A 503 is the planet saying "not there yet, ask again": expected while it bakes, so not a failure to tell of.
          if (res.status !== 503) o.warn('veml:planet:content-failed', `${url}: ${res.status}`);
          return;
        }
        const bytes = await res.arrayBuffer();
        fetched();
        const container = await o.loadGlb(bytes, url);
        if (chunks.get(key) !== c) {
          container.dispose();
          return;
        }
        adopt(c, container);
        c.state = 'ready';
        tries.delete(key);
      } catch (err) {
        // Anything else is a failure, asked for again as a 503 is.
        failed(key, c, 503, null);
        o.warn('veml:planet:content-failed', `${url}: ${String(err)}`);
      } finally {
        fetched();
      }
    })();
    pending.add(p);
    void p.finally(() => pending.delete(p));
  };

  /** A mesh drawn many times: the column under each of its instances, in the slot's area. */
  const readInstances = (mesh: Mesh, s: AreaChunksState, here: Slot) => {
    mesh.computeWorldMatrix(true);
    const world = mesh.getWorldMatrix();
    const matrices = mesh.thinInstanceGetWorldMatrices().map((m) => m.clone());
    // Drawn from a buffer that takes changes: a glTF loader hands instances over in one that does not, and an
    // instance hidden in it would still be drawn.
    const data = new Float32Array(matrices.length * 16);
    matrices.forEach((m, i) => m.copyToArray(data, i * 16));
    mesh.thinInstanceSetBuffer('matrix', data, 16, false);
    const columns = new Int32Array(matrices.length * 2);
    const v = new Vector3();
    matrices.forEach((m, i) => {
      const t = m.getTranslation();
      Vector3.TransformCoordinatesFromFloatsToRef(t.x, t.y, t.z, world, v);
      const a = planetToArea(cs, radius, here, s.fromScene([v.x, v.y, v.z]));
      columns[i * 2] = a ? Math.floor((a[0] + 0.5) / CHUNK) : OFF_FACE;
      columns[i * 2 + 1] = a ? Math.floor((a[2] + 0.5) / CHUNK) : 0;
    });
    instanceReads.set(mesh, { slot: here.key, columns, matrices, cutFor: -1 });
  };

  /** Hide a mesh's instances that stand over complete columns, each at its own place, or stand them all again. */
  const hideInstances = (mesh: Mesh, read: InstanceRead) => {
    if (read.cutFor === completeVersion) return;
    read.cutFor = completeVersion;
    let any = false;
    const n = read.matrices.length;
    read.matrices.forEach((m, i) => {
      const cx = read.columns[i * 2]!;
      const over = cx !== OFF_FACE && complete.has(columnKey(cx, read.columns[i * 2 + 1]!));
      any ||= over;
      mesh.thinInstanceSetMatrixAt(i, over ? Matrix.Compose(Vector3.Zero(), Quaternion.Identity(), m.getTranslation()) : m, i === n - 1);
    });
    if (any) hidden.add(mesh);
    else hidden.delete(mesh);
  };

  /** A terrain mesh's triangles in the slot's area coordinates. */
  const readTile = (mesh: AbstractMesh, s: AreaChunksState, here: Slot): TileRead | undefined => {
    if (((mesh as Mesh).thinInstanceCount ?? 0) > 0) {
      readInstances(mesh as Mesh, s, here);
      return undefined;
    }
    const positions = mesh.getVerticesData('position');
    const indices = mesh.getIndices();
    if (!positions || !indices) return undefined;
    mesh.computeWorldMatrix(true);
    const world = mesh.getWorldMatrix();
    const n = positions.length / 3;
    // Each vertex's area x, y and z; NaN off the slot's face. And where it is in the scene.
    const area = new Float64Array(n * 3);
    const inScene = new Float64Array(n * 3);
    const v = new Vector3();
    for (let i = 0; i < n; i++) {
      Vector3.TransformCoordinatesFromFloatsToRef(positions[i * 3]!, positions[i * 3 + 1]!, positions[i * 3 + 2]!, world, v);
      inScene[i * 3] = v.x;
      inScene[i * 3 + 1] = v.y;
      inScene[i * 3 + 2] = v.z;
      const a = planetToArea(cs, radius, here, s.fromScene([v.x, v.y, v.z]));
      area[i * 3] = a ? a[0] : NaN;
      area[i * 3 + 1] = a ? a[1] : NaN;
      area[i * 3 + 2] = a ? a[2] : NaN;
    }
    const tris = indices.length / 3;
    const columns = new Int32Array(tris * 4);
    const heights = new Float64Array(tris * 2);
    // Each triangle's area bounds: x0, x1, z0, z1.
    const bounds = new Float64Array(tris * 4);
    const spans: number[] = [];
    for (let t = 0; t < tris; t++) {
      let x0 = Infinity, x1 = -Infinity, z0 = Infinity, z1 = -Infinity, y0 = Infinity, y1 = -Infinity;
      for (let c = 0; c < 3; c++) {
        const i = indices[t * 3 + c]! * 3;
        x0 = Math.min(x0, area[i]!);
        x1 = Math.max(x1, area[i]!);
        y0 = Math.min(y0, area[i + 1]!);
        y1 = Math.max(y1, area[i + 1]!);
        z0 = Math.min(z0, area[i + 2]!);
        z1 = Math.max(z1, area[i + 2]!);
      }
      // Math.min and max carry a NaN through: any corner off the face takes the triangle off it.
      if (Number.isNaN(x0 + x1 + y0 + y1 + z0 + z1)) {
        columns[t * 4] = OFF_FACE;
        continue;
      }
      bounds.set([x0, x1, z0, z1], t * 4);
      heights[t * 2] = y0;
      heights[t * 2 + 1] = y1;
      if (spans.length < 4096) spans.push(Math.max(x1 - x0, z1 - z0));
    }
    // A wall (a triangle standing upright, along x or along z) is a side of the cell behind it: the crown or step it
    // closes. It goes with that cell, so its footprint reaches back across the cell, a cell's width (the tile's
    // commonest triangle span). Cut by its own thin footprint, it would go with the cell in front where that one is
    // over complete columns and the cell behind is not, and leave the kept cell open to look into.
    spans.sort((a, b) => a - b);
    const cellWidth = spans.length ? spans[spans.length >> 1]! : 0;
    const normals = cellWidth > 0 ? mesh.getVerticesData('normal') : null;
    for (let t = 0; t < tris; t++) {
      if (columns[t * 4] === OFF_FACE) continue;
      let x0 = bounds[t * 4]!, x1 = bounds[t * 4 + 1]!, z0 = bounds[t * 4 + 2]!, z1 = bounds[t * 4 + 3]!;
      const alongZ = x1 - x0 < cellWidth * 0.05, alongX = z1 - z0 < cellWidth * 0.05;
      if (normals && alongZ !== alongX) {
        // Which way the wall faces, in the area: a quarter metre from its middle along its normal.
        const i = indices[t * 3]!;
        Vector3.TransformNormalFromFloatsToRef(normals[i * 3]!, normals[i * 3 + 1]!, normals[i * 3 + 2]!, world, v);
        v.normalize();
        const mid = (arr: Float64Array, k: number) => (arr[indices[t * 3]! * 3 + k]! + arr[indices[t * 3 + 1]! * 3 + k]! + arr[indices[t * 3 + 2]! * 3 + k]!) / 3;
        const q = planetToArea(cs, radius, here, s.fromScene([mid(inScene, 0) + v.x * 0.25, mid(inScene, 1) + v.y * 0.25, mid(inScene, 2) + v.z * 0.25]));
        if (q) {
          // Back across the cell behind it, and a little past, so a cell that ends on a column's edge still counts it.
          const reach = cellWidth * 1.02;
          if (alongZ) {
            if (q[0] > mid(area, 0)) x0 -= reach;
            else x1 += reach;
          } else if (q[2] > mid(area, 2)) z0 -= reach;
          else z1 += reach;
        }
      }
      columns[t * 4] = Math.floor((x0 + 0.5) / CHUNK);
      columns[t * 4 + 1] = Math.floor((z0 + 0.5) / CHUNK);
      columns[t * 4 + 2] = Math.floor((x1 + 0.5) / CHUNK);
      columns[t * 4 + 3] = Math.floor((z1 + 0.5) / CHUNK);
    }
    // A mesh of several parts (a tile's pictures): each part's material and its run of the indices, kept apart through every cut.
    const parts = mesh.subMeshes && mesh.subMeshes.length > 1 ? mesh.subMeshes.map((p) => ({ materialIndex: p.materialIndex, start: p.indexStart, count: p.indexCount })) : undefined;
    const read: TileRead = { slot: here.key, full: Uint32Array.from(indices), columns, heights, cutFor: 0, ...(parts ? { parts } : {}) };
    reads.set(mesh, read);
    return read;
  };

  /** Cut a terrain mesh's triangles that lie wholly over complete columns, or make it whole again. */
  const cut = (mesh: AbstractMesh, read: TileRead) => {
    if (read.cutFor === completeVersion) return;
    read.cutFor = completeVersion;
    const { full, columns } = read;
    const kept: number[] = [];
    // Cut only where every column under a triangle has its chunks, so nobody falls through a hole and no
    // ground shows through a gap in the water. Where the terrain's water and the chunks' both lie, the
    // chunks' is drawn first and keeps its depth (loadChunk), so only it shows.
    const over = (t: number): boolean => {
      const cx0 = columns[t * 4]!;
      if (cx0 === OFF_FACE || complete.size === 0) return false;
      const cz0 = columns[t * 4 + 1]!, cx1 = columns[t * 4 + 2]!, cz1 = columns[t * 4 + 3]!;
      if ((cx1 - cx0 + 1) * (cz1 - cz0 + 1) > MAX_TRIANGLE_COLUMNS) return false;
      for (let cx = cx0; cx <= cx1; cx++) for (let cz = cz0; cz <= cz1; cz++) if (!complete.has(columnKey(cx, cz))) return false;
      return true;
    };
    // Each part's kept indices in turn, so the parts stay runs of the cut indices.
    const runs = read.parts ?? [{ materialIndex: 0, start: 0, count: full.length }];
    const keptPer = runs.map(() => 0);
    runs.forEach((p, n) => {
      for (let t = p.start / 3; t < (p.start + p.count) / 3; t++) {
        if (over(t)) continue;
        kept.push(full[t * 3]!, full[t * 3 + 1]!, full[t * 3 + 2]!);
        keptPer[n]! += 3;
      }
    });
    // A mesh needs at least one triangle; a degenerate one draws nothing and is never hit.
    if (kept.length === 0) kept.push(0, 0, 0);
    (mesh as AbstractMesh & { setIndices(i: number[]): void }).setIndices(kept);
    if (read.parts && kept.length > 3) {
      const verts = mesh.getTotalVertices();
      mesh.subMeshes = [];
      let start = 0;
      read.parts.forEach((p, n) => {
        if (keptPer[n]! > 0) new SubMesh(p.materialIndex, 0, verts, start, keptPer[n]!, mesh);
        start += keptPer[n]!;
      });
      // A new part's bounds are in the mesh's own frame until the mesh's place is worked out again, which for a tile
      // held in place is not until the origin moves: carried to where it is drawn now, or the view culls it unseen.
      const world = mesh.getWorldMatrix();
      for (const s of mesh.subMeshes) s.updateBoundingInfo(world);
    }
    if (kept.length === full.length) touched.delete(mesh);
    else touched.add(mesh);
  };

  const setComplete = (next: Set<number>) => {
    if (next.size === complete.size && [...next].every((k) => complete.has(k))) return;
    complete = next;
    completeVersion++;
  };

  const restore = () => {
    setComplete(new Set());
    for (const m of [...hidden]) {
      const r = instanceReads.get(m);
      if (r && !m.isDisposed()) hideInstances(m, r);
      else hidden.delete(m);
    }
    for (const m of [...touched]) {
      const r = reads.get(m);
      if (r && !m.isDisposed()) cut(m, r);
      else touched.delete(m);
    }
  };

  const setActive = (on: boolean) => {
    if (active === on) return;
    active = on;
    for (const c of [...chunks.values(), ...old.values()]) for (const m of c.meshes) m.setEnabled(on);
  };
  /** A part of each chunk drawn: this style's that have arrived, and the old style's still standing in. */
  const ofDrawn = (part: (c: Chunk) => AbstractMesh[]): AbstractMesh[] => {
    const out: AbstractMesh[] = [];
    for (const c of chunks.values()) if (c.state === 'ready') out.push(...part(c));
    for (const c of old.values()) out.push(...part(c));
    return out;
  };

  return {
    update(s) {
      const here = s.active && s.feet ? s.fromScene(s.feet) : undefined;
      const g = here ? gridOfDirection(cs.faceBlocks, here) : undefined;
      const next = g ? slotOfGrid(cs, g.face, g.gx, g.gz) : undefined;
      if (!here || !next || !cs.areas.has(next.key)) {
        setActive(false);
        restore();
        return;
      }
      if (slot?.key !== next.key) {
        for (const k of [...chunks.keys()]) dropChunk(k);
        for (const k of [...old.keys()]) dropOld(k);
        restore();
        slot = next;
      }
      if (s.style !== style) changeStyle(s.style);
      const at = planetToArea(cs, radius, slot, here)!;
      // The area's map about the visitor: while it holds (they stand still, the origin stays), so do the chunks' places.
      const map = areaMap(cs, radius, slot, at, s.toScene);
      if (map.some((v, i) => !(Math.abs(v - placedBy[i]!) <= (i >= 12 ? HOLD_MOVE_M : HOLD_TURN)))) {
        placedBy = map;
        node.setPreTransformMatrix(Matrix.FromArray(map));
        node.computeWorldMatrix(true);
        for (const c of [...chunks.values(), ...old.values()]) holdPlaces(c.places);
      }
      setActive(true);

      // Read the terrain near the visitor into area coordinates, nearest first.
      const reach = (keepRadius + 1) * CHUNK;
      const feet = new Vector3(...s.feet!);
      const unread: [number, AbstractMesh][] = [];
      for (const t of s.tiles)
        for (const m of t.meshes) {
          const r = reads.get(m) ?? instanceReads.get(m);
          if (r && r.slot === slot.key) continue;
          const b = m.getBoundingInfo().boundingSphere;
          const d = Vector3.Distance(b.centerWorld, feet) - b.radiusWorld;
          if (d < reach) unread.push([d, m]);
        }
      unread.sort((a, b) => a[0] - b[0]);
      for (const [, m] of unread.slice(0, READS_PER_FRAME)) readTile(m, s, slot);

      // Each column's terrain heights near the visitor, from the triangles of the tiles shown
      // over it, worked out again only when the visitor changes column or the tiles change.
      const fx = Math.floor((at[0] + 0.5) / CHUNK), fz = Math.floor((at[2] + 0.5) / CHUNK);
      const shownReads: TileRead[] = [];
      const ids: number[] = [];
      for (const t of s.tiles)
        for (const m of t.meshes) {
          const r = reads.get(m);
          if (r && r.slot === slot.key) {
            shownReads.push(r);
            ids.push(m.uniqueId);
          }
        }
      const signature = `${fx},${fz}:${ids.join(',')}`;
      if (signature !== heightsFor) {
        heightsFor = signature;
        heights = new Map();
        for (const r of shownReads) {
          for (let t = 0; t < r.full.length / 3; t++) {
            const cx0 = r.columns[t * 4]!;
            if (cx0 === OFF_FACE || (r.columns[t * 4 + 2]! - cx0 + 1) * (r.columns[t * 4 + 3]! - r.columns[t * 4 + 1]! + 1) > MAX_TRIANGLE_COLUMNS) continue;
            const lx = Math.max(cx0, fx - keepRadius), hx = Math.min(r.columns[t * 4 + 2]!, fx + keepRadius);
            const lz = Math.max(r.columns[t * 4 + 1]!, fz - keepRadius), hz = Math.min(r.columns[t * 4 + 3]!, fz + keepRadius);
            const y0 = r.heights[t * 2]!, y1 = r.heights[t * 2 + 1]!;
            for (let cx = lx; cx <= hx; cx++)
              for (let cz = lz; cz <= hz; cz++) {
                const k = columnKey(cx, cz);
                const cur = heights.get(k);
                if (!cur) heights.set(k, [y0, y1]);
                else {
                  if (y0 < cur[0]) cur[0] = y0;
                  if (y1 > cur[1]) cur[1] = y1;
                }
              }
          }
        }
      }

      // Ask for what is missing around the visitor, nearest first; let go of what is far.
      const want: [number, string, number, string][] = [];
      const nextComplete = new Set<number>();
      for (const [col, h] of heights) {
        const [cx, cz] = columnXZ(col);
        const d2 = (cx - fx) ** 2 + (cz - fz) ** 2;
        if (d2 > keepRadius * keepRadius) continue;
        let all = true;
        for (const y of levelsFor(h[0], h[1])) {
          // Three times as far up and down as across: a coarse tile's triangle, or the ground seen from high over it,
          // can span kilometres, and every chunk between would be asked for; a real cliff beside the visitor is far
          // shorter. The column is not complete without them, so the terrain over it stays.
          if (Math.abs(y + CHUNK / 2 - at[1]) > 3 * (chunkRadius + 1) * CHUNK) {
            all = false;
            continue;
          }
          const key = `${cx * CHUNK}_${y}_${cz * CHUNK}`;
          let c = chunks.get(key);
          // A failed chunk whose wait is over is asked for again.
          if (c?.state === 'failed' && c.retryAt !== undefined && now() >= c.retryAt) {
            dropChunk(key);
            c = undefined;
          }
          // The old style's chunk stands in until this one arrives, and while it fails.
          const standing = old.has(key);
          if (!c) {
            if (!standing) all = false;
            if (d2 <= chunkRadius * chunkRadius) want.push([d2, key, col, chunkUrl(cs, slot, cx * CHUNK, y, cz * CHUNK, style)!]);
          } else if (c.state !== 'ready' && !standing) all = false;
        }
        if (all) nextComplete.add(col);
      }
      want.sort((a, b) => a[0] - b[0]);
      for (const [, key, col, url] of want) {
        if (loading >= PARALLEL) break;
        loadChunk(key, col, url);
      }
      for (const [key, c] of chunks) {
        const [cx, cz] = columnXZ(c.column);
        if ((cx - fx) ** 2 + (cz - fz) ** 2 > keepRadius * keepRadius && c.state !== 'loading') dropChunk(key);
      }
      // An old style's chunk goes once its chunk in the new style has arrived, never while it fails (the column was
      // counted complete for it above, and the terrain under it stays cut), or when it is far: here, in the frame,
      // never as a fetch ends. It is hidden now and disposed a few frames on (dropOld):
      // disposed at once, many in a frame as a style changes, WebGPU drew a frame with materials gone and stopped drawing.
      for (const [key, c] of old) {
        const [cx, cz] = columnXZ(c.column);
        const replaced = chunks.get(key);
        if (replaced?.state === 'ready' || (cx - fx) ** 2 + (cz - fz) ** 2 > keepRadius * keepRadius) dropOld(key);
      }

      // The hand-over.
      setComplete(nextComplete);
      for (const t of s.tiles)
        for (const m of t.meshes) {
          const r = reads.get(m);
          if (r && r.slot === slot.key) cut(m, r);
          const ir = instanceReads.get(m);
          if (ir && ir.slot === slot.key) hideInstances(m as Mesh, ir);
        }
      for (const m of [...hidden]) {
        const r = instanceReads.get(m);
        if (m.isDisposed() || !r) hidden.delete(m);
        else hideInstances(m, r);
      }
      for (const m of [...touched]) {
        if (m.isDisposed()) touched.delete(m);
        else {
          const r = reads.get(m);
          if (r) cut(m, r);
        }
      }
    },
    water() {
      return active ? ofDrawn((c) => c.wet) : [];
    },
    meshes() {
      return active ? ofDrawn((c) => c.meshes) : [];
    },
    walkableNear(at, radius) {
      const out: AbstractMesh[] = [];
      if (!active) return out;
      for (let x = Math.floor((at[0] - radius) / 16) * 16; x <= at[0] + radius; x += 16)
        for (let y = Math.floor((at[1] - radius) / 16) * 16; y <= at[1] + radius; y += 16)
          for (let z = Math.floor((at[2] - radius) / 16) * 16; z <= at[2] + radius; z += 16) {
            const key = `${x}_${y}_${z}`;
            const c = chunks.get(key);
            const drawn = c?.state === 'ready' ? c : old.get(key);
            if (drawn) out.push(...drawn.walk);
          }
      return out;
    },
    async reload(key, [x, y, z]) {
      const c = chunks.get(`${x}_${y}_${z}`);
      if (!slot || slot.key !== key || !c || c.state === 'loading') return false;
      const here = slot;
      const mine = (c.redraws = (c.redraws ?? 0) + 1);
      // In the style the chunk is drawn in now, so an edit in the blocks style is drawn in blocks.
      const url = chunkUrl(cs, here, x, y, z, style)!;
      try {
        // A chunk the planet is baking again is "not there yet" (503): asked again after its Retry-After, for half a
        // minute, while it is still this area's and still drawn; given up on, the edit would never be drawn.
        let res = await o.fetchImpl(`${url}${url.includes('?') ? '&' : '?'}v=${++asked}`);
        for (const until = now() + RELOAD_WAIT_MS; res.status === 503 && now() < until; ) {
          const after = Number(res.headers.get('retry-after') ?? 1);
          await new Promise((r) => setTimeout(r, (Number.isFinite(after) && after >= 0 ? after : 1) * 1000));
          if (chunks.get(`${x}_${y}_${z}`) !== c || slot !== here || c.redraws !== mine) return false;
          res = await o.fetchImpl(`${url}${url.includes('?') ? '&' : '?'}v=${++asked}`);
        }
        if (!res.ok) return false;
        const container = res.status === 204 ? undefined : await o.loadGlb(await res.arrayBuffer(), url);
        // Gone meanwhile, another area's now, or asked again since: the newer asking's answer is the one drawn.
        if (chunks.get(`${x}_${y}_${z}`) !== c || slot !== here || c.redraws !== mine) {
          container?.dispose();
          return false;
        }
        const old = c.container;
        c.container = undefined;
        c.meshes = [];
        c.walk = [];
        c.wet = [];
        c.places = [];
        if (container) adopt(c, container);
        // The chunk as it was stays drawn until the new one has drawn, so no frame goes without it.
        if (old && container) retireWhenDrawn(scene, old, container.meshes, o.drawable ?? ((m) => m.isReady(true) && !pipelineWaiting(m)));
        else if (old) retireAfterFrames(scene, old);
        return true;
      } catch (err) {
        o.warn('veml:planet:content-failed', `${url}: ${String(err)}`);
        return false;
      }
    },
    area() {
      return slot && active ? { slot: slot.key, node } : undefined;
    },
    walkable() {
      return active ? ofDrawn((c) => c.walk) : [];
    },
    async idle() {
      while (pending.size > 0) await Promise.allSettled([...pending]);
    },
    dispose() {
      for (const k of [...chunks.keys()]) dropChunk(k);
      for (const k of [...old.keys()]) dropOld(k);
      node.dispose();
    },
  };
}
