/**
 * The planet description (specs/veml/profiles/planet.md, The planet
 * description): the JSON a `planet:planet` names. Fields it does not know
 * are ignored. The terrain stays on the description's own origin; sites are
 * includes, and may be anywhere.
 *
 * A host may serve its ground in several styles (smoothed, whole blocks):
 * the description lists them, its own first, and its terrain and surface
 * scheme name their content with a `{style}` template, which the shell
 * fills with the style it draws (terrainStyleOf).
 */

import type { VemlPlanetSite } from '../../veml/documentModel';
import { planetNumber, readSite } from '../../veml/planetValues';
import { resolveWorldUri } from '../../veml/uriResolve';

export interface PlanetDescription {
  seaLevel?: number;
  floor?: number;
  /** The terrain tileset's URL, absolute; a `{style}` in it is filled with the style drawn (withStyle). */
  terrain: string;
  /** The styles the host serves its ground in, its own first; none when it names none. */
  styles: string[];
  /** The surface scheme and its own fields, when one is named. */
  surface?: { scheme: string } & Record<string, unknown>;
  sites: VemlPlanetSite[];
}

export type PlanetDescriptionResult =
  | { ok: true; description: PlanetDescription; warnings: string[] }
  | { ok: false; reason: string };

const originOf = (url: string): string | undefined => {
  try {
    return new URL(url).origin;
  } catch {
    return undefined;
  }
};

/** The most sites read from a description: past them, the rest are passed over with a warning. */
const MAX_SITES = 100_000;

/** A style's name: lower-case words joined by hyphens. */
const STYLE_NAME = /^[a-z][a-z0-9]*(-[a-z0-9]+)*$/;

/**
 * The style the ground is drawn in: the visitor's choice, or on `auto` the
 * one the world asks for (its `planet.terrain-style` hint), where the host
 * serves it; else the host's own; none where the host names none.
 */
export function terrainStyleOf(asked: string | null | undefined, styles: readonly string[], visitor = 'auto'): string | undefined {
  const wanted = visitor === 'auto' ? asked : visitor;
  return styles.find((s) => s === wanted) ?? styles[0];
}

/** A URL or template with its `{style}` filled, as written or as URL resolution escaped it in a path; none fills it with nothing. */
export const withStyle = (url: string, style: string | undefined): string => url.replace(/{style}|%7Bstyle%7D/gi, style ?? '');

export function readPlanetDescription(json: unknown, url: string): PlanetDescriptionResult {
  if (!json || typeof json !== 'object' || Array.isArray(json)) return { ok: false, reason: 'veml:planet:description-unavailable' };
  const d = json as Record<string, unknown>;
  if (d.format !== 'planet/1') return { ok: false, reason: typeof d.format === 'string' ? 'veml:planet:unknown-format' : 'veml:planet:description-unavailable' };
  if (typeof d.terrain !== 'string' || d.terrain.length === 0) return { ok: false, reason: 'veml:planet:description-unavailable' };
  const terrain = resolveWorldUri(d.terrain, url);
  if (originOf(terrain) === undefined || originOf(terrain) !== originOf(url)) return { ok: false, reason: 'veml:planet:other-origin' };
  const warnings: string[] = [];
  const description: PlanetDescription = { terrain, styles: [], sites: [] };
  const seaLevel = planetNumber(d.seaLevel as number | undefined);
  if (seaLevel !== undefined) description.seaLevel = seaLevel;
  const floor = planetNumber(d.floor as number | undefined);
  if (floor !== undefined) description.floor = floor;
  if (d.surface && typeof d.surface === 'object' && typeof (d.surface as { scheme?: unknown }).scheme === 'string') {
    description.surface = d.surface as PlanetDescription['surface'];
  }
  if (Array.isArray(d.styles)) {
    for (const s of d.styles) if (typeof s === 'string' && STYLE_NAME.test(s) && !description.styles.includes(s)) description.styles.push(s);
  }
  if (Array.isArray(d.sites)) {
    if (d.sites.length > MAX_SITES) warnings.push('veml:planet:too-many-sites');
    for (const s of d.sites.slice(0, MAX_SITES)) {
      const site = s && typeof s === 'object' ? readSite(s as Record<string, unknown>, url) : undefined;
      if (site) description.sites.push(site);
      else warnings.push('veml:planet:invalid-site');
    }
  }
  return { ok: true, description, warnings };
}
